class Team {                                                 // declares the Team class
    private final List<String> members = new ArrayList<>();  // creates an empty ArrayList named members
    public List<String> getMembers() { return members; }     // leaks internals
    public List<String> getMembersSafe() {                   // getter
        return Collections.unmodifiableList(members);        // returns the result to the caller
    }
}
