    public static void main(String[] args) {  // program entry point
        List<String> cities = new ArrayList<>(List.of("Pune", "Agra", "Nashik"));  // creates an ArrayList filled with the listed values

        cities.sort(null);           // null means natural order (A to Z)
        System.out.println(cities);  // prints cities

        cities.sort((a, b) -> b.compareTo(a));  // reverse order (Z to A)
        System.out.println(cities);             // prints cities
