// MASTER PROGRAM: all important ArrayList methods in one program
import java.util.ArrayList;    // imports the ArrayList class
import java.util.Collections;  // imports the Collections class
import java.util.Iterator;     // imports the Iterator class
import java.util.List;         // imports the List class

public class ArrayListMasterDemo {            // class that holds the main method
    public static void main(String[] args) {  // program entry point
        // 1. Create an empty list
        ArrayList<String> forts = new ArrayList<>();  // creates an empty ArrayList named forts

        // 2. Add elements: add, add at index, addAll, addFirst, addLast
        forts.add("Raigad");                                 // adds "Raigad" to the end of the list
        forts.add("Torna");                                  // adds "Torna" to the end of the list
        forts.add(1, "Sinhagad");                            // insert at index 1
        forts.addAll(List.of("Purandar", "Lohagad"));        // add a whole list
        forts.addFirst("Panhala");                           // Java 21
        forts.addLast("Rajgad");                             // Java 21
        System.out.println("2. After adds     : " + forts);  // prints a label followed by the value

        // 3. Read elements: get, getFirst, getLast, size, isEmpty
        System.out.println("3. get(2)         : " + forts.get(2));  // prints the element or value read
        System.out.println("   first / last   : " + forts.getFirst() + " / " + forts.getLast());  // prints the element or value read
        System.out.println("   size / isEmpty : " + forts.size() + " / " + forts.isEmpty());  // prints the number of elements

        // 4. Search: contains, containsAll, indexOf, lastIndexOf
        System.out.println("4. contains Torna : " + forts.contains("Torna"));  // prints whether the element is present
        System.out.println("   containsAll    : " + forts.containsAll(List.of("Torna", "Raigad")));  // prints whether the element is present
        System.out.println("   indexOf Torna  : " + forts.indexOf("Torna"));  // prints the index of the element
        System.out.println("   lastIndexOf    : " + forts.lastIndexOf("Torna"));  // prints the index of the element

        // 5. Change: set and replaceAll
        forts.set(0, "Panhalgad");                          // replace index 0
        forts.replaceAll(f -> f.toUpperCase());             // change every element
        System.out.println("5. After changes : " + forts);  // prints a label followed by the value

        // 6. Sort and reorder: sort, reverse, swap
        forts.sort(null);                                    // A to Z
        System.out.println("6. Sorted         : " + forts);  // prints a label followed by the value
        Collections.reverse(forts);                          // reverses the order of the elements
        Collections.swap(forts, 0, 1);                       // swaps two elements
        System.out.println("   Reversed+swap  : " + forts);  // prints a label followed by the value

        // 7. Part of the list and conversions: subList, toArray, stream
        System.out.println("7. subList(0, 2)  : " + forts.subList(0, 2));  // prints the selected range
        String[] array = forts.toArray(new String[0]);  // stores the result: copies the elements into an array
        System.out.println("   array length   : " + array.length);  // prints a label followed by the value
        System.out.println("   starts with R  : " + forts.stream().filter(f -> f.startsWith("R")).toList());  // prints a label followed by the value

        // 8. Loop: for-each, iterator (safe remove), forEach
        for (String fort : forts) {                         // loops over every element of forts
            System.out.print(fort + " ");                   // prints the result
        }
        System.out.println();                               // prints an empty line
        Iterator<String> it = forts.iterator();             // stores the result: gets an iterator to walk the elements
        while (it.hasNext()) {                              // runs while the iterator has more elements
            if (it.next().startsWith("P")) {                // checks the condition
                it.remove();                                // safe removal while looping
            }
        }
        forts.forEach(f -> System.out.print(f.charAt(0)));  // runs the given action for every element
        System.out.println();                               // prints an empty line

        // 9. Remove: remove by index, remove by value, removeIf, removeFirst, removeLast
        forts.remove(0);                                     // removes the element at index 0
        forts.remove("TORNA");                               // removes "TORNA" from the list
        forts.removeIf(f -> f.startsWith("L"));              // removes every element that matches the condition
        System.out.println("9. After removes  : " + forts);  // prints a label followed by the value
        if (!forts.isEmpty()) {                              // checks whether it is empty
            forts.removeFirst();                             // removes the first element
        }
        if (!forts.isEmpty()) {                              // checks whether it is empty
            forts.removeLast();                              // removes the last element
        }

        // 10. Copy and compare: copy constructor, equals
        List<String> copy = new ArrayList<>(forts);  // creates an ArrayList named copy copied from forts
        System.out.println("10. copy equals   : " + copy.equals(forts));  // prints the comparison result

        // 11. Clear everything
        forts.clear();  // removes every element from the list
        System.out.println("11. After clear   : " + forts + " size=" + forts.size());  // prints the number of elements
    }
}
// OUTPUT:
// 2. After adds     : [Panhala, Raigad, Sinhagad, Torna, Purandar, Lohagad, Rajgad]
// 3. get(2)         : Sinhagad
//    first / last   : Panhala / Rajgad
//    size / isEmpty : 7 / false
// 4. contains Torna : true
//    containsAll    : true
//    indexOf Torna  : 3
//    lastIndexOf    : 3
// 5. After changes : [PANHALGAD, RAIGAD, SINHAGAD, TORNA, PURANDAR, LOHAGAD, RAJGAD]
// 6. Sorted         : [LOHAGAD, PANHALGAD, PURANDAR, RAIGAD, RAJGAD, SINHAGAD, TORNA]
//    Reversed+swap  : [SINHAGAD, TORNA, RAJGAD, RAIGAD, PURANDAR, PANHALGAD, LOHAGAD]
// 7. subList(0, 2)  : [SINHAGAD, TORNA]
