// ArrayList.sort(Comparator): in place sorting
import java.util.*;  // imports every class of java.util

public class ALSortMethodDemo {                                // class that holds the main method
    public static void main(String[] args) throws Exception {  // program entry point
        List<String> forts = new ArrayList<>(List.of("Sinhagad", "Raigad", "Torna", "Pratapgad"));  // creates an ArrayList filled with the listed values
        forts.sort(null);                                      // null means natural order (A to Z)
        System.out.println("A to Z   : " + forts);             // prints a label followed by the value
        forts.sort(Comparator.comparing(String::length));      // shortest name first, equal lengths keep old order
        System.out.println("By length: " + forts);             // prints a label followed by the value
        forts.sort(Comparator.reverseOrder());                 // Z to A
        System.out.println("Z to A   : " + forts);             // prints a label followed by the value
    }
}
// OUTPUT:
// A to Z   : [Pratapgad, Raigad, Sinhagad, Torna]
// By length: [Torna, Raigad, Sinhagad, Pratapgad]
// Z to A   : [Torna, Sinhagad, Raigad, Pratapgad]

