// Sort objects by one field, then another
import java.util.*;  // imports every class of java.util

public class ALComparatorChainDemo {  // class that holds the main method
    record Fort(String name, String district, int height) { }

    public static void main(String[] args) throws Exception {  // program entry point
        List<Fort> forts = new ArrayList<>();                  // creates an empty ArrayList named forts
        forts.add(new Fort("Raigad", "Raigad", 1356));         // adds new Fort("Raigad", "Raigad", 1356) to the end of the list
        forts.add(new Fort("Torna", "Pune", 1403));            // adds new Fort("Torna", "Pune", 1403) to the end of the list
        forts.add(new Fort("Sinhagad", "Pune", 1312));         // adds new Fort("Sinhagad", "Pune", 1312) to the end of the list
        forts.add(new Fort("Pratapgad", "Satara", 1076));      // adds new Fort("Pratapgad", "Satara", 1... to the end of the list
        // district A to Z, and inside one district the tallest fort first
        forts.sort(Comparator.comparing(Fort::district)
                .thenComparing(Fort::height, Comparator.reverseOrder()));
        for (Fort f : forts) {      // loops over every element of forts
            System.out.println(f);  // prints f
        }
    }
}
// OUTPUT:
