        List<String> route = new ArrayList<>(List.of("Pune", "Satara", "Kolhapur", "Belgaum"));  // creates an ArrayList filled with the listed values
        System.out.println("Outward route : " + route);        // prints a label followed by the value
        List<String> view = route.reversed();                  // Java 21: a view, the list is not changed
        System.out.println("reversed() view: " + view + " | list still " + route);  // prints a label followed by the value
