import java.util.*;  // imports every class of java.util

public class ALShuffleDemo {                                   // class that holds the main method
    public static void main(String[] args) throws Exception {  // program entry point
        List<String> forts = new ArrayList<>(List.of("Raigad", "Sinhagad", "Torna", "Pratapgad", "Lohagad"));  // creates an ArrayList filled with the listed values
        Collections.shuffle(forts, new Random(1));             // seed 1: same mix on every run
        System.out.println("Shuffled once : " + forts);        // prints a label followed by the value
        Collections.shuffle(forts, new Random(1));             // shuffling the mixed list again with seed 1
        System.out.println("Shuffled again: " + forts);        // prints a label followed by the value
        Collections.sort(forts);                               // back to a known order
        System.out.println("Sorted        : " + forts);        // prints a label followed by the value
    }
}
// OUTPUT:
// Shuffled once : [Torna, Pratapgad, Sinhagad, Lohagad, Raigad]
// Shuffled again: [Sinhagad, Lohagad, Pratapgad, Raigad, Torna]
// Sorted        : [Lohagad, Pratapgad, Raigad, Sinhagad, Torna]

