public class ALBinarySearchDemo {                               // class that holds the main method
    public static void main(String[] args) throws Exception {   // program entry point
        List<Integer> heights = new ArrayList<>(List.of(1403, 1126, 1356, 1450, 1076));  // creates an ArrayList filled with the listed values
