// anyMatch, allMatch, noneMatch and count
import java.util.*;         // imports every class of java.util
import java.util.stream.*;  // imports every class of java.util.stream

public class ALMatchCountDemo {                                // class that holds the main method
    public static void main(String[] args) throws Exception {  // program entry point
        List<Integer> heights = List.of(1312, 1356, 1403, 1033);  // heights is an immutable list of the listed values
        System.out.println("Any above 1400?    " + heights.stream().anyMatch(h -> h > 1400));  // true
