// Real-time: pagination with subList
import java.util.*;  // imports every class of java.util

public class ALPagingDemo {                                    // class that holds the main method
    public static void main(String[] args) throws Exception {  // program entry point
        List<String> forts = new ArrayList<>();                // creates an empty ArrayList named forts
        String[] names = {"Raigad", "Sinhagad", "Torna", "Pratapgad", "Lohagad", "Visapur", "Rajgad", "Purandar", "Shivneri", "Panhala"};  // stores the value in names
        forts.addAll(Arrays.asList(names));                    // adds every element of Arrays.asList(names) to the list
        int pageSize = 4;                                      // declares int pageSize with value 4
        int pages = (forts.size() + pageSize - 1) / pageSize;  // round up
        for (int page = 1; page <= pages; page++) {            // counting loop
            int from = (page - 1) * pageSize;                  // declares int from with value (page - 1) * pageSi...
            int to = Math.min(from + pageSize, forts.size());  // last page may be shorter
            System.out.println("Page " + page + "/" + pages + ": " + forts.subList(from, to));  // prints the selected range
        }
    }
}
// OUTPUT:
// Page 1/3: [Raigad, Sinhagad, Torna, Pratapgad]
// Page 2/3: [Lohagad, Visapur, Rajgad, Purandar]
// Page 3/3: [Shivneri, Panhala]

// Sample project: fort ticket counter report (ArrayList)
import java.util.*;         // imports every class of java.util
import java.util.stream.*;  // imports every class of java.util.stream

public class ALTicketReportProject {  // class that holds the main method
    // one ticket sale: tickets cost Rs 100 each
    record Sale(String visitor, String city, int tickets, boolean refunded) {  // declares the Sale record
        int amount() {             // method amount()
            return tickets * 100;  // returns the result to the caller
        }
    }

    public static void main(String[] args) throws Exception {  // program entry point
        List<Sale> sales = new ArrayList<>();                  // Step 1: record the sales
        sales.add(new Sale("Amit", "Pune", 3, false));         // adds new Sale("Amit", "Pune", 3, false) to the end of the list
        sales.add(new Sale("Neha", "Nashik", 5, false));       // adds new Sale("Neha", "Nashik", 5, fal... to the end of the list
        sales.add(new Sale("Ravi", "Pune", 2, true));          // refunded later
        sales.add(new Sale("Sita", "Satara", 4, false));       // adds new Sale("Sita", "Satara", 4, fal... to the end of the list
        sales.add(new Sale("Omkar", "Pune", 6, false));        // adds new Sale("Omkar", "Pune", 6, fals... to the end of the list
        sales.add(new Sale("Kiran", "Nashik", 1, false));      // adds new Sale("Kiran", "Nashik", 1, fa... to the end of the list

        System.out.println("== All sales, largest first ==");  // Step 2: sort
        List<Sale> sorted = new ArrayList<>(sales);            // creates an ArrayList named sorted copied from sales
        sorted.sort(Comparator.comparingInt(Sale::amount).reversed());  // sorts using the given comparator
        for (Sale s : sorted) {                                // loops over every element of sorted
            System.out.println(s.visitor() + " (" + s.city() + ") Rs " + s.amount());  // prints the result
        }

        System.out.println("== Finding ==");                  // Step 3: find
        Sale biggest = Collections.max(sales, Comparator.comparingInt(Sale::amount));  // stores the value in biggest
        System.out.println("Biggest sale : " + biggest.visitor() + " Rs " + biggest.amount());  // prints a label followed by the value
        String firstNashik = sales.stream().filter(s -> s.city().equals("Nashik"))
                .map(Sale::visitor).findFirst().orElse("nobody");
        System.out.println("First Nashik : " + firstNashik);  // prints a label followed by the value
        long puneCount = sales.stream().filter(s -> s.city().equals("Pune")).count();  // stores the result: creates a stream of the elements
        System.out.println("Pune sales   : " + puneCount);    // prints a label followed by the value

        System.out.println("== Revenue by city ==");           // Step 4: group
        Map<String, Integer> byCity = new TreeMap<>();         // creates an empty TreeMap named byCity
        for (Sale s : sales) {                                 // loops over every element of sales
            byCity.merge(s.city(), s.amount(), Integer::sum);  // combines the old and new value for the key
        }
        byCity.forEach((city, sum) -> System.out.println(city + ": Rs " + sum));  // runs the given action for every element

        sales.removeIf(Sale::refunded);  // Step 5: drop refunds
        int total = sales.stream().mapToInt(Sale::amount).sum();  // stores the result: creates a stream of the elements
        System.out.println("Final total after refunds: Rs " + total + " from " + sales.size() + " sales");  // prints the number of elements
    }
}
// OUTPUT:
// == All sales, largest first ==
// Omkar (Pune) Rs 600
// Neha (Nashik) Rs 500
// Sita (Satara) Rs 400
// Amit (Pune) Rs 300
// Ravi (Pune) Rs 200
// Kiran (Nashik) Rs 100
// == Finding ==
// Biggest sale : Omkar Rs 600
// First Nashik : Neha
// Pune sales   : 3
// == Revenue by city ==
// Nashik: Rs 600
// Pune: Rs 1100
// Satara: Rs 400
// Final total after refunds: Rs 1900 from 5 sales

