    static void print(String title, List<Booking> list) {  // method print()
        System.out.println("--- " + title + " (" + list.size() + ") ---");  // prints the number of elements
        for (int i = 0; i < list.size(); i++) {            // loops through all the indexes
            Booking b = list.get(i);                       // stores the result: reads the element at index i
            System.out.println((i + 1) + ". " + b.fort() + " | " + b.customerCity() + " | " + b.people() + " people");  // prints the result
        }
    }

    public static void main(String[] args) {         // program entry point
        List<Booking> bookings = new ArrayList<>();  // creates an empty ArrayList named bookings

        // 1. New bookings arrive one by one
        bookings.add(new Booking("Pune", "Raigad", 4));        // adds new Booking("Pune", "Raigad", 4) to the end of the list
        bookings.add(new Booking("Mumbai", "Torna", 2));       // adds new Booking("Mumbai", "Torna", 2) to the end of the list
        bookings.add(new Booking("Nashik", "Lohagad", 6));     // adds new Booking("Nashik", "Lohagad",... to the end of the list
        bookings.add(new Booking("Nagpur", "Raigad", 3));      // adds new Booking("Nagpur", "Raigad", 3) to the end of the list
        bookings.add(new Booking("Kolhapur", "Panhala", 5));   // adds new Booking("Kolhapur", "Panhala"... to the end of the list
        bookings.add(0, new Booking("Delhi", "Sinhagad", 8));  // a VIP group goes to the top
        print("After booking", bookings);                      // calls the print() method

        // 2. Find a booking and change its fort
        int position = -1;                           // declares int position with value -1
        for (int i = 0; i < bookings.size(); i++) {  // loops through all the indexes
            if (bookings.get(i).customerCity().equals("Mumbai")) {  // checks the condition
                position = i;                        // assigns a new value to position
            }
        }
        Booking old = bookings.get(position);        // stores the result: reads the element at index position
        bookings.set(position, new Booking(old.customerCity(), "Purandar", old.people()));  // customer changed the fort
        System.out.println("Mumbai booking moved to " + bookings.get(position).fort());  // prints the element or value read

        // 3. Cancel every Raigad booking
        boolean cancelled = bookings.removeIf(b -> b.fort().equals("Raigad"));  // stores the result: removes every element that matches the condition
        System.out.println("Raigad cancelled: " + cancelled);  // prints a label followed by the value

        // 4. Sort by fort name, then by group size (largest first)
        bookings.sort(Comparator.comparing(Booking::fort).thenComparing(Comparator.comparingInt(Booking::people).reversed()));  // sorts using the given comparator
        print("Sorted", bookings);  // calls the print() method

        // 5. Show the list two bookings per page
        int pageSize = 2;  // declares int pageSize with value 2
        for (int from = 0, page = 1; from < bookings.size(); from += pageSize, page++) {  // loops through all the indexes
            int to = Math.min(from + pageSize, bookings.size());  // declares int to with value Math.min(from + pag...
            System.out.println("Page " + page + ": " + bookings.subList(from, to).stream().map(Booking::fort).toList());  // prints the selected range
        }

        int total = bookings.stream().mapToInt(Booking::people).sum();  // stores the result: creates a stream of the elements
        System.out.println("Total trekkers today: " + total);  // prints a label followed by the value
    }
}
// OUTPUT:
// --- After booking (6) ---
// 1. Sinhagad | Delhi | 8 people
// 2. Raigad | Pune | 4 people
// 3. Torna | Mumbai | 2 people
// 4. Lohagad | Nashik | 6 people
// 5. Raigad | Nagpur | 3 people
// 6. Panhala | Kolhapur | 5 people
// Mumbai booking moved to Purandar
// Raigad cancelled: true
// --- Sorted (4) ---
// 1. Lohagad | Nashik | 6 people
// 2. Panhala | Kolhapur | 5 people
// 3. Purandar | Mumbai | 2 people
// 4. Sinhagad | Delhi | 8 people
// Page 1: [Lohagad, Panhala]
// Page 2: [Purandar, Sinhagad]
// Total trekkers today: 21

// Real-time practice: analysing a visitor log stored in an ArrayList
import java.util.ArrayList;          // imports the ArrayList class
import java.util.Collections;        // imports the Collections class
import java.util.LinkedHashSet;      // imports the LinkedHashSet class
import java.util.List;               // imports the List class
import java.util.Map;                // imports the Map class
import java.util.TreeMap;            // imports the TreeMap class
import java.util.stream.Collectors;  // imports the Collectors class

public class VisitorLogAnalysis {  // class that holds the main method
    record Visit(String city, int day, int people) { }

    public static void main(String[] args) {  // program entry point
        List<Visit> log = new ArrayList<>(List.of(
                new Visit("Pune", 1, 4), new Visit("Mumbai", 1, 2), new Visit("Pune", 2, 6),
                new Visit("Nashik", 2, 3), new Visit("Pune", 3, 5), new Visit("Nagpur", 3, 1),
                new Visit("Mumbai", 3, 7), new Visit("Pune", 4, 2)));

        // Who came from Pune?
        List<Visit> fromPune = log.stream().filter(v -> v.city().equals("Pune")).toList();  // stores the result: creates a stream of the elements
        System.out.println("Visits from Pune : " + fromPune.size());  // prints the number of elements

        // People per day (TreeMap keeps the days in order)
        Map<Integer, Integer> perDay = new TreeMap<>();       // creates an empty TreeMap named perDay
        for (Visit v : log) {                                 // loops over every element of log
            perDay.merge(v.day(), v.people(), Integer::sum);  // combines the old and new value for the key
        }
        System.out.println("People per day   : " + perDay);   // prints a label followed by the value

        // Cities in the order they first appeared, without repeats
        List<String> cities = new ArrayList<>(new LinkedHashSet<>(log.stream().map(Visit::city).toList()));  // creates an ArrayList ordered by the given comparator
        System.out.println("Unique cities    : " + cities);  // prints a label followed by the value

        // Quick answers with Collections helpers
        List<Integer> groups = log.stream().map(Visit::people).collect(Collectors.toList());  // stores the result: creates a stream of the elements
        System.out.println("Biggest group    : " + Collections.max(groups));  // prints a label followed by the value
        System.out.println("Groups of 2      : " + Collections.frequency(groups, 2));  // prints a label followed by the value
        System.out.printf("Average group    : %.2f%n", groups.stream().mapToInt(Integer::intValue).average().orElse(0));  // prints formatted text

        // Busiest city
        Map<String, Integer> perCity = log.stream().collect(Collectors.groupingBy(Visit::city, TreeMap::new, Collectors.summingInt(Visit::people)));  // stores the result: creates a stream of the elements
        String busiest = Collections.max(perCity.entrySet(), Map.Entry.comparingByValue()).getKey();  // stores the value in busiest
        System.out.println("People per city  : " + perCity);  // prints a label followed by the value
        System.out.println("Busiest city     : " + busiest);  // prints a label followed by the value
    }
}
// OUTPUT:
// Visits from Pune : 4
// People per day   : {1=6, 2=9, 3=13, 4=2}
// Unique cities    : [Pune, Mumbai, Nashik, Nagpur]
// Biggest group    : 7
// Groups of 2      : 2
// Average group    : 3.75
// People per city  : {Mumbai=9, Nagpur=1, Nashik=3, Pune=17}
// Busiest city     : Pune

// Practice: seat manager with a waiting list (two ArrayLists)
import java.util.ArrayList;  // imports the ArrayList class
import java.util.List;       // imports the List class

public class SeatManager {       // class that holds the main method
    static final int SEATS = 4;  // stores the value in SEATS

    public static void main(String[] args) {  // program entry point
        String[] commands = {
            "BOOK Pune", "BOOK Mumbai", "BOOK Nashik", "BOOK Nagpur", "BOOK Kolhapur", "BOOK Satara",
                    "CANCEL Mumbai", "CANCEL Satara", "BOOK Thane", "CANCEL Pune", "CANCEL Delhi"};

        List<String> confirmed = new ArrayList<>();  // creates an empty ArrayList named confirmed
        List<String> waiting = new ArrayList<>();    // creates an empty ArrayList named waiting

        for (String command : commands) {                 // loops over every element of commands
            String[] parts = command.split(" ");          // stores the value in parts
            String name = parts[1];                       // stores the value in name
            if (parts[0].equals("BOOK")) {                // checks the condition
                if (confirmed.size() < SEATS) {           // checks the condition
                    confirmed.add(name);                  // adds name to the end of the list
                    System.out.println(command + " -> seat confirmed");  // prints the result
                } else {                                  // runs when the condition is false
                    waiting.add(name);                    // adds name to the end of the list
                    System.out.println(command + " -> waiting list position " + waiting.size());  // prints the number of elements
                }
            } else if (confirmed.remove(name)) {          // remove(Object) returns true if found
                String message = command + " -> seat released";  // stores the value in message
                if (!waiting.isEmpty()) {                 // checks whether it is empty
                    String promoted = waiting.remove(0);  // first come, first served
                    confirmed.add(promoted);              // adds promoted to the end of the list
                    message += ", " + promoted + " promoted from the waiting list";  // updates message
                }
                System.out.println(message);              // prints message
            } else if (waiting.remove(name)) {            // checks the next condition
                System.out.println(command + " -> removed from the waiting list");  // prints the result
            } else {                                      // runs when the condition is false
                System.out.println(command + " -> nobody with that name");  // prints the result
            }
        }
        System.out.println("Confirmed: " + confirmed);    // prints a label followed by the value
        System.out.println("Waiting  : " + waiting);      // prints a label followed by the value
    }
}
// OUTPUT:
// BOOK Pune -> seat confirmed
// BOOK Mumbai -> seat confirmed
// BOOK Nashik -> seat confirmed
// BOOK Nagpur -> seat confirmed
// BOOK Kolhapur -> waiting list position 1
// BOOK Satara -> waiting list position 2
// CANCEL Mumbai -> seat released, Kolhapur promoted from the waiting list
// CANCEL Satara -> removed from the waiting list
// BOOK Thane -> waiting list position 1
// CANCEL Pune -> seat released, Thane promoted from the waiting list
// CANCEL Delhi -> nobody with that name
// Confirmed: [Nashik, Nagpur, Kolhapur, Thane]
// Waiting  : []

