// Practice solution: remove duplicates and rotate
import java.util.*;  // imports every class of java.util

public class RotateSchedule {                                  // class that holds the main method
    public static void main(String[] args) throws Exception {  // program entry point
        List<String> stops = new ArrayList<>(List.of("Raigad", "Sinhagad", "Raigad", "Torna", "Lohagad", "Sinhagad", "Rajgad"));  // creates an ArrayList filled with the listed values
        List<String> unique = new ArrayList<>();               // creates an empty ArrayList named unique
        for (String s : stops) {                               // loops over every element of stops
            if (!unique.contains(s)) unique.add(s);            // keep only the first appearance
        }
        System.out.println("Unique   : " + unique);            // prints a label followed by the value
        int pos = unique.indexOf("Torna");                     // stores the result: finds the first index of "Torna"
        Collections.rotate(unique, -pos);                      // negative = move left, Torna comes first
        System.out.println("Rotated  : " + unique);            // prints a label followed by the value
        System.out.println("Same with LinkedHashSet: " + new ArrayList<>(new LinkedHashSet<>(stops)));  // prints a label followed by the value
    }
}
// OUTPUT:
// Unique   : [Raigad, Sinhagad, Torna, Lohagad, Rajgad]
// Rotated  : [Torna, Lohagad, Rajgad, Raigad, Sinhagad]
// Same with LinkedHashSet: [Raigad, Sinhagad, Torna, Lohagad, Rajgad]

// Practice solution: merge two sorted lists, median, binarySearch
import java.util.*;  // imports every class of java.util

public class MergeSortedGuides {                               // class that holds the main method
    public static void main(String[] args) throws Exception {  // program entry point
        List<Integer> a = List.of(2, 5, 9, 14);                // a is an immutable list of the listed values
        List<Integer> b = List.of(3, 4, 11, 20, 25);           // b is an immutable list of the listed values
        List<Integer> merged = new ArrayList<>(a.size() + b.size());  // exact capacity, no regrowth
        int i = 0, j = 0;                                      // declares int i with value 0, j = 0
        while (i < a.size() && j < b.size()) {                 // two pointers
            if (a.get(i) <= b.get(j)) {                        // checks the condition
                merged.add(a.get(i++));                        // adds a.get(i++) to the end of the list
            }
            else {                                             // runs when the condition is false
                merged.add(b.get(j++));                        // adds b.get(j++) to the end of the list
            }
        }
        while (i < a.size()) merged.add(a.get(i++));           // leftovers
        while (j < b.size()) {                                 // repeats while the condition is true
            merged.add(b.get(j++));                            // adds b.get(j++) to the end of the list
        }
        System.out.println("Merged: " + merged);               // prints a label followed by the value
        int n = merged.size();                                 // stores the result: reads the number of elements
        double median = (n % 2 == 1) ? merged.get(n / 2) : (merged.get(n / 2 - 1) + merged.get(n / 2)) / 2.0;  // declares double median with value (n % 2 == 1) ? merg...
        System.out.println("Median: " + median);               // prints a label followed by the value
        System.out.println("binarySearch 9  -> " + Collections.binarySearch(merged, 9));  // prints a label followed by the value
        int r = Collections.binarySearch(merged, 10);          // declares int r with value Collections.binaryS...
        System.out.println("binarySearch 10 -> " + r + " (not found, would be inserted at " + (-r - 1) + ")");  // prints a label followed by the value
    }
}
// OUTPUT:
// Merged: [2, 3, 4, 5, 9, 11, 14, 20, 25]
// Median: 9.0
// binarySearch 9  -> 4
// binarySearch 10 -> -6 (not found, would be inserted at 5)

// LinkedList constructors and the three ways to see it: List, Queue, Deque
import java.util.Deque;       // imports the Deque class
import java.util.LinkedList;  // imports the LinkedList class
import java.util.List;        // imports the List class
import java.util.Queue;       // imports the Queue class

public class LinkedListCreateDemo {                // class that holds the main method
    public static void main(String[] args) {       // program entry point
        List<String> forts = new LinkedList<>();   // used like a list
        forts.add("Raigad");                       // adds "Raigad" to the end of the list
        forts.add("Sinhagad");                     // adds "Sinhagad" to the end of the list
        System.out.println("As List : " + forts);  // prints a label followed by the value

        Queue<String> waiting = new LinkedList<>(forts);  // copy constructor, used like a queue (first in, first out)
        System.out.println("As Queue: " + waiting + " head=" + waiting.peek());  // prints the element or value read

        Deque<String> stack = new LinkedList<>(List.of("Pune", "Nashik", "Nagpur"));  // used like a deque
        stack.push("Mumbai");                      // push puts the element at the FRONT
        System.out.println("As Deque: " + stack);  // prints a label followed by the value
    }
}
// OUTPUT:
// As List : [Raigad, Sinhagad]
// As Queue: [Raigad, Sinhagad] head=Raigad
// As Deque: [Mumbai, Pune, Nashik, Nagpur]

