// LinkedList as a Queue (first in, first out) and a Stack (last in, first out)
import java.util.LinkedList;  // imports the LinkedList class

public class LinkedListQueueStackDemo {                 // class that holds the main method
    public static void main(String[] args) {            // program entry point
        LinkedList<String> queue = new LinkedList<>();  // creates an empty LinkedList named queue
        queue.offer("Asha");                            // adds "Asha" at the tail without throwing if the queue is full
        queue.offer("Ravi");                            // adds "Ravi" at the tail without throwing if the queue is full
        System.out.println(queue.poll());               // Asha: first in, first out

        LinkedList<String> stack = new LinkedList<>();  // creates an empty LinkedList named stack
        stack.push("Asha");                             // pushes "Asha" on top of the stack
        stack.push("Ravi");                             // pushes "Ravi" on top of the stack
        System.out.println(stack.pop());                // Ravi: last in, first out
    }
}
// OUTPUT:
// Asha
// Ravi

