// LinkedList listIterator(): walk and change elements
import java.util.LinkedList;    // imports the LinkedList class
import java.util.List;          // imports the List class
import java.util.ListIterator;  // imports the ListIterator class

public class LinkedListListIteratorDemo {     // class that holds the main method
    public static void main(String[] args) {  // program entry point
        LinkedList<String> forts = new LinkedList<>(List.of("Raigad", "Sinhagad", "Torna"));  // creates a LinkedList filled with the listed values

        ListIterator<String> it = forts.listIterator();  // stores the result: gets a list iterator that can move in both directions
        while (it.hasNext()) {                           // runs while the iterator has more elements
            String fort = it.next();                     // stores the result: moves to and returns the next element
            it.set(fort.toUpperCase());                  // replace the element just read
        }

        System.out.println(forts);  // prints forts
    }
}
// OUTPUT:
// [RAIGAD, SINHAGAD, TORNA]

