// MASTER PROGRAM: all important LinkedList methods in one program
import java.util.Iterator;    // imports the Iterator class
import java.util.LinkedList;  // imports the LinkedList class
import java.util.List;        // imports the List class

public class LinkedListMasterDemo {           // class that holds the main method
    public static void main(String[] args) {  // program entry point
        // 1. Create an empty list
        LinkedList<String> forts = new LinkedList<>();  // creates an empty LinkedList named forts

        // 2. Add at the end: add, addLast, offer
        forts.add("Raigad");      // adds "Raigad" to the end of the list
        forts.addLast("Torna");   // adds "Torna" at the end
        forts.offer("Purandar");  // adds "Purandar" at the tail without throwing if the queue is full

        // 3. Add at the front: addFirst, push, offerFirst
        forts.addFirst("Sinhagad");   // adds "Sinhagad" at the front
        forts.push("Panhala");        // pushes "Panhala" on top of the stack
        forts.offerFirst("Lohagad");  // adds "Lohagad" at the head

        // 4. Add in the middle and add many: add(index), addAll
        forts.add(2, "Rajgad");                               // inserts "Rajgad" at index 2
        forts.addAll(List.of("Pratapgad", "Vishalgad"));      // adds every element of List.of("Pratapgad", "Vishalgad") to the list
        System.out.println("4. After adds      : " + forts);  // prints a label followed by the value

        // 5. Look without removing: getFirst, getLast, element, peek, peekFirst, peekLast
        System.out.println("5. first / last    : " + forts.getFirst() + " / " + forts.getLast());  // prints the element or value read
        System.out.println("   element / peek  : " + forts.element() + " / " + forts.peek());  // prints the element or value read
        System.out.println("   peekFirst/Last  : " + forts.peekFirst() + " / " + forts.peekLast());  // prints the element or value read

        // 6. By index: get, set
        System.out.println("6. get(3)          : " + forts.get(3));  // prints the element or value read
        forts.set(3, "Karnala");  // replaces the element at index 3 with "Karnala"

        // 7. Search: contains, indexOf, lastIndexOf
        System.out.println("7. contains Torna  : " + forts.contains("Torna"));  // prints whether the element is present
        System.out.println("   indexOf Torna   : " + forts.indexOf("Torna"));  // prints the index of the element
        System.out.println("   lastIndexOf     : " + forts.lastIndexOf("Torna"));  // prints the index of the element

        // 8. Loop: iterator and descendingIterator
        Iterator<String> back = forts.descendingIterator();  // stores the result: gets an iterator that walks in reverse order
        System.out.print("8. Backward        : ");           // prints the text "8. Backward        : "
        while (back.hasNext()) {                             // runs while the iterator has more elements
            System.out.print(back.next() + " ");             // prints the next element
        }
        System.out.println();                                // prints an empty line

        // 9. Remove from the ends (throws if empty): remove, removeFirst, removeLast, pop
        forts.remove();       // removes the head element
        forts.removeFirst();  // removes the first element
        forts.removeLast();   // removes the last element
        forts.pop();          // removes the element on top

        // 10. Remove from the ends (returns null if empty): poll, pollFirst, pollLast
        System.out.println("10. poll           : " + forts.poll());  // prints the removed element
        System.out.println("    pollFirst/Last : " + forts.pollFirst() + " / " + forts.pollLast());  // prints the removed element

        // 11. Remove by value or index: remove(Object), remove(int), removeFirstOccurrence, removeIf
        forts.remove("Torna");                                // removes "Torna" from the list
        forts.remove(0);                                      // removes the element at index 0
        forts.removeFirstOccurrence("Raigad");                // calls removeFirstOccurrence() on forts
        forts.removeIf(f -> f.startsWith("V"));               // removes every element that matches the condition
        System.out.println("11. After removes  : " + forts);  // prints a label followed by the value

        // 12. Copy and reverse: clone, reversed
        Object copy = forts.clone();  // stores the result: creates a shallow copy
        System.out.println("12. clone equals   : " + forts.equals(copy));  // prints the comparison result
        System.out.println("    reversed       : " + forts.reversed());  // prints a label followed by the value

        // 13. Clear everything
        forts.clear();                                        // removes every element from the list
        System.out.println("13. After clear    : " + forts);  // prints a label followed by the value
    }
}
// OUTPUT:
// 4. After adds      : [Lohagad, Panhala, Rajgad, Sinhagad, Raigad, Torna, Purandar, Pratapgad, Vishalgad]
// 5. first / last    : Lohagad / Vishalgad
//    element / peek  : Lohagad / Lohagad
//    peekFirst/Last  : Lohagad / Vishalgad
// 6. get(3)          : Sinhagad
// 7. contains Torna  : true
//    indexOf Torna   : 5
//    lastIndexOf     : 5
// 8. Backward        : Vishalgad Pratapgad Purandar Torna Raigad Karnala Rajgad Panhala Lohagad
// 10. poll           : Karnala
