// Sample project: fort gate queue simulator (LinkedList)
import java.util.*;         // imports every class of java.util
import java.util.stream.*;  // imports every class of java.util.stream

public class LLGateQueueProject {  // class that holds the main method
    // waited is a tiny counter held in an array so the record can change it
    record Group(String name, int people, boolean vip, int[] waited) {  // declares the Group record
        Group(String name, int people, boolean vip) {  // constructor
            this(name, people, vip, new int[1]);       // calls the this() method
        }
    }

    static String names(List<Group> groups) {  // method names()
        return groups.stream().map(Group::name).toList().toString();  // returns the result to the caller
    }

    public static void main(String[] args) throws Exception {  // program entry point
        LinkedList<Group> line = new LinkedList<>();           // Step 2: arrivals
        List<Group> arrivals = List.of(new Group("Pune Trekkers", 12, false), new Group("Nashik Club", 9, false),
                new Group("School Trip", 15, false), new Group("Minister Visit", 6, true), new Group("Satara Scouts", 8, false));
        for (Group g : arrivals) {                             // loops over every element of arrivals
            if (g.vip()) {                                     // checks the condition
                line.addFirst(g);                              // adds g at the front
            }
            else {                                             // runs when the condition is false
                line.addLast(g);                               // adds g at the end
            }
        }
        System.out.println("Line at start: " + names(line));   // prints a label followed by the value

        int capacity = 20;                                    // declares int capacity with value 20
        List<String> admitted = new ArrayList<>();            // creates an empty ArrayList named admitted
        List<String> gaveUp = new ArrayList<>();              // creates an empty ArrayList named gaveUp
        for (int round = 1; round <= 4 && !line.isEmpty(); round++) {  // Step 3: rounds
            int space = capacity;                             // declares int space with value capacity
            System.out.println("-- Round " + round + " (front: " + line.peekFirst().name() + ")");  // prints the element or value read
            while (!line.isEmpty() && line.peekFirst().people() <= space) {  // runs until the collection is empty
                Group g = line.pollFirst();                   // stores the result: removes and returns the head (null if empty)
                space -= g.people();                          // updates space
                admitted.add(g.name());                       // adds g.name() to the end of the list
                System.out.println("  admitted " + g.name() + " (" + g.people() + "), space left " + space);  // prints a label followed by the value
            }
            Iterator<Group> it = line.iterator();             // Step 4: waiting groups get tired
            while (it.hasNext()) {                            // runs while the iterator has more elements
                Group g = it.next();                          // stores the result: moves to and returns the next element
                g.waited()[0]++;
                if (g.waited()[0] > 2) {                      // checks the condition
                    it.remove();                              // removes the head element
                    gaveUp.add(g.name());                     // adds g.name() to the end of the list
                    System.out.println("  " + g.name() + " gave up after waiting");  // prints a label followed by the value
                }
            }
        }
        System.out.println("== Summary ==");                  // Step 5: summary
        System.out.println("Admitted : " + admitted);         // prints a label followed by the value
        System.out.println("Gave up  : " + gaveUp);           // prints a label followed by the value
        System.out.println("Still waiting: " + names(line));  // prints a label followed by the value
    }
}
// OUTPUT:
// Line at start: [Minister Visit, Pune Trekkers, Nashik Club, School Trip, Satara Scouts]
// -- Round 1 (front: Minister Visit)
//   admitted Minister Visit (6), space left 14
//   admitted Pune Trekkers (12), space left 2
// -- Round 2 (front: Nashik Club)
//   admitted Nashik Club (9), space left 11
// -- Round 3 (front: School Trip)
//   admitted School Trip (15), space left 5
//   Satara Scouts gave up after waiting
// == Summary ==
// Admitted : [Minister Visit, Pune Trekkers, Nashik Club, School Trip]
// Gave up  : [Satara Scouts]
// Still waiting: []

// Real-time practice: a day-tour route and a gate queue with LinkedList
import java.util.LinkedList;    // imports the LinkedList class
import java.util.ListIterator;  // imports the ListIterator class

public class TourRoutePlanner {                          // class that holds the main method
    public static void main(String[] args) {             // program entry point
        LinkedList<String> route = new LinkedList<>();   // creates an empty LinkedList named route
        route.add("Lohagad");                            // adds "Lohagad" to the end of the list
        route.add("Rajgad");                             // adds "Rajgad" to the end of the list
        route.addFirst("Sinhagad");                      // start the day here
        route.addLast("Raigad");                         // finish here
        System.out.println("Planned route : " + route);  // prints a label followed by the value

        // Insert a stop right after Lohagad while walking the list
        ListIterator<String> it = route.listIterator();  // stores the result: gets a list iterator that can move in both directions
        while (it.hasNext()) {                           // runs while the iterator has more elements
            if (it.next().equals("Lohagad")) {           // checks the condition
                it.add("Visapur");                       // O(1): no shifting
            }
        }
        System.out.println("With Visapur  : " + route);  // prints a label followed by the value

        // The tour moves forward: the first stop is visited and removed
        while (route.size() > 2) {                 // repeats while the condition is true
            String visited = route.removeFirst();  // stores the result: removes the first element
            System.out.println("Visited " + visited + ", next is " + route.peekFirst());  // prints the element or value read
        }

        // The same class as a queue: groups waiting at the gate
        LinkedList<String> gate = new LinkedList<>();     // creates an empty LinkedList named gate
        gate.offer("Group from Pune");                    // adds "Group from Pune" at the tail without throwing if the queue is full
        gate.offer("Group from Nashik");                  // adds "Group from Nashik" at the tail without throwing if the queue is full
        gate.offer("Group from Mumbai");                  // adds "Group from Mumbai" at the tail without throwing if the queue is full
        while (!gate.isEmpty()) {                         // runs until the collection is empty
            System.out.println("Now entering: " + gate.poll());  // prints the removed element
        }
        System.out.println("Remaining route: " + route);  // prints a label followed by the value
    }
}
// OUTPUT:
