// Practice: round-robin scheduling with a LinkedList queue
import java.util.ArrayList;   // imports the ArrayList class
import java.util.LinkedList;  // imports the LinkedList class
import java.util.List;        // imports the List class

public class GuideScheduler {  // class that holds the main method
    record Group(String name, int hoursLeft) { }

    public static void main(String[] args) {           // program entry point
        LinkedList<Group> queue = new LinkedList<>();  // creates an empty LinkedList named queue
        queue.add(new Group("Pune group", 5));         // adds new Group("Pune group", 5) to the end of the list
        queue.add(new Group("Nashik group", 2));       // adds new Group("Nashik group", 2) to the end of the list
        queue.add(new Group("Nagpur group", 7));       // adds new Group("Nagpur group", 7) to the end of the list

        final int SLICE = 2;                        // declares int SLICE with value 2
        int clock = 0;                              // declares int clock with value 0
        List<String> finished = new ArrayList<>();  // creates an empty ArrayList named finished

        while (!queue.isEmpty()) {                        // runs until the collection is empty
            Group g = queue.poll();                       // next group in line
            int used = Math.min(SLICE, g.hoursLeft());    // declares int used with value Math.min(SLICE, g.h...
            clock += used;                                // updates clock
            int left = g.hoursLeft() - used;              // declares int left with value g.hoursLeft() - used
            System.out.println("t=" + clock + "h: " + g.name() + " got " + used + "h, left " + left);  // prints a label followed by the value
            if (left > 0) {                               // checks the condition
                queue.add(new Group(g.name(), left));     // back of the line
            } else {                                      // runs when the condition is false
                finished.add(g.name() + " (at " + clock + "h)");  // adds g.name() + " (at " + clock + "h)" to the end of the list
            }
        }
        System.out.println("Finish order: " + finished);  // prints a label followed by the value
    }
}
// OUTPUT:
// t=2h: Pune group got 2h, left 3
// t=4h: Nashik group got 2h, left 0
// t=6h: Nagpur group got 2h, left 5
// t=8h: Pune group got 2h, left 1
// t=10h: Nagpur group got 2h, left 3
// t=11h: Pune group got 1h, left 0
// t=13h: Nagpur group got 2h, left 1
// t=14h: Nagpur group got 1h, left 0
// Finish order: [Nashik group (at 4h), Pune group (at 11h), Nagpur group (at 14h)]

// Practice solution: reverse and rotate a LinkedList
import java.util.*;  // imports every class of java.util

public class ReverseRotateLinked {                             // class that holds the main method
    public static void main(String[] args) throws Exception {  // program entry point
        LinkedList<String> stops = new LinkedList<>(List.of("Pune", "Satara", "Kolhapur", "Belgaum", "Goa"));  // creates a LinkedList filled with the listed values
        LinkedList<String> reversed = new LinkedList<>();      // creates an empty LinkedList named reversed
        while (!stops.isEmpty()) {                             // runs until the collection is empty
            reversed.addFirst(stops.removeFirst());            // each taken element goes in front
        }
        System.out.println("Reversed: " + reversed);           // prints a label followed by the value
        for (int i = 0; i < 2; i++) {                          // counting loop
            reversed.addLast(reversed.removeFirst());          // move the first element to the back
        }
        System.out.println("Rotated left by 2: " + reversed);  // prints a label followed by the value
    }
}
// OUTPUT:
// Reversed: [Goa, Belgaum, Kolhapur, Satara, Pune]
// Rotated left by 2: [Kolhapur, Satara, Pune, Goa, Belgaum]

// Practice solution: Josephus problem with LinkedList
import java.util.*;  // imports every class of java.util

public class JosephusGame {                                    // class that holds the main method
    public static void main(String[] args) throws Exception {  // program entry point
        LinkedList<Integer> circle = new LinkedList<>();       // creates an empty LinkedList named circle
        for (int i = 1; i <= 9; i++) {                         // counting loop
            circle.add(i);                                     // adds i to the end of the list
        }
        int step = 3;                                          // declares int step with value 3
        int index = 0;                                         // declares int index with value 0
        StringBuilder order = new StringBuilder();             // creates a StringBuilder object named order
        while (circle.size() > 1) {                            // repeats while the condition is true
            index = (index + step - 1) % circle.size();        // move 3 places around the circle
            order.append(circle.remove(index)).append(' ');    // person leaves; index now points to the next
        }
        System.out.println("Leaving order: " + order.toString().trim());  // prints a label followed by the value
        System.out.println("Last one left: " + circle.getFirst());  // prints the element or value read
    }
}
// OUTPUT:
// Leaving order: 3 6 9 4 8 5 2 7
// Last one left: 1

// Practice solution: merge sorted queues, insert with ListIterator
import java.util.*;  // imports every class of java.util

public class MergeSortedQueues {                               // class that holds the main method
    public static void main(String[] args) throws Exception {  // program entry point
        LinkedList<Integer> gateA = new LinkedList<>(List.of(5, 12, 30, 41));  // creates a LinkedList filled with the listed values
        LinkedList<Integer> gateB = new LinkedList<>(List.of(8, 15, 33));  // creates a LinkedList filled with the listed values
        LinkedList<Integer> merged = new LinkedList<>();       // creates an empty LinkedList named merged
        while (!gateA.isEmpty() && !gateB.isEmpty()) {         // runs until the collection is empty
            if (gateA.peekFirst() <= gateB.peekFirst()) {      // checks the condition
                merged.add(gateA.pollFirst());                 // adds gateA.pollFirst() to the end of the list
            }
            else {                                             // runs when the condition is false
                merged.add(gateB.pollFirst());                 // adds gateB.pollFirst() to the end of the list
            }
        }
        merged.addAll(gateA);                                  // one of them is empty, the other has leftovers
        merged.addAll(gateB);                                  // adds every element of gateB to the list
        System.out.println("Merged : " + merged);              // prints a label followed by the value
        ListIterator<Integer> it = merged.listIterator();      // stores the result: gets a list iterator that can move in both directions
        while (it.hasNext()) {                                 // runs while the iterator has more elements
            if (it.next() > 25) {                              // first element bigger than 25
                it.previous();                                 // step back before it
                it.add(25);                                    // insert here, O(1)
                break;                                         // leaves the loop or switch
            }
        }
        System.out.println("With 25: " + merged);              // prints a label followed by the value
    }
}
// OUTPUT:
// Merged : [5, 8, 12, 15, 30, 33, 41]
// With 25: [5, 8, 12, 15, 25, 30, 33, 41]

// Practice solution: sliding window maximum (Deque)
import java.util.*;  // imports every class of java.util

public class SlidingWindowMax {                                 // class that holds the main method
    public static void main(String[] args) throws Exception {   // program entry point
        int[] h = {1356, 1126, 1403, 1033, 1312, 1450, 1076};   // stores the value in h
        int k = 3;                                              // declares int k with value 3
        Deque<Integer> dq = new LinkedList<>();                 // holds indexes, heights decreasing
        List<Integer> result = new ArrayList<>();               // creates an empty ArrayList named result
        for (int i = 0; i < h.length; i++) {                    // loops through all the indexes
            while (!dq.isEmpty() && h[dq.peekLast()] <= h[i]) dq.pollLast();  // smaller ones can never be the maximum
            dq.addLast(i);                                      // adds i at the end
            if (dq.peekFirst() <= i - k) dq.pollFirst();        // front left the window
            if (i >= k - 1) result.add(h[dq.peekFirst()]);      // front is the window maximum
        }
        System.out.println("Heights : " + Arrays.toString(h));  // prints a label followed by the value
        System.out.println("Max of each window of 3: " + result);  // prints a label followed by the value
    }
}
// OUTPUT:
// Heights : [1356, 1126, 1403, 1033, 1312, 1450, 1076]
// Max of each window of 3: [1403, 1403, 1403, 1450, 1450]

