        // 2. Add: add, addElement, insertElementAt
        forts.add("Raigad");                                 // adds "Raigad" to the end of the list
        forts.addElement("Torna");                           // adds "Torna" at the end
        forts.insertElementAt("Sinhagad", 1);                // inserts "Sinhagad" at index 1
        forts.add("Purandar");                               // adds "Purandar" to the end of the list
        System.out.println("2. After adds     : " + forts);  // prints a label followed by the value

        // 3. Read: get, elementAt, firstElement, lastElement
        System.out.println("3. get(1)         : " + forts.get(1));  // prints the element or value read
        System.out.println("   elementAt(1)   : " + forts.elementAt(1));  // prints a label followed by the value
        System.out.println("   first / last   : " + forts.firstElement() + " / " + forts.lastElement());  // prints a label followed by the value

        // 4. Size and capacity: size, capacity, isEmpty
        System.out.println("4. size/capacity  : " + forts.size() + " / " + forts.capacity());  // prints the number of elements
        System.out.println("   isEmpty        : " + forts.isEmpty());  // prints whether it is empty

        // 5. Search: contains, indexOf, indexOf from a position, lastIndexOf
        System.out.println("5. contains Torna : " + forts.contains("Torna"));  // prints whether the element is present
        System.out.println("   indexOf Torna  : " + forts.indexOf("Torna"));  // prints the index of the element
        System.out.println("   indexOf from 2 : " + forts.indexOf("Torna", 2));  // prints the index of the element
        System.out.println("   lastIndexOf    : " + forts.lastIndexOf("Torna"));  // prints the index of the element

        // 6. Change: set, setElementAt
        forts.set(0, "Lohagad");                             // replaces the element at index 0 with "Lohagad"
        forts.setElementAt("Rajgad", 1);                     // replaces the element at index 1 with "Rajgad"
        System.out.println("6. After changes  : " + forts);  // prints a label followed by the value

        // 7. Sort (a List method works on Vector too)
        Collections.sort(forts);                             // sorts the list (natural order or the given comparator)
        System.out.println("7. Sorted         : " + forts);  // prints a label followed by the value

        // 8. Loop: Enumeration (old) and Iterator (new)
        Enumeration<String> old = forts.elements();     // stores the result: gets an enumeration to walk through
        System.out.print("8. Enumeration    : ");       // prints the text "8. Enumeration    : "
        while (old.hasMoreElements()) {                 // repeats while the condition is true
            System.out.print(old.nextElement() + " ");  // prints the result
        }
        System.out.println();                           // prints an empty line
        Iterator<String> it = forts.iterator();         // stores the result: gets an iterator to walk the elements
        while (it.hasNext()) {                          // runs while the iterator has more elements
            if (it.next().startsWith("L")) {            // checks the condition
                it.remove();                            // removes the head element
            }
        }

        // 9. Copy: copyInto, toArray, clone
        String[] array = new String[forts.size()];  // stores the value in array
        forts.copyInto(array);                      // calls copyInto() on forts
        System.out.println("9. array length   : " + array.length);  // prints a label followed by the value
        Object copy = forts.clone();                // stores the result: creates a shallow copy
        System.out.println("   clone equals   : " + forts.equals(copy));  // prints the comparison result

        // 10. Remove: removeElement, removeElementAt, remove(index), removeIf, removeAllElements
        forts.removeElement("Rajgad");                       // removes the first occurrence of "Rajgad"
        forts.removeElementAt(0);                            // removes the element at index 0
        System.out.println("10. After removes : " + forts);  // prints a label followed by the value
        forts.removeAllElements();                           // removes every element
        System.out.println("    After clear   : " + forts);  // prints a label followed by the value
    }
}
// OUTPUT:
// 2. After adds     : [Raigad, Sinhagad, Torna, Purandar]
// 3. get(1)         : Sinhagad
//    elementAt(1)   : Sinhagad
//    first / last   : Raigad / Purandar
// 4. size/capacity  : 4 / 10
//    isEmpty        : false
// 5. contains Torna : true
//    indexOf Torna  : 2
//    indexOf from 2 : 2
//    lastIndexOf    : 2
// 6. After changes  : [Lohagad, Rajgad, Torna, Purandar]
// 7. Sorted         : [Lohagad, Purandar, Rajgad, Torna]
// 8. Enumeration    : Lohagad Purandar Rajgad Torna
// 9. array length   : 3
//    clone equals   : true
// 10. After removes : [Torna]
//     After clear   : []

