// Safe "add if absent" on a shared Vector: lock around the whole check-then-act
import java.util.Vector;  // imports the Vector class

public class VectorCheckThenActDemo {      // class that holds the main method
    static void addIfAbsent(Vector<String> shared, String fort) {  // method addIfAbsent()
        synchronized (shared) {            // the same lock the Vector uses internally
            if (!shared.contains(fort)) {  // check ...
                shared.add(fort);          // ... then act, with no other thread in between
            }
        }
    }

    public static void main(String[] args) {    // program entry point
        Vector<String> forts = new Vector<>();  // creates an empty Vector named forts
        addIfAbsent(forts, "Raigad");           // calls the addIfAbsent() method
        addIfAbsent(forts, "Torna");            // calls the addIfAbsent() method
        addIfAbsent(forts, "Raigad");           // ignored: already there
        System.out.println(forts);              // prints forts
    }
}
// OUTPUT:
// [Raigad, Torna]

// Two threads add to one Vector: no lost updates because every add is synchronized
import java.util.Vector;  // imports the Vector class

public class VectorThreadsDemo {                  // class that holds the main method
    public static void main(String[] args) throws InterruptedException {  // program entry point
        Vector<String> visited = new Vector<>();  // creates an empty Vector named visited

        Runnable lowerForts = () -> {         // defines lowerForts as a lambda
            for (int i = 1; i <= 500; i++) {  // counting loop
                visited.add("Raigad-" + i);   // adds "Raigad-" + i to the end of the list
            }
        };
        Runnable upperForts = () -> {         // defines upperForts as a lambda
            for (int i = 1; i <= 500; i++) {  // counting loop
                visited.add("Torna-" + i);    // adds "Torna-" + i to the end of the list
            }
        };

        Thread a = new Thread(lowerForts);  // creates a thread named a
        Thread b = new Thread(upperForts);  // creates a thread named b
        a.start();                          // starts the thread
        b.start();                          // starts the thread
        a.join();                           // wait for both threads to finish
        b.join();                           // waits for the thread to finish

        System.out.println("Total visited: " + visited.size());  // always 1000 with a Vector
    }
}
// OUTPUT:
// Total visited: 1000

