// Sample project: legacy Vector register migration
import java.util.*;  // imports every class of java.util

public class VELegacyMigrationProject {  // class that holds the main method
    record FortRow(String fort, String city, int visitors) { }

    public static void main(String[] args) throws Exception {  // program entry point
        Vector<String> legacy = new Vector<>();                // Step 1: old module data
        legacy.addElement("Raigad,Raigad,120");                // adds "Raigad,Raigad,120" at the end
        legacy.addElement("Torna,Pune,80");                    // adds "Torna,Pune,80" at the end
        legacy.addElement("Sinhagad,Pune,200");                // adds "Sinhagad,Pune,200" at the end

        Thread gateA = new Thread(() -> {           // Step 2: two threads add records
            for (int i = 0; i < 3; i++) {           // counting loop
                legacy.add("Lohagad,Pune,10");      // adds "Lohagad,Pune,10" to the end of the list
            }
        });
        Thread gateB = new Thread(() -> {
            for (int i = 0; i < 3; i++) {           // counting loop
                legacy.add("Pratapgad,Satara,25");  // adds "Pratapgad,Satara,25" to the end of the list
            }
        });
        gateA.start();                              // starts the thread
        gateB.start();                              // starts the thread
        try {                                       // code that may throw an exception
            gateA.join();                           // waits for the thread to finish
            gateB.join();                           // waits for the thread to finish
        } catch (InterruptedException ex) {         // handles InterruptedException
            throw new RuntimeException(ex);         // throws RuntimeException
        }
        System.out.println("Legacy records: " + legacy.size());  // prints the number of elements

        List<FortRow> modern = new ArrayList<>();      // Step 3: read with Enumeration
        Enumeration<String> en = legacy.elements();    // stores the result: gets an enumeration to walk through
        while (en.hasMoreElements()) {                 // repeats while the condition is true
            String[] p = en.nextElement().split(",");  // stores the value in p
            modern.add(new FortRow(p[0], p[1], Integer.parseInt(p[2])));  // adds new FortRow(p[0], p[1], Integer.p... to the end of the list
        }

        modern.sort(Comparator.comparingInt(FortRow::visitors).reversed()  // Step 4: sort and find
                .thenComparing(FortRow::fort));
        FortRow best = Collections.max(modern, Comparator.comparingInt(FortRow::visitors));  // stores the value in best
        System.out.println("Best fort: " + best.fort() + " with " + best.visitors());  // prints a label followed by the value

        System.out.println("== Report ==");              // Step 5: report
        for (FortRow r : modern) {                       // loops over every element of modern
            System.out.println(r.fort() + " (" + r.city() + ") " + r.visitors());  // prints the result
        }
        Map<String, Integer> perCity = new TreeMap<>();  // creates an empty TreeMap named perCity
        int total = 0;                                   // declares int total with value 0
        for (FortRow r : modern) {                       // loops over every element of modern
            perCity.merge(r.city(), r.visitors(), Integer::sum);  // combines the old and new value for the key
            total += r.visitors();                       // updates total
        }
        System.out.println("Per city: " + perCity);      // prints a label followed by the value
        System.out.println("Total visitors " + total + ", migrated " + modern.size() + " of " + legacy.size() + " records");  // prints the number of elements
    }
}
// OUTPUT:
// Legacy records: 9
// Best fort: Sinhagad with 200
// == Report ==
// Sinhagad (Pune) 200
// Raigad (Raigad) 120
// Torna (Pune) 80
// Pratapgad (Satara) 25
// Pratapgad (Satara) 25
// Pratapgad (Satara) 25
// Lohagad (Pune) 10
// Lohagad (Pune) 10
// Lohagad (Pune) 10
// Per city: {Pune=310, Raigad=120, Satara=75}
// Total visitors 505, migrated 9 of 9 records

// Real-time practice: four threads writing to one Vector
import java.util.Vector;  // imports the Vector class

public class SharedTicketLog {                    // class that holds the main method
    public static void main(String[] args) throws InterruptedException {  // program entry point
        Vector<String> tickets = new Vector<>();  // creates an empty Vector named tickets

        Thread[] counters = new Thread[4];                    // creates an array named counters
        for (int c = 0; c < counters.length; c++) {           // loops through all the indexes
            final String counterName = "Counter-" + (c + 1);  // stores the text "Counter-" + (c + 1) in counterName
            counters[c] = new Thread(() -> {
                for (int i = 0; i < 1000; i++) {              // counting loop
