            t.join();                                         // waits for the thread to finish
        }
        System.out.println("Tickets recorded : " + tickets.size());  // prints the number of elements

        // A "first time only" rule needs the lock around BOTH steps
        Vector<String> vip = new Vector<>();         // creates an empty Vector named vip
        Runnable addVip = () -> {                    // defines addVip as a lambda
            synchronized (vip) {                     // only one thread at a time may run this block
                if (!vip.contains("Raigad pass")) {  // checks whether the element is present
                    vip.add("Raigad pass");          // adds "Raigad pass" to the end of the list
                }
            }
        };
        Thread a = new Thread(addVip);               // creates a thread named a
        Thread b = new Thread(addVip);               // creates a thread named b
        a.start();                                   // starts the thread
        b.start();                                   // starts the thread
        a.join();                                    // waits for the thread to finish
        b.join();                                    // waits for the thread to finish
        System.out.println("VIP pass entries : " + vip.size());  // prints the number of elements
    }
}
// OUTPUT:
// Tickets recorded : 4000
// VIP pass entries : 1

