import java.util.Collections;  // imports the Collections class
import java.util.Vector;       // imports the Vector class

public class SharedLeaderboard {                  // class that holds the main method
    public static void main(String[] args) throws InterruptedException {  // program entry point
        Vector<Integer> scores = new Vector<>();  // creates an empty Vector named scores

