// Practice solution: capacity growth steps
import java.util.*;  // imports every class of java.util

public class PredictCapacity {                                 // class that holds the main method
    public static void main(String[] args) throws Exception {  // program entry point
        Vector<Integer> stepped = new Vector<>(3, 4);          // creates a Vector named stepped copied from 3, 4
        Vector<Integer> doubling = new Vector<>(3);            // creates a Vector with initial capacity 3
        int lastA = stepped.capacity(), lastB = doubling.capacity();  // stores the result: reads the current capacity
        int growA = 0, growB = 0;                              // declares int growA with value 0, growB = 0
        for (int i = 1; i <= 12; i++) {                        // counting loop
            stepped.add(i);                                    // adds i to the end of the list
            doubling.add(i);                                   // adds i to the end of the list
            if (stepped.capacity() != lastA) {                 // checks the condition
                lastA = stepped.capacity();                    // assigns a new value to lastA
                growA++;                                       // increments growA
                System.out.println("Stepped grew at size " + i + " to " + lastA);  // prints a label followed by the value
            }
            if (doubling.capacity() != lastB) {                // checks the condition
                lastB = doubling.capacity();                   // assigns a new value to lastB
                growB++;                                       // increments growB
                System.out.println("Doubling grew at size " + i + " to " + lastB);  // prints a label followed by the value
            }
        }
        System.out.println("Growth steps: stepped " + growA + ", doubling " + growB);  // prints a label followed by the value
    }
}
