// Practice solution: producer-consumer with a Vector
import java.util.*;  // imports every class of java.util

public class VectorProducerConsumer {                          // class that holds the main method
    public static void main(String[] args) throws Exception {  // program entry point
        Vector<Integer> buffer = new Vector<>();               // creates an empty Vector named buffer
        int[] sum = new int[1];                                // creates an array named sum
        Thread producer = new Thread(() -> {
            for (int n = 1; n <= 5; n++) {                     // counting loop
                synchronized (buffer) {                        // only one thread at a time may run this block
                    buffer.add(n);                             // adds n to the end of the list
                    buffer.notifyAll();                        // wake the consumer
                }
                try {                                          // code that may throw an exception
                    Thread.sleep(5); } catch (InterruptedException ex) { return;
                }
            }
        });
        Thread consumer = new Thread(() -> {
            for (int taken = 0; taken < 5; taken++) {          // counting loop
                synchronized (buffer) {                        // only one thread at a time may run this block
                    while (buffer.isEmpty()) {                 // runs until the collection is empty
                        try { buffer.wait(); } catch (InterruptedException ex) { return; }  // sleep until something is added
                    }
                    sum[0] += buffer.remove(0);                // remove(int) takes the first element
                }
            }
        });
        consumer.start();                                      // starts the thread
        producer.start();                                      // starts the thread
        producer.join();                                       // waits for the thread to finish
        consumer.join();                                       // waits for the thread to finish
        System.out.println("Total of tickets consumed: " + sum[0]);  // prints a label followed by the value
        System.out.println("Buffer left: " + buffer);          // prints a label followed by the value
    }
}
// OUTPUT:
// Total of tickets consumed: 15
// Buffer left: []

