        plates.push("Plate 2");                          // pushes "Plate 2" on top of the stack
        plates.push("Plate 3");                          // pushes "Plate 3" on top of the stack
        System.out.println("2. After push: " + plates);  // prints a label followed by the value

        // 3. peek: look at the top, nothing is removed
        System.out.println("3. peek      : " + plates.peek());  // prints the element or value read

        // 4. search: position from the top, starting at 1
        System.out.println("4. search    : " + plates.search("Plate 3") + " and " + plates.search("Plate 1"));  // prints a label followed by the value

