import java.util.*;  // imports every class of java.util

public class STHelperStackSortDemo {                            // class that holds the main method
    public static void main(String[] args) throws Exception {   // program entry point
        Stack<Integer> input = new Stack<>();                   // creates an empty Stack named input
        for (int n : new int[]{34, 3, 31, 98, 92, 23}) {        // loops over every element of new int[]{34, 3, 31, 98, 92,...
            input.push(n);                                      // pushes n on top of the stack
        }
        Stack<Integer> sorted = new Stack<>();                  // top will be the biggest
        while (!input.empty()) {                                // repeats while the condition is true
            int current = input.pop();                          // stores the result: removes the element on top
            while (!sorted.empty() && sorted.peek() > current) {  // repeats while the condition is true
                input.push(sorted.pop());                       // move bigger ones back
            }
            sorted.push(current);                               // now it fits
        }
        System.out.println("Sorted (bottom to top): " + sorted);  // prints a label followed by the value
        System.out.println("Top (biggest): " + sorted.peek());  // prints the element or value read
    }
}
