// Real-time: stack-based DFS route finder
import java.util.*;  // imports every class of java.util

public class STRouteSearchDemo {                               // class that holds the main method
    public static void main(String[] args) throws Exception {  // program entry point
        Map<String, List<String>> roads = new LinkedHashMap<>();  // creates an empty LinkedHashMap named roads
        roads.put("Pune", List.of("Sinhagad", "Torna"));       // maps key "Pune" to value List.of("Sinhagad", "Torna")
        roads.put("Sinhagad", List.of("Rajgad"));              // maps key "Sinhagad" to value List.of("Rajgad")
        roads.put("Torna", List.of("Rajgad", "Raigad"));       // maps key "Torna" to value List.of("Rajgad", "Raigad")
        roads.put("Rajgad", List.of());                        // maps key "Rajgad" to value List.of()
        roads.put("Raigad", List.of());                        // maps key "Raigad" to value List.of()
        Stack<List<String>> paths = new Stack<>();             // each entry is a whole path
        paths.push(List.of("Pune"));                           // pushes List.of("Pune") on top of the stack
        while (!paths.empty()) {                               // repeats while the condition is true
            List<String> path = paths.pop();                   // stores the result: removes the element on top
            String last = path.get(path.size() - 1);           // stores the result: reads the element at index path.size() - 1
            if (last.equals("Raigad")) {                       // checks the condition
                System.out.println("Route found: " + String.join(" -> ", path));  // prints a label followed by the value
                break;                                         // leaves the loop or switch
            }
            for (String next : roads.get(last)) {              // loops over every element of roads.get(last)
                List<String> longer = new ArrayList<>(path);   // creates an ArrayList named longer copied from path
                longer.add(next);                              // adds next to the end of the list
                paths.push(longer);                            // explore later (LIFO)
            }
        }
    }
}
// OUTPUT:
// Route found: Pune -> Torna -> Raigad

