public class STBrowserProject {                            // class that holds the main method
    static class Browser {                                 // declares the Browser class
        String current;                                    // declares current of type String
        final Stack<String> back = new Stack<>();          // creates an empty Stack named back
        final Stack<String> forward = new Stack<>();       // creates an empty Stack named forward
        final List<String> bookmarks = new ArrayList<>();  // creates an empty ArrayList named bookmarks

        Browser(String start) {    // constructor
            this.current = start;  // stores start in the field current
        }

        void open(String page) {  // method open()
            back.push(current);   // pushes current on top of the stack
            current = page;       // assigns a new value to current
            forward.clear();      // new page: forward history is gone
        }

        void back() {               // method back()
            if (back.empty()) { System.out.println("  (nothing to go back to)"); return; }  // Step 3
            forward.push(current);  // pushes current on top of the stack
            current = back.pop();   // assigns a new value to current
        }

        void forward() {              // method forward()
            if (forward.empty()) { System.out.println("  (nothing to go forward to)"); return; }
            back.push(current);       // pushes current on top of the stack
            current = forward.pop();  // assigns a new value to current
        }

        void bookmark() {  // method bookmark()
            if (!bookmarks.contains(current)) bookmarks.add(current);  // no duplicates
