// Real-time practice: undo / redo and bracket checking with Stack
import java.util.ArrayList;  // imports the ArrayList class
import java.util.List;       // imports the List class
import java.util.Stack;      // imports the Stack class

public class RouteEditorUndo {                           // class that holds the main method
    static final List<String> plan = new ArrayList<>();  // creates an empty ArrayList named plan
    static final Stack<String> undo = new Stack<>();     // creates an empty Stack named undo
    static final Stack<String> redo = new Stack<>();     // creates an empty Stack named redo

    static void add(String fort) {                           // method add()
        plan.add(fort);                                      // adds fort to the end of the list
        undo.push(fort);                                     // remember the action
        redo.clear();                                        // a new action ends the redo history
        System.out.println("add " + fort + "  -> " + plan);  // prints a label followed by the value
    }

    static void undoLast() {                                 // method undoLast()
        if (undo.empty()) {                                  // checks the condition
            System.out.println("nothing to undo");           // prints the text "nothing to undo"
            return;                                          // ends the method
        }
        String fort = undo.pop();                            // most recent action first
        plan.remove(fort);                                   // removes fort from the collection
        redo.push(fort);                                     // pushes fort on top of the stack
        System.out.println("undo " + fort + " -> " + plan);  // prints a label followed by the value
    }

    static void redoLast() {                                 // method redoLast()
        if (redo.empty()) {                                  // checks the condition
            System.out.println("nothing to redo");           // prints the text "nothing to redo"
            return;                                          // ends the method
        }
        String fort = redo.pop();                            // stores the result: removes the element on top
        plan.add(fort);                                      // adds fort to the end of the list
        undo.push(fort);                                     // pushes fort on top of the stack
        System.out.println("redo " + fort + " -> " + plan);  // prints a label followed by the value
    }

    static boolean balanced(String text) {                     // method balanced()
        Stack<Character> open = new Stack<>();                 // creates an empty Stack named open
        for (char ch : text.toCharArray()) {                   // loops over every element of text.toCharArray()
            if (ch == '(' || ch == '[' || ch == '{') {         // checks the condition
                open.push(ch);                                 // pushes ch on top of the stack
            } else if (ch == ')' || ch == ']' || ch == '}') {  // checks the next condition
                if (open.empty()) {                            // checks the condition
                    return false;                              // returns the result to the caller
                }
                char top = open.pop();                         // stores the result: removes the element on top
                if ((ch == ')' && top != '(') || (ch == ']' && top != '[') || (ch == '}' && top != '{')) {  // checks the condition
                    return false;                              // returns the result to the caller
                }
            }
        }
        return open.empty();                                   // returns the result to the caller
    }

    public static void main(String[] args) {                // program entry point
        add("Sinhagad");                                    // calls the add() method
        add("Lohagad");                                     // calls the add() method
        add("Raigad");                                      // calls the add() method
        undoLast();                                         // calls the undoLast() method
        undoLast();                                         // calls the undoLast() method
        redoLast();                                         // calls the redoLast() method
        add("Torna");                                       // clears the redo history
        redoLast();                                         // calls the redoLast() method
        System.out.println("Last action: " + undo.peek());  // prints the element or value read

        System.out.println("(a[b]{c})  balanced? " + balanced("(a[b]{c})"));  // prints a label followed by the value
        System.out.println("(a[b)]     balanced? " + balanced("(a[b)]"));  // prints a label followed by the value
    }
}
// OUTPUT:
// add Sinhagad  -> [Sinhagad]
// add Lohagad  -> [Sinhagad, Lohagad]
// add Raigad  -> [Sinhagad, Lohagad, Raigad]
// undo Raigad -> [Sinhagad, Lohagad]
// undo Lohagad -> [Sinhagad]
// redo Lohagad -> [Sinhagad, Lohagad]
// add Torna  -> [Sinhagad, Lohagad, Torna]
// nothing to redo
// Last action: Torna
// (a[b]{c})  balanced? true
// (a[b)]     balanced? false

// Practice: evaluating infix expressions with two Stacks
import java.util.Stack;  // imports the Stack class

public class InfixCalculator {                    // class that holds the main method
    static int priority(char op) {                // method priority()
        return (op == '+' || op == '-') ? 1 : 2;  // * and / bind tighter
    }

    static void apply(Stack<Integer> numbers, Stack<Character> ops) {  // method apply()
        int b = numbers.pop();      // right operand is on top
        int a = numbers.pop();      // stores the result: removes the element on top
        char op = ops.pop();        // stores the result: removes the element on top
        numbers.push(switch (op) {  // pushes switch (op on top of the stack
            case '+' -> a + b;
            case '-' -> a - b;
            case '*' -> a * b;
            default -> a / b;
        });
    }

    static int evaluate(String text) {             // method evaluate()
        Stack<Integer> numbers = new Stack<>();    // creates an empty Stack named numbers
        Stack<Character> ops = new Stack<>();      // creates an empty Stack named ops
        for (int i = 0; i < text.length(); i++) {  // loops through all the indexes
            char ch = text.charAt(i);              // declares char ch with value text.charAt(i)
            if (ch == ' ') {                       // checks the condition
                continue;                          // skips to the next iteration
            }
            if (Character.isDigit(ch)) {           // checks the condition
                int value = 0;                     // declares int value with value 0
                while (i < text.length() && Character.isDigit(text.charAt(i))) {  // repeats while the condition is true
                    value = value * 10 + (text.charAt(i++) - '0');  // assigns a new value to value
                }
                i--;                               // decrements i
                numbers.push(value);               // pushes value on top of the stack
            } else if (ch == '(') {                // checks the next condition
                ops.push(ch);                      // pushes ch on top of the stack
            } else if (ch == ')') {                // checks the next condition
                while (ops.peek() != '(') {        // repeats while the condition is true
                    apply(numbers, ops);           // calls the apply() method
                }
                ops.pop();                         // discard the '('
            } else {                               // runs when the condition is false
                while (!ops.empty() && ops.peek() != '(' && priority(ops.peek()) >= priority(ch)) {  // repeats while the condition is true
                    apply(numbers, ops);           // calls the apply() method
                }
                ops.push(ch);                      // pushes ch on top of the stack
            }
        }
        while (!ops.empty()) {                     // repeats while the condition is true
            apply(numbers, ops);                   // calls the apply() method
        }
        return numbers.pop();                      // returns the result to the caller
    }

    public static void main(String[] args) {  // program entry point
