// Practice solution: reverse text and palindrome check
import java.util.*;  // imports every class of java.util

public class ReverseAndPalindrome {                       // class that holds the main method
    static String reverse(String text) {                  // method reverse()
        Stack<Character> stack = new Stack<>();           // creates an empty Stack named stack
        for (char c : text.toCharArray()) stack.push(c);  // last character ends up on top
        StringBuilder sb = new StringBuilder();           // creates a StringBuilder object named sb
        while (!stack.empty()) sb.append(stack.pop());    // pops in reverse order
        return sb.toString();                             // returns the result to the caller
    }

    public static void main(String[] args) throws Exception {  // program entry point
        System.out.println("Reversed: " + reverse("Raigad Fort"));  // prints a label followed by the value
        for (String w : new String[]{"MADAM", "TORNA"}) {      // loops over every element of new String[]{"MADAM", "TORNA"}
            System.out.println(w + " palindrome? " + w.equals(reverse(w)));  // prints the comparison result
        }
    }
}
// OUTPUT:
// Reversed: troF dagiaR
// MADAM palindrome? true
// TORNA palindrome? false

// Practice solution: next greater element
import java.util.*;  // imports every class of java.util

public class NextTallerFort {                                   // class that holds the main method
    public static void main(String[] args) throws Exception {   // program entry point
        int[] h = {1033, 1356, 1126, 1403, 1312, 1076, 1450};   // stores the value in h
        int[] answer = new int[h.length];                       // stores the value in answer
        Arrays.fill(answer, -1);                                // default: none
        Stack<Integer> waiting = new Stack<>();                 // indexes still waiting for a taller fort
        for (int i = 0; i < h.length; i++) {                    // loops through all the indexes
            while (!waiting.empty() && h[waiting.peek()] < h[i]) {  // repeats while the condition is true
                answer[waiting.pop()] = h[i];                   // h[i] is the next taller for that fort
            }
            waiting.push(i);                                    // pushes i on top of the stack
        }
        System.out.println("Heights : " + Arrays.toString(h));  // prints a label followed by the value
        System.out.println("Next big: " + Arrays.toString(answer));  // prints a label followed by the value
    }
}
// OUTPUT:
// Heights : [1033, 1356, 1126, 1403, 1312, 1076, 1450]
// Next big: [1356, 1403, 1403, 1450, 1450, 1450, -1]

// Practice solution: stack with O(1) minimum
import java.util.*;  // imports every class of java.util

public class MinStackPractice {                             // class that holds the main method
    static class MinStack {                                 // declares the MinStack class
        private final Stack<Integer> data = new Stack<>();  // creates an empty Stack named data
        private final Stack<Integer> mins = new Stack<>();  // creates an empty Stack named mins

        void push(int v) {  // method push()
            data.push(v);   // pushes v on top of the stack
            if (mins.empty() || v <= mins.peek()) mins.push(v);  // <= keeps duplicates of the minimum
        }

        int pop() {                            // method pop()
            int v = data.pop();                // stores the result: removes the element on top
            if (v == mins.peek()) mins.pop();  // the minimum left the stack
            return v;                          // returns the result to the caller
        }

        int min() {              // method min()
            return mins.peek();  // returns the result to the caller
        }
    }

    public static void main(String[] args) throws Exception {  // program entry point
        MinStack s = new MinStack();                           // creates an empty MinStack named s
        int[] pushes = {50, 30, 70, 30, 20};                   // stores the value in pushes
        for (int p : pushes) {                                 // loops over every element of pushes
            s.push(p);                                         // pushes p on top of the stack
            System.out.println("push " + p + " -> min " + s.min());  // prints a label followed by the value
        }
        for (int i = 0; i < 3; i++) {                          // counting loop
            System.out.println("pop " + s.pop() + " -> min " + s.min());  // prints the removed element
        }
    }
}
// OUTPUT:
// push 50 -> min 50
// push 30 -> min 30
// push 70 -> min 30
// push 30 -> min 30
// push 20 -> min 20
// pop 20 -> min 30
// pop 30 -> min 30
// pop 70 -> min 30

// Practice solution: decode nested repeats with stacks
import java.util.*;  // imports every class of java.util

public class DecodeTrekCode {                         // class that holds the main method
    static String decode(String code) {               // method decode()
        Stack<Integer> counts = new Stack<>();        // creates an empty Stack named counts
        Stack<StringBuilder> texts = new Stack<>();   // creates an empty Stack named texts
        StringBuilder current = new StringBuilder();  // creates a StringBuilder object named current
        int number = 0;                               // declares int number with value 0
        for (char c : code.toCharArray()) {           // loops over every element of code.toCharArray()
            if (Character.isDigit(c)) {               // checks the condition
                number = number * 10 + (c - '0');     // can be more than one digit
            } else if (c == '[') {                    // checks the next condition
                counts.push(number);                  // remember how many times
                texts.push(current);                  // remember the text so far
                current = new StringBuilder();        // assigns a new value to current
                number = 0;                           // assigns a new value to number
            } else if (c == ']') {                    // checks the next condition
                int times = counts.pop();             // stores the result: removes the element on top
                StringBuilder before = texts.pop();   // stores the result: removes the element on top
                before.append(current.toString().repeat(times));  // repeat the inner text
                current = before;                     // assigns a new value to current
            } else {                                  // runs when the condition is false
                current.append(c);                    // calls append() on current
            }
        }
        return current.toString();                    // returns the result to the caller
    }

    public static void main(String[] args) throws Exception {  // program entry point
        for (String code : new String[]{"2[ab3[c]]d", "3[Fort]", "x2[y]z"}) {  // loops over every element of new String[]{"2[ab3[c]]d", "3...
            System.out.println(code + " -> " + decode(code));  // prints the result
        }
    }
}
// OUTPUT:
// 2[ab3[c]]d -> abcccabcccd
// 3[Fort] -> FortFortFort
// x2[y]z -> xyyz

