        // 3. addAll: union (everything from both sets)
        a.addAll(Set.of(3, 4, 5));                    // adds every element of Set.of(3, 4, 5) to the set
        System.out.println("3. After addAll: " + a);  // prints a label followed by the value

        // 4. size and isEmpty
        System.out.println("4. size/isEmpty: " + a.size() + " / " + a.isEmpty());  // prints the number of elements

        // 5. contains and containsAll
        System.out.println("5. contains 4  : " + a.contains(4));  // prints whether the element is present
        System.out.println("   containsAll : " + a.containsAll(Set.of(1, 2)));  // prints whether the element is present

        // 6. remove: true only if it was present
        System.out.println("6. remove 5    : " + a.remove(5));  // prints the removed element
        System.out.println("   remove 5    : " + a.remove(5));  // prints the removed element

        // 7. Loop: for-each, iterator with remove, forEach
        for (int n : a) {                           // loops over every element of a
            System.out.print(n + " ");              // prints the result
        }
        System.out.println();                       // prints an empty line
        Iterator<Integer> it = a.iterator();        // stores the result: gets an iterator to walk the elements
        while (it.hasNext()) {                      // runs while the iterator has more elements
            if (it.next() == 4) {                   // checks the condition
                it.remove();                        // removes the head element
            }
        }
        a.forEach(n -> System.out.print(n + ","));  // runs the given action for every element
        System.out.println();                       // prints an empty line

        // 8. Set maths: retainAll (common), removeAll (difference), removeIf (rule)
        Set<Integer> common = new HashSet<>(a);            // creates a HashSet named common copied from a
        common.retainAll(Set.of(2, 3, 9));                 // keeps only the elements that are also in Set.of(2, 3, 9)
        System.out.println("8. common      : " + common);  // prints a label followed by the value
        Set<Integer> diff = new HashSet<>(a);              // creates a HashSet named diff copied from a
        diff.removeAll(Set.of(2, 3));                      // removes all elements that are in Set.of(2, 3)
        System.out.println("   difference  : " + diff);    // prints a label followed by the value
        a.removeIf(n -> n % 2 == 0);                       // removes every element that matches the condition

        // 9. Convert: toArray, stream, copy
        System.out.println("9. array length: " + a.toArray().length);  // prints a label followed by the value
        System.out.println("   stream count: " + a.stream().count());  // prints a label followed by the value
        Set<Integer> copy = new HashSet<>(a);  // creates a HashSet named copy copied from a
        System.out.println("   equals copy : " + a.equals(copy));  // prints the comparison result

        // 10. clear
        a.clear();                                    // removes every element from the set
        System.out.println("10. After clear: " + a);  // prints a label followed by the value
    }
}
// OUTPUT:
// 2. add 1      : true
//    add 1 again: false
// 3. After addAll: [1, 2, 3, 4, 5]
// 4. size/isEmpty: 5 / false
// 5. contains 4  : true
//    containsAll : true
// 6. remove 5    : true
//    remove 5    : false
// 1 2 3 4
// 1,2,3,
// 8. common      : [2, 3]
//    difference  : [1]
// 9. array length: 2
//    stream count: 2
//    equals copy : true
// 10. After clear: []

