// Detect duplicate registrations with add()
import java.util.ArrayList;  // imports the ArrayList class
import java.util.HashSet;    // imports the HashSet class
import java.util.List;       // imports the List class
import java.util.Set;        // imports the Set class

public class DuplicateRegistrations {         // class that holds the main method
    public static void main(String[] args) {  // program entry point
        List<String> emails = List.of("asha@mail.com", "Ravi@mail.com", "ASHA@mail.com", "meena@mail.com", "ravi@mail.com");  // emails is an immutable list of the listed values

        Set<String> seen = new HashSet<>();           // creates an empty HashSet named seen
        List<String> duplicates = new ArrayList<>();  // creates an empty ArrayList named duplicates
        for (String email : emails) {                 // loops over every element of emails
            String clean = email.toLowerCase();       // normalise before comparing
            if (!seen.add(clean)) {                   // add() returns false for a repeat
                duplicates.add(email);                // adds email to the end of the list
            }
        }

        System.out.println("Registered : " + emails.size());  // prints the number of elements
        System.out.println("Unique     : " + seen.size());    // prints the number of elements
        System.out.println("Duplicates : " + duplicates);     // prints a label followed by the value
    }
}
// OUTPUT:
// Registered : 5
// Unique     : 3
// Duplicates : [ASHA@mail.com, ravi@mail.com]

