// SAMPLE PROJECT: Trek registration desk (HashSet in action)
import java.util.ArrayList;  // imports the ArrayList class
import java.util.HashSet;    // imports the HashSet class
import java.util.List;       // imports the List class
import java.util.Map;        // imports the Map class
import java.util.Set;        // imports the Set class
import java.util.TreeMap;    // imports the TreeMap class
import java.util.TreeSet;    // imports the TreeSet class

public class TrekRegistrationDesk {  // class that holds the main method
    record Registration(String email, String name, String fort) { }

    public static void main(String[] args) {  // program entry point
        // Step 1: raw sign-ups. Some people sign up twice or with different letter case.
        List<Registration> signups = List.of(
                new Registration("asha@mail.com", "Asha", "Raigad"),
                new Registration("ravi@mail.com", "Ravi", "Torna"),
                new Registration("ASHA@mail.com", "Asha K", "Raigad"),
                new Registration("meena@mail.com", "Meena", "Raigad"),
                new Registration("ravi@mail.com", "Ravi", "Raigad"),
                new Registration("kiran@mail.com", "Kiran", "Sinhagad"),
                new Registration("meena@mail.com", "Meena", "Torna"),
                new Registration("ravi@mail.com", "Ravi", "Torna"));

        // Step 2: accept the first sign-up for each (e-mail, fort) pair, reject the rest
        Set<String> seenKeys = new HashSet<>();                 // creates an empty HashSet named seenKeys
        List<Registration> accepted = new ArrayList<>();        // creates an empty ArrayList named accepted
        List<String> rejected = new ArrayList<>();              // creates an empty ArrayList named rejected
        for (Registration r : signups) {                        // loops over every element of signups
            String key = r.email().toLowerCase() + "|" + r.fort();  // normalised key
            if (seenKeys.add(key)) {                            // true = new pair
                accepted.add(r);                                // adds r to the end of the list
            } else {                                            // runs when the condition is false
                rejected.add(r.name() + " for " + r.fort());    // adds r.name() + " for " + r.fort() to the end of the list
            }
        }
        System.out.println("Sign-ups received : " + signups.size());  // prints the number of elements
        System.out.println("Accepted          : " + accepted.size());  // prints the number of elements
        System.out.println("Rejected          : " + rejected);  // prints a label followed by the value

        // Step 3: attendees per fort (a TreeMap of TreeSets only to print in a fixed order)
        Map<String, Set<String>> byFort = new TreeMap<>();  // creates an empty TreeMap named byFort
        for (Registration r : accepted) {                   // loops over every element of accepted
            byFort.computeIfAbsent(r.fort(), f -> new TreeSet<>()).add(r.email().toLowerCase());  // computes the value for the key
        }
        for (Map.Entry<String, Set<String>> e : byFort.entrySet()) {  // loops over every element of byFort.entrySet()
            System.out.println(e.getKey() + " -> " + e.getValue().size() + " trekkers " + e.getValue());  // prints the number of elements
        }

        // Step 4: set maths
        Set<String> both = new TreeSet<>(byFort.get("Raigad"));  // creates a TreeSet named both copied from byFort.get("Raigad")
        both.retainAll(byFort.get("Torna"));         // intersection
        Set<String> everyone = new TreeSet<>();      // creates an empty TreeSet named everyone
        for (Set<String> group : byFort.values()) {  // loops over every element of byFort.values()
            everyone.addAll(group);                  // union
        }
        System.out.println("Going to Raigad and Torna : " + both);  // prints a label followed by the value
        System.out.println("Different people overall  : " + everyone.size());  // prints the number of elements
    }
}
