// Real-time practice: registrations and set arithmetic with HashSet
import java.util.HashSet;  // imports the HashSet class
import java.util.Set;      // imports the Set class
import java.util.TreeSet;  // imports the TreeSet class

public class VisitorRegistry {                 // class that holds the main method
    public static void main(String[] args) {   // program entry point
        Set<String> raigad = new HashSet<>();  // creates an empty HashSet named raigad
        for (String id : new String[] {"PUN-101", "MUM-202", "PUN-101", "NSK-303", "NGP-404"}) {  // loops over every element of new String[] {"PUN-101", "MUM...
            if (!raigad.add(id)) {             // checks the condition
                System.out.println("Rejected duplicate registration: " + id);  // prints a label followed by the value
            }
        }

        Set<String> torna = new HashSet<>(Set.of("MUM-202", "KOP-505", "NGP-404", "SAT-606"));  // creates a HashSet filled with the listed values

        Set<String> both = new HashSet<>(raigad);        // creates a HashSet named both copied from raigad
        both.retainAll(torna);                           // intersection
        Set<String> either = new HashSet<>(raigad);      // creates a HashSet named either copied from raigad
        either.addAll(torna);                            // union
        Set<String> onlyRaigad = new HashSet<>(raigad);  // creates a HashSet named onlyRaigad copied from raigad
        onlyRaigad.removeAll(torna);                     // difference

        System.out.println("Visited both forts   : " + new TreeSet<>(both));  // prints a label followed by the value
        System.out.println("Visited either fort  : " + new TreeSet<>(either));  // prints a label followed by the value
        System.out.println("Visited only Raigad  : " + new TreeSet<>(onlyRaigad));  // prints a label followed by the value
        System.out.println("Gate check PUN-101   : " + raigad.contains("PUN-101"));  // prints whether the element is present
        System.out.println("Raigad is subset of union: " + either.containsAll(raigad));  // prints whether the element is present
    }
}
// OUTPUT:
// Rejected duplicate registration: PUN-101
// Visited both forts   : [MUM-202, NGP-404]
// Visited either fort  : [KOP-505, MUM-202, NGP-404, NSK-303, PUN-101, SAT-606]
// Visited only Raigad  : [NSK-303, PUN-101]
// Gate check PUN-101   : true
// Raigad is subset of union: true

// Practice: common, unique and first-repeated elements with sets
import java.util.HashMap;  // imports the HashMap class
import java.util.HashSet;  // imports the HashSet class
import java.util.List;     // imports the List class
import java.util.Map;      // imports the Map class
import java.util.Set;      // imports the Set class
import java.util.TreeSet;  // imports the TreeSet class

public class WhoVisitedWhat {                 // class that holds the main method
    public static void main(String[] args) {  // program entry point
        List<Set<String>> groups = List.of(
                new HashSet<>(List.of("Raigad", "Torna", "Lohagad", "Purandar")),
                new HashSet<>(List.of("Raigad", "Torna", "Sinhagad")),
                new HashSet<>(List.of("Raigad", "Torna", "Panhala", "Lohagad")));

        Set<String> everyGroup = new HashSet<>(groups.get(0));  // creates a HashSet named everyGroup copied from groups.get(0)
        for (Set<String> g : groups) {                          // loops over every element of groups
            everyGroup.retainAll(g);                            // keep only what is in all sets
        }
        System.out.println("Visited by every group: " + new TreeSet<>(everyGroup));  // prints a label followed by the value

        Map<String, Integer> howMany = new HashMap<>();  // creates an empty HashMap named howMany
        for (Set<String> g : groups) {                   // loops over every element of groups
            for (String fort : g) {                      // loops over every element of g
                howMany.merge(fort, 1, Integer::sum);    // combines the old and new value for the key
            }
        }
        Set<String> onlyOne = new TreeSet<>();           // creates an empty TreeSet named onlyOne
        howMany.forEach((fort, count) -> {               // runs the given action for every element
            if (count == 1) {                            // checks the condition
                onlyOne.add(fort);                       // adds fort to the set (a duplicate is ignored)
            }
        });
        System.out.println("Visited by exactly one group: " + onlyOne);  // prints a label followed by the value

        String[] log = {"Pune", "Mumbai", "Nashik", "Mumbai", "Pune"};  // stores the value in log
        Set<String> seen = new HashSet<>();  // creates an empty HashSet named seen
        for (String city : log) {            // loops over every element of log
            if (!seen.add(city)) {           // add() is false for a repeat
                System.out.println("First repeated city in the log: " + city);  // prints a label followed by the value
                break;                       // leaves the loop or switch
            }
        }
    }
}
// OUTPUT:
// Visited by every group: [Raigad, Torna]
// Visited by exactly one group: [Panhala, Purandar, Sinhagad]
// First repeated city in the log: Mumbai

// Practice: pair with a given sum using a HashSet (one pass, O(n))
import java.util.HashSet;  // imports the HashSet class
import java.util.Set;      // imports the Set class

public class PairSumFinder {                    // class that holds the main method
    public static void main(String[] args) {    // program entry point
        int[] heights = {10, 15, 3, 7, 8, 12};  // stores the value in heights
        int target = 15;                        // declares int target with value 15

        Set<Integer> seen = new HashSet<>();  // creates an empty HashSet named seen
        for (int x : heights) {               // loops over every element of heights
            int need = target - x;            // the partner we are looking for
            if (seen.contains(need)) {        // O(1) lookup
                System.out.println("Pair found: " + need + " + " + x + " = " + target);  // prints a label followed by the value
            }
            seen.add(x);                      // remember x for later elements
        }
    }
}
// OUTPUT:
// Pair found: 7 + 8 = 15
// Pair found: 3 + 12 = 15

// Practice: longest substring without repeating characters (sliding window)
import java.util.HashSet;  // imports the HashSet class
import java.util.Set;      // imports the Set class

public class LongestUniqueStretch {                            // class that holds the main method
    static int longest(String text) {                          // method longest()
        Set<Character> window = new HashSet<>();               // creates an empty HashSet named window
        int left = 0;                                          // declares int left with value 0
        int best = 0;                                          // declares int best with value 0
        for (int right = 0; right < text.length(); right++) {  // loops through all the indexes
            char c = text.charAt(right);                       // declares char c with value text.charAt(right)
            while (window.contains(c)) {                       // duplicate inside the window: shrink from the left
                window.remove(text.charAt(left));              // removes text.charAt(left) from the set
                left++;                                        // increments left
            }
            window.add(c);                                     // window now has only distinct letters
            best = Math.max(best, right - left + 1);           // assigns a new value to best
        }
        return best;                                           // returns the result to the caller
    }

    public static void main(String[] args) {                    // program entry point
        for (String word : new String[] {"abcabcbb", "pwwkew", "nashik"}) {  // loops over every element of new String[] {"abcabcbb", "pw...
            System.out.println(word + " -> " + longest(word));  // prints the result
        }
    }
}
// OUTPUT:
// abcabcbb -> 3
// pwwkew -> 3
// nashik -> 6

