// MASTER PROGRAM: all important LinkedHashSet methods in one program
import java.util.LinkedHashSet;  // imports the LinkedHashSet class
import java.util.Set;            // imports the Set class

public class LinkedHashSetMasterDemo {        // class that holds the main method
    public static void main(String[] args) {  // program entry point
        // 1. Create an empty set (it remembers insertion order)
        LinkedHashSet<String> forts = new LinkedHashSet<>();  // creates an empty LinkedHashSet named forts

        // 2. add and addAll: duplicates are ignored
        forts.add("Torna");                                // adds "Torna" to the set (a duplicate is ignored)
        forts.add("Raigad");                               // adds "Raigad" to the set (a duplicate is ignored)
        forts.add("Torna");                                // ignored
        forts.addAll(Set.of("Sinhagad"));                  // adds every element of Set.of("Sinhagad") to the set
        System.out.println("2. After adds   : " + forts);  // prints a label followed by the value

        // 3. size, isEmpty, contains
        System.out.println("3. size/isEmpty : " + forts.size() + " / " + forts.isEmpty());  // prints the number of elements
        System.out.println("   contains     : " + forts.contains("Raigad"));  // prints whether the element is present

        // 4. Java 21: getFirst, getLast, reversed
        System.out.println("4. first / last : " + forts.getFirst() + " / " + forts.getLast());  // prints the element or value read
        System.out.println("   reversed     : " + forts.reversed());  // prints a label followed by the value

        // 5. Java 21: addFirst / addLast move an existing element
        forts.addFirst("Sinhagad");                        // moves to the front
        forts.addLast("Purandar");                         // new, added at the end
        System.out.println("5. After moves  : " + forts);  // prints a label followed by the value

        // 6. Loop: always in insertion order
        for (String fort : forts) {        // loops over every element of forts
            System.out.print(fort + " ");  // prints the result
        }
        System.out.println();              // prints an empty line

        // 7. Remove: remove, removeFirst, removeLast, removeAll, retainAll, removeIf
        forts.remove("Raigad");                            // removes "Raigad" from the set
        forts.removeFirst();                               // removes the first element
        forts.removeLast();                                // removes the last element
        System.out.println("7. After removes: " + forts);  // prints a label followed by the value
        forts.addAll(Set.of("Lohagad"));                   // adds every element of Set.of("Lohagad") to the set
        forts.retainAll(Set.of("Torna", "Lohagad"));       // keeps only the elements that are also in Set.of("Torna", "Lohagad")
        forts.removeAll(Set.of("Lohagad"));                // removes all elements that are in Set.of("Lohagad")
        forts.removeIf(f -> f.startsWith("Z"));            // removes every element that matches the condition

        // 8. Copy and compare: equals ignores the order
        LinkedHashSet<String> a = new LinkedHashSet<>(java.util.List.of("A", "B"));  // creates a LinkedHashSet filled with the listed values
        LinkedHashSet<String> b = new LinkedHashSet<>(java.util.List.of("B", "A"));  // creates a LinkedHashSet filled with the listed values
        System.out.println("8. equals       : " + a.equals(b));  // prints the comparison result

        // 9. clear
        forts.clear();                                     // removes every element from the set
        System.out.println("9. After clear  : " + forts);  // prints a label followed by the value
    }
}
// OUTPUT:
// 2. After adds   : [Torna, Raigad, Sinhagad]
// 3. size/isEmpty : 3 / false
//    contains     : true
// 4. first / last : Torna / Sinhagad
//    reversed     : [Sinhagad, Raigad, Torna]
// 5. After moves  : [Sinhagad, Torna, Raigad, Purandar]
// Sinhagad Torna Raigad Purandar
// 7. After removes: [Torna]
// 8. equals       : true
// 9. After clear  : []

