// SAMPLE PROJECT: Recently viewed forts (LinkedHashSet history)
import java.util.ArrayList;      // imports the ArrayList class
import java.util.LinkedHashSet;  // imports the LinkedHashSet class
import java.util.List;           // imports the List class

public class FortHistoryApp {     // class that holds the main method
    static class History {        // declares the History class
        private final LinkedHashSet<String> items = new LinkedHashSet<>();  // oldest ... newest
        private final int limit;  // field limit of type int

        History(int limit) {     // constructor
            this.limit = limit;  // stores limit in the field limit
        }

        // Step 2: record a visit
        void visit(String fort) {                      // method visit()
            items.remove(fort);                        // seen before? take it out so it can move
            items.add(fort);                           // add at the end = newest
            if (items.size() > limit) {                // checks the condition
                String dropped = items.removeFirst();  // too many: forget the oldest (Java 21)
                System.out.println("   (forgot " + dropped + ")");  // prints a label followed by the value
            }
        }

        // Step 3: read the history
        List<String> newestFirst() {                   // method newestFirst()
            return new ArrayList<>(items.reversed());  // returns the result to the caller
        }

        String oldest() {             // method oldest()
            return items.getFirst();  // returns the result to the caller
        }

        String newest() {            // method newest()
            return items.getLast();  // returns the result to the caller
        }
    }

    public static void main(String[] args) {  // program entry point
        // Step 1: a history that keeps only 4 forts
        History history = new History(4);  // creates a History object named history

        // Step 4: replay some visits
        String[] visits = {"Raigad", "Torna", "Sinhagad", "Raigad", "Purandar", "Lohagad", "Torna"};  // stores the value in visits
        for (String fort : visits) {                // loops over every element of visits
