// Real-time practice: recently viewed forts with LinkedHashSet
import java.util.ArrayList;      // imports the ArrayList class
import java.util.Iterator;       // imports the Iterator class
import java.util.LinkedHashSet;  // imports the LinkedHashSet class
import java.util.List;           // imports the List class

public class RecentlyViewed {    // class that holds the main method
    static final int LIMIT = 3;  // stores the value in LIMIT

    static void view(LinkedHashSet<String> recent, String fort) {  // method view()
        recent.remove(fort);                          // if it is there, move it to the end
        recent.add(fort);                             // adds fort to the set (a duplicate is ignored)
        Iterator<String> oldest = recent.iterator();  // stores the result: gets an iterator to walk the elements
        while (recent.size() > LIMIT) {               // repeats while the condition is true
            oldest.next();                            // moves to and returns the next element
            oldest.remove();                          // drop the oldest
        }
        System.out.println("viewed " + fort + " -> " + recent);  // prints a label followed by the value
    }

    public static void main(String[] args) {                   // program entry point
        LinkedHashSet<String> recent = new LinkedHashSet<>();  // creates an empty LinkedHashSet named recent
        view(recent, "Raigad");                                // calls the view() method
        view(recent, "Torna");                                 // calls the view() method
        view(recent, "Raigad");                                // moves Raigad to the end
        view(recent, "Lohagad");                               // calls the view() method
        view(recent, "Panhala");                               // Torna is now the oldest and falls out

        List<String> clicks = new ArrayList<>(List.of("Pune", "Mumbai", "Pune", "Nashik", "Mumbai", "Nagpur"));  // creates an ArrayList filled with the listed values
        List<String> unique = new ArrayList<>(new LinkedHashSet<>(clicks));  // creates an ArrayList named unique copied from new LinkedHashSet<>(click...
        System.out.println("Clicks            : " + clicks);  // prints a label followed by the value
        System.out.println("Unique, same order: " + unique);  // prints a label followed by the value
    }
}
// OUTPUT:
// viewed Raigad -> [Raigad]
// viewed Torna -> [Raigad, Torna]
// viewed Raigad -> [Torna, Raigad]
// viewed Lohagad -> [Torna, Raigad, Lohagad]
// viewed Panhala -> [Raigad, Lohagad, Panhala]
// Clicks            : [Pune, Mumbai, Pune, Nashik, Mumbai, Nagpur]
// Unique, same order: [Pune, Mumbai, Nashik, Nagpur]

// Practice: first non-repeating city in a stream, with a LinkedHashSet
import java.util.HashSet;        // imports the HashSet class
import java.util.LinkedHashSet;  // imports the LinkedHashSet class
import java.util.Set;            // imports the Set class

public class FirstUniqueCity {                // class that holds the main method
    public static void main(String[] args) {  // program entry point
        String[] stream = {"Pune", "Mumbai", "Pune", "Nashik", "Mumbai", "Nagpur", "Nashik", "Nagpur", "Kolhapur"};  // stores the value in stream

        LinkedHashSet<String> candidates = new LinkedHashSet<>();  // seen exactly once, in order
        Set<String> repeated = new HashSet<>();  // creates an empty HashSet named repeated

        for (String city : stream) {        // loops over every element of stream
            if (repeated.contains(city)) {  // checks whether the element is present
                // already known to repeat: nothing to do
            } else if (candidates.contains(city)) {  // checks the next condition
                candidates.remove(city);             // second time: no longer unique
                repeated.add(city);                  // adds city to the set (a duplicate is ignored)
            } else {                                 // runs when the condition is false
                candidates.add(city);                // first time
            }
            String first = candidates.isEmpty() ? "none" : candidates.iterator().next();  // stores the result: checks whether it has no elements
            System.out.println("after " + city + ": first unique = " + first);  // prints a label followed by the value
        }
    }
}
// OUTPUT:
// after Pune: first unique = Pune
// after Mumbai: first unique = Pune
// after Pune: first unique = Mumbai
// after Nashik: first unique = Mumbai
// after Mumbai: first unique = Nashik
// after Nagpur: first unique = Nashik
// after Nashik: first unique = Nagpur
// after Nagpur: first unique = none
// after Kolhapur: first unique = Kolhapur

