// Practice: union, intersection and difference that keep the order
import java.util.LinkedHashSet;  // imports the LinkedHashSet class
import java.util.List;           // imports the List class
import java.util.Set;            // imports the Set class

public class OrderedPlanMerge {               // class that holds the main method
    public static void main(String[] args) {  // program entry point
        List<String> planA = List.of("Pune", "Nashik", "Nagpur", "Indore");  // planA is an immutable list of the listed values
        List<String> planB = List.of("Nagpur", "Surat", "Pune");  // planB is an immutable list of the listed values

        Set<String> union = new LinkedHashSet<>(planA);  // creates a LinkedHashSet named union copied from planA
        union.addAll(planB);                             // new cities of B go to the end

        Set<String> shared = new LinkedHashSet<>(planA);  // creates a LinkedHashSet named shared copied from planA
        shared.retainAll(planB);                          // order of plan A

        Set<String> onlyB = new LinkedHashSet<>(planB);  // creates a LinkedHashSet named onlyB copied from planB
        onlyB.removeAll(planA);                          // removes all elements that are in planA

        System.out.println("Combined plan : " + union);   // prints a label followed by the value
        System.out.println("In both       : " + shared);  // prints a label followed by the value
        System.out.println("Only in B     : " + onlyB);   // prints a label followed by the value
    }
}
// OUTPUT:
// Combined plan : [Pune, Nashik, Nagpur, Indore, Surat]
// In both       : [Pune, Nagpur]
// Only in B     : [Surat]

// Practice: detect the first repeated city and print the loop
import java.util.ArrayList;      // imports the ArrayList class
import java.util.LinkedHashSet;  // imports the LinkedHashSet class
import java.util.List;           // imports the List class
import java.util.Set;            // imports the Set class

public class RouteLoopFinder {                // class that holds the main method
    public static void main(String[] args) {  // program entry point
        List<String> route = List.of("Pune", "Nashik", "Nagpur", "Indore", "Nashik", "Surat");  // route is an immutable list of the listed values

        Set<String> visited = new LinkedHashSet<>();  // creates an empty LinkedHashSet named visited
        String repeated = null;                       // stores the value in repeated
        for (String city : route) {                   // loops over every element of route
            if (!visited.add(city)) {                 // second visit found
                repeated = city;                      // assigns a new value to repeated
                break;                                // leaves the loop or switch
            }
        }

        if (repeated == null) {                     // checks for null
            System.out.println("No city repeats");  // prints the text "No city repeats"
            return;                                 // ends the method
        }

        List<String> loop = new ArrayList<>();            // creates an empty ArrayList named loop
        boolean collecting = false;                       // declares boolean collecting with value false
        for (String city : visited) {                     // insertion order = visiting order
            if (city.equals(repeated)) {                  // checks the condition
                collecting = true;                        // start from the first visit of the repeated city
            }
            if (collecting) {                             // checks the condition
                loop.add(city);                           // adds city to the end of the list
            }
        }
        loop.add(repeated);                               // close the loop
        System.out.println("First repeat: " + repeated);  // prints a label followed by the value
        System.out.println("Loop        : " + String.join(" -> ", loop));  // prints a label followed by the value
    }
}
// OUTPUT:
