// Practice: LRU cache built on a LinkedHashSet
import java.util.Iterator;       // imports the Iterator class
import java.util.LinkedHashSet;  // imports the LinkedHashSet class

public class FortCacheDemo {         // class that holds the main method
    static class FortCache {         // declares the FortCache class
        private final LinkedHashSet<String> cache = new LinkedHashSet<>();  // least recent ... most recent
        private final int capacity;  // field capacity of type int
        int hits;                    // declares hits of type int
        int misses;                  // declares misses of type int

        FortCache(int capacity) {      // constructor
            this.capacity = capacity;  // stores capacity in the field capacity
        }

        boolean request(String fort) {           // method request()
            boolean hit = cache.contains(fort);  // stores the result: checks whether fort is present
            if (hit) {                           // checks the condition
                hits++;                          // increments hits
                cache.remove(fort);              // refresh: it becomes the most recent
            } else {                             // runs when the condition is false
                misses++;                        // increments misses
                if (cache.size() == capacity) {  // checks the condition
                    Iterator<String> oldest = cache.iterator();  // stores the result: gets an iterator to walk the elements
                    oldest.next();               // the first element is the least recently used
                    oldest.remove();             // evict it
                }
            }
            cache.add(fort);                     // adds fort to the end of the list
            return hit;                          // returns the result to the caller
        }

        @Override
        public String toString() {    // text shown when the object is printed
            return cache.toString();  // returns the result to the caller
        }
    }

    public static void main(String[] args) {  // program entry point
        FortCache cache = new FortCache(3);   // creates a FortCache object named cache
        String[] requests = {"Raigad", "Torna", "Raigad", "Sinhagad", "Purandar", "Torna", "Raigad"};  // stores the value in requests

        for (String fort : requests) {          // loops over every element of requests
            boolean hit = cache.request(fort);  // declares boolean hit with value cache.request(fort)
            System.out.println(fort + " -> " + (hit ? "HIT " : "MISS") + " cache " + cache);  // prints the result
        }
        System.out.println("Hits " + cache.hits + ", misses " + cache.misses);  // prints a label followed by the value
    }
}
// OUTPUT:
// Raigad -> MISS cache [Raigad]
// Torna -> MISS cache [Raigad, Torna]
// Raigad -> HIT  cache [Torna, Raigad]
// Sinhagad -> MISS cache [Torna, Raigad, Sinhagad]
// Purandar -> MISS cache [Raigad, Sinhagad, Purandar]
// Torna -> MISS cache [Sinhagad, Purandar, Torna]
// Raigad -> MISS cache [Purandar, Torna, Raigad]
// Hits 1, misses 6

// TreeSet constructors: natural order, custom order, copy
import java.util.Comparator;  // imports the Comparator class
import java.util.List;        // imports the List class
