public class TreeSetCreateDemo {              // class that holds the main method
    public static void main(String[] args) {  // program entry point
        List<String> forts = List.of("Torna", "Raigad", "Sinhagad", "Purandar", "Raigad");  // forts is an immutable list of the listed values

        Set<String> natural = new TreeSet<>(forts);  // A to Z, duplicate Raigad dropped
