// MASTER PROGRAM: all important TreeSet methods in one program
import java.util.Comparator;  // imports the Comparator class
import java.util.Set;         // imports the Set class
import java.util.TreeSet;     // imports the TreeSet class

public class TreeSetMasterDemo {              // class that holds the main method
    public static void main(String[] args) {  // program entry point
        // 1. Create an empty TreeSet (always sorted)
        TreeSet<Integer> numbers = new TreeSet<>();  // creates an empty TreeSet named numbers

        // 2. add and addAll: sorted, duplicates ignored
        numbers.add(30);                                      // adds 30 to the set (a duplicate is ignored)
        numbers.add(10);                                      // adds 10 to the set (a duplicate is ignored)
        numbers.add(30);                                      // ignored
        numbers.addAll(Set.of(20, 40, 50));                   // adds every element of Set.of(20, 40, 50) to the set
        System.out.println("2. After adds    : " + numbers);  // prints a label followed by the value

        // 3. size, isEmpty, contains
        System.out.println("3. size/contains : " + numbers.size() + " / " + numbers.contains(20));  // prints the number of elements

        // 4. first and last
        System.out.println("4. first / last  : " + numbers.first() + " / " + numbers.last());  // prints the element or value read

        // 5. Nearest values: lower, floor, ceiling, higher
        System.out.println("5. lower(30)     : " + numbers.lower(30));  // prints the nearest element
        System.out.println("   floor(30)     : " + numbers.floor(30));  // prints the nearest element
        System.out.println("   ceiling(35)   : " + numbers.ceiling(35));  // prints the nearest element
        System.out.println("   higher(50)    : " + numbers.higher(50));  // prints the nearest element

        // 6. Range views: headSet, tailSet, subSet
        System.out.println("6. headSet(30)   : " + numbers.headSet(30));  // prints the selected range
        System.out.println("   tailSet(30)   : " + numbers.tailSet(30));  // prints the selected range
        System.out.println("   subSet(20, 40): " + numbers.subSet(20, 40));  // prints the selected range

        // 7. Reverse order: descendingSet, reversed
        System.out.println("7. descending    : " + numbers.descendingSet());  // prints a label followed by the value
        System.out.println("   reversed      : " + numbers.reversed());  // prints a label followed by the value

        // 8. Remove: remove, pollFirst, pollLast
        numbers.remove(30);                                   // removes the element at index 30
        System.out.println("8. pollFirst     : " + numbers.pollFirst());  // prints the removed element
        System.out.println("   pollLast      : " + numbers.pollLast());  // prints the removed element
        System.out.println("   Left          : " + numbers);  // prints a label followed by the value

        // 9. A custom order with a Comparator
        TreeSet<String> cities = new TreeSet<>(Comparator.reverseOrder());  // creates a TreeSet ordered by the given comparator
        cities.add("Pune");                                  // adds "Pune" to the set (a duplicate is ignored)
        cities.add("Agra");                                  // adds "Agra" to the set (a duplicate is ignored)
        System.out.println("9. Z to A        : " + cities);  // prints a label followed by the value

        // 10. clear
        numbers.clear();                                      // removes every element from the set
        System.out.println("10. After clear  : " + numbers);  // prints a label followed by the value
    }
}
