// TreeSet ordered by height then name
import java.util.Comparator;  // imports the Comparator class
import java.util.TreeSet;     // imports the TreeSet class

public class TreeSetSortMultiFieldDemo {      // class that holds the main method
    public static void main(String[] args) {  // program entry point
        record Fort(String name, int height) { }

        Comparator<Fort> order = Comparator.comparing(Fort::height, Comparator.reverseOrder())  // tallest first
                .thenComparing(Fort::name);  // tie-breaker

