import java.util.Comparator;  // imports the Comparator class
import java.util.TreeSet;     // imports the TreeSet class

public class LeaderboardExample {             // class that holds the main method
    public static void main(String[] args) {  // program entry point
        record Team(String city, int points) { }

        Comparator<Team> bestFirst = Comparator.comparing(Team::points, Comparator.reverseOrder())  // most points first
                .thenComparing(Team::city);  // tie-breaker

        TreeSet<Team> board = new TreeSet<>(bestFirst);  // creates a TreeSet named board copied from bestFirst
        board.add(new Team("Pune", 40));                 // adds new Team("Pune", 40) to the set (a duplicate is ignored)
        board.add(new Team("Nashik", 55));               // adds new Team("Nashik", 55) to the set (a duplicate is ignored)
        board.add(new Team("Nagpur", 40));               // adds new Team("Nagpur", 40) to the set (a duplicate is ignored)

        // Pune wins a match: remove the old entry, add the new one
        board.remove(new Team("Pune", 40));  // removes new Team("Pune", 40) from the set
        board.add(new Team("Pune", 60));     // adds new Team("Pune", 60) to the set (a duplicate is ignored)

        int rank = 1;              // declares int rank with value 1
        for (Team team : board) {  // loops over every element of board
            System.out.println(rank + ". " + team.city() + " " + team.points());  // prints the result
            rank++;                // increments rank
        }
    }
}
