// SAMPLE PROJECT: Fort ranking board (TreeSet with a Comparator)
import java.util.Comparator;  // imports the Comparator class
import java.util.TreeSet;     // imports the TreeSet class

public class FortRankingBoard {  // class that holds the main method
    // Step 1: the element and the ordering rule
    record Fort(String name, int height) { }

    static void printRanking(TreeSet<Fort> board) {  // method printRanking()
        int rank = 1;                                // declares int rank with value 1
        for (Fort fort : board) {                    // loops over every element of board
            System.out.println("  " + rank + ". " + fort.name() + " (" + fort.height() + " m)");  // prints a label followed by the value
            rank++;                                  // increments rank
        }
    }

    public static void main(String[] args) {                // program entry point
        Comparator<Fort> tallestFirst = Comparator.comparing(Fort::height, Comparator.reverseOrder())
                .thenComparing(Fort::name);
        TreeSet<Fort> board = new TreeSet<>(tallestFirst);  // creates a TreeSet named board copied from tallestFirst

        // Step 2: add in any order
        board.add(new Fort("Raigad", 1356));            // adds new Fort("Raigad", 1356) to the set (a duplicate is ignored)
        board.add(new Fort("Torna", 1403));             // adds new Fort("Torna", 1403) to the set (a duplicate is ignored)
        board.add(new Fort("Sinhagad", 1312));          // adds new Fort("Sinhagad", 1312) to the set (a duplicate is ignored)
        board.add(new Fort("Purandar", 1374));          // adds new Fort("Purandar", 1374) to the set (a duplicate is ignored)
        board.add(new Fort("Lohagad", 1033));           // adds new Fort("Lohagad", 1033) to the set (a duplicate is ignored)
        board.add(new Fort("Harishchandragad", 1424));  // adds new Fort("Harishchandragad", 1424) to the set (a duplicate is ignored)

        // Step 3: ranking, top 3, rank of one fort
        System.out.println("Ranking:");  // prints the text "Ranking:"
        printRanking(board);             // calls the printRanking() method

        System.out.println("Top 3:");  // prints the text "Top 3:"
        board.stream().limit(3).forEach(f -> System.out.println("  " + f.name()));  // creates a stream of the elements

        Fort raigad = new Fort("Raigad", 1356);         // creates a Fort object named raigad
        int rank = board.headSet(raigad).size() + 1;    // forts ranked before it, plus one
        System.out.println("Rank of Raigad: " + rank);  // prints a label followed by the value

        // Step 4: neighbours (the set is ordered tallest first, so "lower" means taller)
        Fort taller = board.lower(raigad);    // stores the result: finds the largest element < raigad
        Fort shorter = board.higher(raigad);  // stores the result: finds the smallest element > raigad
        System.out.println("Next taller than Raigad : " + taller.name());  // prints a label followed by the value
        System.out.println("Next shorter than Raigad: " + shorter.name());  // prints a label followed by the value

        // Step 5: a new measurement. Remove the old entry first, then add the updated one.
        board.remove(new Fort("Sinhagad", 1312));            // removes new Fort("Sinhagad", 1312) from the set
        board.add(new Fort("Sinhagad", 1380));               // adds new Fort("Sinhagad", 1380) to the set (a duplicate is ignored)
        System.out.println("After re-measuring Sinhagad:");  // prints the text "After re-measuring Sinhagad:"
        printRanking(board);                                 // calls the printRanking() method
    }
}
// OUTPUT:
// Ranking:
//   1. Harishchandragad (1424 m)
//   2. Torna (1403 m)
//   3. Purandar (1374 m)
//   4. Raigad (1356 m)
//   5. Sinhagad (1312 m)
//   6. Lohagad (1033 m)
// Top 3:
//   Harishchandragad
//   Torna
//   Purandar
// Rank of Raigad: 4
// Next taller than Raigad : Purandar
// Next shorter than Raigad: Sinhagad
// After re-measuring Sinhagad:
//   1. Harishchandragad (1424 m)
//   2. Torna (1403 m)
