// Real-time practice: booked time slots and a fort directory with TreeSet
import java.util.TreeSet;  // imports the TreeSet class

public class TrekSlotFinder {          // class that holds the main method
    static String time(int minutes) {  // method time()
        return String.format("%02d:%02d", minutes / 60, minutes % 60);  // returns the result to the caller
    }

    public static void main(String[] args) {                   // program entry point
        TreeSet<Integer> booked = new TreeSet<>();             // creates an empty TreeSet named booked
        for (int hour : new int[] {9, 11, 6, 14, 8}) {         // loops over every element of new int[] {9, 11, 6, 14, 8}
            booked.add(hour * 60);                             // minutes from midnight
        }
        System.out.print("Booked slots : ");                   // prints the text "Booked slots : "
        booked.forEach(m -> System.out.print(time(m) + " "));  // runs the given action for every element
        System.out.println();                                  // prints an empty line

        int wanted = 10 * 60;  // a customer wants 10:00
        System.out.println("Slot before 10:00 : " + time(booked.lower(wanted)));  // prints the nearest element
        System.out.println("Slot after  10:00 : " + time(booked.higher(wanted)));  // prints the nearest element
        System.out.println("Wanted 10:00 free?: " + !booked.contains(wanted));  // prints whether the element is present

        System.out.print("Between 08:00 and 12:00 : ");  // prints the text "Between 08:00 and 12:00 : "
        booked.subSet(8 * 60, true, 12 * 60, true).forEach(m -> System.out.print(time(m) + " "));  // takes the range from 8 * 60 to true
        System.out.println();                            // prints an empty line

        System.out.println("Earliest: " + time(booked.first()) + ", latest: " + time(booked.last()));  // prints the element or value read
        System.out.println("Served and removed: " + time(booked.pollFirst()) + ", left " + booked.size());  // prints the number of elements

        TreeSet<String> directory = new TreeSet<>(String.CASE_INSENSITIVE_ORDER);  // creates a TreeSet named directory copied from String.CASE_INSENSITIVE_O...
        directory.add("torna");                         // adds "torna" to the set (a duplicate is ignored)
        directory.add("Raigad");                        // adds "Raigad" to the set (a duplicate is ignored)
        directory.add("lohagad");                       // adds "lohagad" to the set (a duplicate is ignored)
        directory.add("RAIGAD");                        // same as Raigad: ignored
        System.out.println("Directory: " + directory);  // prints a label followed by the value
        System.out.println("First fort starting with R or later: " + directory.ceiling("R"));  // prints the nearest element
    }
}
// OUTPUT:
// Booked slots : 06:00 08:00 09:00 11:00 14:00
// Slot before 10:00 : 09:00
// Slot after  10:00 : 11:00
// Wanted 10:00 free?: true
// Between 08:00 and 12:00 : 08:00 09:00 11:00
// Earliest: 06:00, latest: 14:00
// Served and removed: 06:00, left 4
// Directory: [lohagad, Raigad, torna]
// First fort starting with R or later: Raigad

// Practice: overlap-free slot booking with a TreeSet
import java.util.Comparator;  // imports the Comparator class
import java.util.TreeSet;     // imports the TreeSet class

public class SlotBooking {  // class that holds the main method
    record Slot(int start, int end) { }

    static boolean book(TreeSet<Slot> booked, Slot wanted) {    // method book()
        Slot before = booked.floor(wanted);                     // starts at or before the new start
        Slot after = booked.ceiling(wanted);                    // starts at or after the new start
        if (before != null && before.end() > wanted.start()) {  // checks for null
            return false;                                       // the earlier booking runs into it
        }
        if (after != null && after.start() < wanted.end()) {    // checks for null
            return false;                                       // it runs into the next booking
        }
        return booked.add(wanted);                              // returns the result to the caller
    }

    public static void main(String[] args) {               // program entry point
        TreeSet<Slot> booked = new TreeSet<>(Comparator.comparingInt(Slot::start));  // creates a TreeSet ordered by the given comparator
        Slot[] requests = {new Slot(9, 11), new Slot(13, 15), new Slot(11, 13), new Slot(10, 12), new Slot(15, 17), new Slot(8, 10)};  // stores the value in requests
        for (Slot s : requests) {                          // loops over every element of requests
