// Practice: closest value using floor and ceiling
import java.util.Set;      // imports the Set class
import java.util.TreeSet;  // imports the TreeSet class

public class ClosestHeight {                                    // class that holds the main method
    static int closest(TreeSet<Integer> heights, int target) {  // method closest()
        Integer below = heights.floor(target);                  // largest value <= target
        Integer above = heights.ceiling(target);                // smallest value >= target
        if (below == null) {                                    // checks for null
            return above;                                       // returns the result to the caller
        }
        if (above == null) {                                    // checks for null
            return below;                                       // returns the result to the caller
        }
        return (target - below) <= (above - target) ? below : above;  // tie -> lower
    }

    public static void main(String[] args) {  // program entry point
        TreeSet<Integer> heights = new TreeSet<>(Set.of(1033, 1312, 1356, 1403));  // creates a TreeSet filled with the listed values

        for (int target : new int[] {1000, 1340, 1334, 1380, 1500}) {  // loops over every element of new int[] {1000, 1340, 1334,...
            System.out.println("Target " + target + " -> closest " + closest(heights, target));  // prints a label followed by the value
        }
    }
}
// OUTPUT:
// Target 1000 -> closest 1033
// Target 1340 -> closest 1356
// Target 1334 -> closest 1312
// Target 1380 -> closest 1403
// Target 1500 -> closest 1403

// Practice: counting by range with headSet, subSet and tailSet
