// Practice: contains nearby almost duplicate (TreeSet sliding window)
import java.util.TreeSet;  // imports the TreeSet class

public class NearbyAlmostDuplicate {                            // class that holds the main method
    static boolean exists(int[] nums, int k, int t) {           // method exists()
        TreeSet<Long> window = new TreeSet<>();                 // long avoids overflow near the int limits
        for (int i = 0; i < nums.length; i++) {                 // loops through all the indexes
            long value = nums[i];                               // declares long value with value nums[i]
            Long candidate = window.ceiling(value - t);         // smallest number >= value - t
            if (candidate != null && candidate <= value + t) {  // checks for null
                return true;                                    // found one within t of value
            }
            window.add(value);                                  // adds value to the set (a duplicate is ignored)
            if (i >= k) {                                       // checks the condition
                window.remove((long) nums[i - k]);              // number left the window of size k
            }
        }
        return false;                                           // returns the result to the caller
    }

    public static void main(String[] args) {  // program entry point
        System.out.println(exists(new int[] {1, 2, 3, 1}, 3, 0));  // prints the result
        System.out.println(exists(new int[] {1, 0, 1, 1}, 1, 2));  // prints the result
        System.out.println(exists(new int[] {1, 5, 9, 1, 5, 9}, 2, 3));  // prints the result
    }
}
// OUTPUT:
// true
// true
// false

