// Map.of / Map.entry / Map.ofEntries / Map.copyOf: immutable maps
import java.util.HashMap;  // imports the HashMap class
import java.util.Map;      // imports the Map class
import java.util.TreeMap;  // imports the TreeMap class

public class HashMapImmutableDemo {           // class that holds the main method
    public static void main(String[] args) {  // program entry point
        Map<String, Integer> small = Map.of("Pune", 20, "Mumbai", 22);  // small is an immutable map of the listed values
        Map<String, Integer> many = Map.ofEntries(
                Map.entry("Delhi", 11), Map.entry("Chennai", 44), Map.entry("Kochi", 484));  // calls entry() on Map

        try {                                           // code that may throw an exception
            small.put("Nagpur", 712);                   // maps key "Nagpur" to value 712
        } catch (UnsupportedOperationException e) {     // handles UnsupportedOperationException
            System.out.println("Map.of is immutable");  // prints the text "Map.of is immutable"
        }
        try {                                           // code that may throw an exception
            Map.of("Pune", 20, "Pune", 2020);           // calls of() on Map
        } catch (IllegalArgumentException e) {          // handles IllegalArgumentException
            System.out.println("Duplicate key rejected: " + e.getMessage());  // prints a label followed by the value
        }

        Map<String, Integer> editable = new HashMap<>(small);  // a modifiable copy
        editable.putAll(many);                                 // copies every entry of many into the map
        System.out.println(new TreeMap<>(editable));           // prints the result
    }
}
// OUTPUT:
// Map.of is immutable
// Duplicate key rejected: duplicate key: Pune
// {Chennai=44, Delhi=11, Kochi=484, Mumbai=22, Pune=20}

// MASTER PROGRAM: all important HashMap methods in one program
import java.util.ArrayList;  // imports the ArrayList class
import java.util.HashMap;    // imports the HashMap class
import java.util.List;       // imports the List class
import java.util.Map;        // imports the Map class

public class HashMapMasterDemo {              // class that holds the main method
    public static void main(String[] args) {  // program entry point
        // 1. Create an empty map: fort name -> height in metres
        Map<String, Integer> heights = new HashMap<>();  // creates an empty HashMap named heights

        // 2. put: add or replace (returns the old value)
        heights.put("Raigad", 820);  // maps key "Raigad" to value 820
        heights.put("Torna", 1400);  // maps key "Torna" to value 1400
        System.out.println("2. put again      : " + heights.put("Raigad", 900));  // prints the result of the add

        // 3. putAll and putIfAbsent
        heights.putAll(Map.of("Sinhagad", 1300));  // copies every entry of Map.of("Sinhagad", 1300) into the map
        heights.putIfAbsent("Raigad", 1);          // ignored: key exists
        heights.putIfAbsent("Purandar", 1200);     // added
        System.out.println("3. After puts     : " + new java.util.TreeMap<>(heights));  // prints a label followed by the value

        // 4. get and getOrDefault
        System.out.println("4. get Raigad     : " + heights.get("Raigad"));  // prints the element or value read
        System.out.println("   get missing    : " + heights.get("Lohagad"));  // prints the element or value read
        System.out.println("   getOrDefault   : " + heights.getOrDefault("Lohagad", 0));  // prints the element or value read

        // 5. containsKey, containsValue, size, isEmpty
        System.out.println("5. containsKey    : " + heights.containsKey("Torna"));  // prints whether the element is present
        System.out.println("   containsValue  : " + heights.containsValue(1400));  // prints whether the element is present
        System.out.println("   size / isEmpty : " + heights.size() + " / " + heights.isEmpty());  // prints the number of elements

        // 6. replace and replaceAll
        heights.replace("Torna", 1403);          // calls replace() on heights
        heights.replaceAll((fort, h) -> h + 1);  // add 1 to every height
        System.out.println("6. Torna          : " + heights.get("Torna"));  // prints the element or value read

        // 7. compute, computeIfPresent, computeIfAbsent, merge
        heights.compute("Raigad", (fort, h) -> h == null ? 1 : h + 10);  // computes the value for the key
        heights.computeIfPresent("Torna", (fort, h) -> h + 10);  // computes the value for the key
        heights.computeIfAbsent("Lohagad", fort -> 1033);  // computes the value for the key
        heights.merge("Torna", 5, Integer::sum);           // combines the old and new value for the key
        System.out.println("7. Torna / Lohagad: " + heights.get("Torna") + " / " + heights.get("Lohagad"));  // prints the element or value read

        // 8. Group values into lists with computeIfAbsent
        Map<String, List<String>> byDistrict = new HashMap<>();  // creates an empty HashMap named byDistrict
        byDistrict.computeIfAbsent("Pune", d -> new ArrayList<>()).add("Sinhagad");  // computes the value for the key
        byDistrict.computeIfAbsent("Pune", d -> new ArrayList<>()).add("Torna");  // computes the value for the key
        System.out.println("8. Pune forts     : " + byDistrict.get("Pune"));  // prints the element or value read

        // 9. Three views: keySet, values, entrySet
        System.out.println("9. keys count     : " + heights.keySet().size());  // prints the number of elements
        System.out.println("   values count   : " + heights.values().size());  // prints the number of elements
        for (Map.Entry<String, Integer> e : new java.util.TreeMap<>(heights).entrySet()) {  // loops over every element of new java.util.TreeMap<>(heigh...
            System.out.println("   " + e.getKey() + " = " + e.getValue());  // prints a label followed by the value
        }

        // 10. forEach
        heights.forEach((fort, h) -> { if (h > 1400) System.out.println("   tall: " + fort); });  // runs the given action for every element

        // 11. remove by key, remove by key and value
        heights.remove("Lohagad");   // removes the entry for key "Lohagad"
        heights.remove("Torna", 0);  // value does not match: nothing removed
        System.out.println("11. After removes    : " + heights.size());  // prints the number of elements

        // 12. copy and equals
        Map<String, Integer> copy = new HashMap<>(heights);  // creates a HashMap named copy copied from heights
        System.out.println("12. equals copy      : " + heights.equals(copy));  // prints the comparison result

        // 13. clear
        heights.clear();  // removes every element from the map
        System.out.println("13. After clear      : " + heights);  // prints a label followed by the value
    }
}
