// Real-time example: marks lookup by roll number
import java.util.*;  // imports every class of java.util

public class HmMarksLookup {  // class that holds the main method
    record Student(String name, int marks) { }

    public static void main(String[] args) {             // program entry point
        Map<Integer, Student> byRoll = new HashMap<>();  // creates an empty HashMap named byRoll
        byRoll.put(101, new Student("Asha", 78));        // maps key 101 to value new Student("Asha", 78)
        byRoll.put(102, new Student("Ravi", 64));        // maps key 102 to value new Student("Ravi", 64)
        byRoll.put(103, new Student("Meera", 91));       // maps key 103 to value new Student("Meera", 91)

        for (int roll : new int[]{102, 110}) {  // loops over every element of new int[]{102, 110}
            Student s = byRoll.get(roll);       // O(1) lookup by key
            if (s == null) {                    // checks for null
                System.out.println("Roll " + roll + ": not found");  // prints a label followed by the value
            } else {                            // runs when the condition is false
                System.out.println("Roll " + roll + ": " + s.name() + " scored " + s.marks());  // prints a label followed by the value
            }
        }

        // grace marks for roll 102 only, because the key exists
        byRoll.computeIfPresent(102, (roll, s) -> new Student(s.name(), s.marks() + 5));  // computes the value for the key
        System.out.println("After grace: " + byRoll.get(102));  // prints the element or value read
    }
}
// OUTPUT:
// Roll 102: Ravi scored 64
// Roll 110: not found
// After grace: Student[name=Ravi, marks=69]

// Real-time example: a small cache in front of a slow lookup
import java.util.*;  // imports every class of java.util

public class HmPriceCache {        // class that holds the main method
    static int databaseCalls = 0;  // stores the value in databaseCalls

    static int slowFeeLookup(String fort) {  // pretend this talks to a database
        databaseCalls++;                     // increments databaseCalls
        return fort.length() * 10;           // returns the result to the caller
    }

    static final Map<String, Integer> cache = new HashMap<>();  // creates an empty HashMap named cache

    static int feeOf(String fort) {        // method feeOf()
        Integer cached = cache.get(fort);  // 1. look in the cache first
        if (cached != null) {              // checks for null
            return cached;                 // returns the result to the caller
        }
        int fee = slowFeeLookup(fort);     // 2. miss: do the slow work
        cache.put(fort, fee);              // 3. remember it
        return fee;                        // returns the result to the caller
    }

    public static void main(String[] args) {              // program entry point
