// Sample project: Fort Visitor Register built on HashMap
import java.util.*;  // imports every class of java.util

public class HmVisitorRegister {  // class that holds the main method
    record Visit(String fort, String visitor, int tickets) { }

    public static void main(String[] args) {  // program entry point
        // Step 1: the visit log
        List<Visit> log = List.of(
                new Visit("Raigad", "Asha", 2),
                new Visit("Torna", "Ravi", 1),
                new Visit("Raigad", "Meera", 3),
                new Visit("Sinhagad", "Asha", 4),
                new Visit("Torna", "Kiran", 2),
                new Visit("Raigad", "Ravi", 1),
                new Visit("Panhala", "Meera", 1));

        // Step 2: entry fee per ticket
        Map<String, Integer> fee = new HashMap<>();  // creates an empty HashMap named fee
        fee.put("Raigad", 50);                       // maps key "Raigad" to value 50
        fee.put("Torna", 30);                        // maps key "Torna" to value 30
        fee.put("Sinhagad", 20);                     // maps key "Sinhagad" to value 20

        // Step 3: tickets per fort
        Map<String, Integer> tickets = new HashMap<>();  // creates an empty HashMap named tickets
        // Step 4: visitor names per fort
        Map<String, List<String>> visitors = new HashMap<>();  // creates an empty HashMap named visitors
        for (Visit v : log) {                                  // loops over every element of log
            tickets.merge(v.fort(), v.tickets(), Integer::sum);  // combines the old and new value for the key
            visitors.computeIfAbsent(v.fort(), k -> new ArrayList<>()).add(v.visitor());  // computes the value for the key
        }

        // Step 5: revenue per fort (a fort without a fee is skipped) and the busiest fort
        Map<String, Integer> revenue = new HashMap<>();  // creates an empty HashMap named revenue
        for (Map.Entry<String, Integer> e : tickets.entrySet()) {  // loops over every element of tickets.entrySet()
            Integer perTicket = fee.get(e.getKey());     // stores the result: reads the value stored for key e.getKey()
            if (perTicket != null) {                     // checks for null
                revenue.put(e.getKey(), e.getValue() * perTicket);  // maps key e.getKey() to value e.getValue() * perTicket
            }
        }
        String busiest = Collections.max(tickets.entrySet(), Map.Entry.comparingByValue()).getKey();  // stores the value in busiest

        // Step 6: report in A to Z order
        System.out.println("Fort        Tickets  Revenue  Visitors");  // prints the text "Fort        Tickets  Revenu..."
        for (String fort : new TreeMap<>(tickets).keySet()) {  // loops over every element of new TreeMap<>(tickets).keySet...
            System.out.printf("%-10s  %7d  %7s  %s%n", fort, tickets.get(fort),
                    revenue.containsKey(fort) ? revenue.get(fort) : "no fee", visitors.get(fort));  // checks whether key fort) ? revenue.get(fort) : "no f... exists
        }
        System.out.println("Busiest fort : " + busiest);       // prints a label followed by the value
        System.out.println("Total revenue: " + revenue.values().stream().mapToInt(Integer::intValue).sum());  // prints the keys, values or entries
    }
}
// OUTPUT:
// Fort        Tickets  Revenue  Visitors
// Panhala           1   no fee  [Meera]
// Raigad            6      300  [Asha, Meera, Ravi]
// Sinhagad          4       80  [Asha]
// Torna             3       90  [Ravi, Kiran]
// Busiest fort : Raigad
// Total revenue: 470

// Real-time practice: a trek-gear inventory with HashMap
import java.util.ArrayList;  // imports the ArrayList class
import java.util.HashMap;    // imports the HashMap class
import java.util.List;       // imports the List class
import java.util.Map;        // imports the Map class
import java.util.TreeMap;    // imports the TreeMap class

public class TrekKitInventory {                        // class that holds the main method
    public static void main(String[] args) {           // program entry point
        Map<String, Integer> stock = new HashMap<>();  // creates an empty HashMap named stock
        stock.put("Rope", 10);                         // maps key "Rope" to value 10
        stock.put("Torch", 25);                        // maps key "Torch" to value 25
        stock.put("Boots", 6);                         // maps key "Boots" to value 6
        stock.put("Raincoat", 12);                     // maps key "Raincoat" to value 12

        // Customers buy items
        String[] sales = {"Torch", "Boots", "Torch", "Rope", "Boots", "Boots", "Map"};  // stores the value in sales
        Map<String, Integer> soldCount = new HashMap<>();  // creates an empty HashMap named soldCount
        for (String item : sales) {                        // loops over every element of sales
            int left = stock.getOrDefault(item, 0);        // stores the result: reads the value for item or 0 if the key is missing
            if (left == 0) {                               // checks the condition
                System.out.println("Cannot sell " + item + ": out of stock or unknown");  // prints a label followed by the value
                continue;                                  // skips to the next iteration
            }
            stock.put(item, left - 1);                     // reduce stock
            soldCount.merge(item, 1, Integer::sum);        // count sales
        }
        System.out.println("Sold   : " + new TreeMap<>(soldCount));  // prints a label followed by the value
        System.out.println("Stock  : " + new TreeMap<>(stock));  // prints a label followed by the value

        // Low stock report
        for (Map.Entry<String, Integer> e : new TreeMap<>(stock).entrySet()) {  // loops over every element of new TreeMap<>(stock).entrySet...
            if (e.getValue() < 5) {  // checks the condition
                System.out.println("LOW STOCK: " + e.getKey() + " (" + e.getValue() + " left)");  // prints a label followed by the value
            }
        }

        // Group items by category
        Map<String, List<String>> byCategory = new TreeMap<>();  // creates an empty TreeMap named byCategory
        String[][] items = {{"Rope", "Climbing"}, {"Torch", "Light"}, {"Boots", "Footwear"}, {"Raincoat", "Clothing"}, {"Headlamp", "Light"}};  // stores the value in items
        for (String[] item : items) {                     // loops over every element of items
            byCategory.computeIfAbsent(item[1], k -> new ArrayList<>()).add(item[0]);  // computes the value for the key
        }
        System.out.println("Categories: " + byCategory);  // prints a label followed by the value

        stock.values().removeIf(count -> count == 0);  // sold-out items disappear
        System.out.println("Still stocked: " + new TreeMap<>(stock).keySet());  // prints the keys, values or entries
    }
}
// OUTPUT:
// Cannot sell Map: out of stock or unknown
// Sold   : {Boots=3, Rope=1, Torch=2}
// Stock  : {Boots=3, Raincoat=12, Rope=9, Torch=23}
// LOW STOCK: Boots (3 left)
// Categories: {Climbing=[Rope], Clothing=[Raincoat], Footwear=[Boots], Light=[Torch, Headlamp]}
// Still stocked: [Boots, Raincoat, Rope, Torch]

// Practice: top-3 frequent cities and "two sum" with HashMap
import java.util.ArrayList;  // imports the ArrayList class
import java.util.HashMap;    // imports the HashMap class
import java.util.List;       // imports the List class
import java.util.Map;        // imports the Map class

public class TopCitiesAndPairs {                        // class that holds the main method
    public static void main(String[] args) {            // program entry point
        String[] log = {"Pune", "Mumbai", "Pune", "Nashik", "Mumbai", "Pune", "Nagpur", "Nashik", "Kolhapur", "Nagpur"};  // stores the value in log
        Map<String, Integer> visits = new HashMap<>();  // creates an empty HashMap named visits
        for (String city : log) {                       // loops over every element of log
            visits.merge(city, 1, Integer::sum);        // combines the old and new value for the key
        }

        List<Map.Entry<String, Integer>> ranked = new ArrayList<>(visits.entrySet());  // creates an ArrayList named ranked copied from visits.entrySet()
        ranked.sort(Map.Entry.<String, Integer>comparingByValue().reversed().thenComparing(Map.Entry.comparingByKey()));  // sorts using the given comparator
        for (int i = 0; i < 3; i++) {  // counting loop
            System.out.println((i + 1) + ". " + ranked.get(i).getKey() + " (" + ranked.get(i).getValue() + " visits)");  // prints the element or value read
        }

        String[] forts = {"Raigad", "Torna", "Lohagad", "Purandar", "Sinhagad"};  // stores the value in forts
        int[] heights = {820, 1403, 1033, 1374, 1312};       // stores the value in heights
        int target = 2777;                                   // declares int target with value 2777
        Map<Integer, String> seen = new HashMap<>();         // height -> fort
        for (int i = 0; i < forts.length; i++) {             // loops through all the indexes
            String partner = seen.get(target - heights[i]);  // stores the result: reads the value stored for key target - heights[i]
            if (partner != null) {                           // checks for null
                System.out.println("Pair for " + target + " m: " + partner + " + " + forts[i]);  // prints a label followed by the value
                break;                                       // leaves the loop or switch
            }
            seen.put(heights[i], forts[i]);                  // maps key heights[i] to value forts[i]
        }
    }
}
// OUTPUT:
// 1. Pune (3 visits)
// 2. Mumbai (2 visits)
// 3. Nagpur (2 visits)
// Pair for 2777 m: Torna + Purandar

