// Practice: memoization with HashMap
import java.util.*;  // imports every class of java.util

public class HmMemoRoutes {                                   // class that holds the main method
    static long ways(int n, Map<Integer, Long> memo) {        // method ways()
        if (n <= 2) {                                         // checks the condition
            return n;                                         // 1 way for 1 step, 2 ways for 2 steps
        }
        Long saved = memo.get(n);                             // stores the result: reads the value stored for key n
        if (saved != null) {                                  // checks for null
            return saved;                                     // already solved: reuse
        }
        long result = ways(n - 1, memo) + ways(n - 2, memo);  // declares long result with value ways(n - 1, memo) +...
        memo.put(n, result);                                  // remember for next time
        return result;                                        // returns the result to the caller
    }

    public static void main(String[] args) {        // program entry point
        Map<Integer, Long> memo = new HashMap<>();  // creates an empty HashMap named memo
        System.out.println("Ways to climb 40 steps: " + ways(40, memo));  // prints a label followed by the value
        System.out.println("Values saved in memo  : " + memo.size());  // prints the number of elements
    }
}
// OUTPUT:
// Ways to climb 40 steps: 165580141
// Values saved in memo  : 38

