// MASTER PROGRAM: all important LinkedHashMap methods in one program
import java.util.LinkedHashMap;  // imports the LinkedHashMap class
import java.util.Map;            // imports the Map class

public class LinkedHashMapMasterDemo {        // class that holds the main method
    public static void main(String[] args) {  // program entry point
        // 1. Create an empty map (it remembers insertion order)
        LinkedHashMap<String, Integer> heights = new LinkedHashMap<>();  // creates an empty LinkedHashMap named heights

        // 2. put, putIfAbsent, putAll
        heights.put("Torna", 1400);                // maps key "Torna" to value 1400
        heights.put("Raigad", 820);                // maps key "Raigad" to value 820
        heights.putIfAbsent("Sinhagad", 1300);     // stores 1300 for key "Sinhagad" only if the key has no value yet
        heights.putAll(Map.of("Purandar", 1200));  // copies every entry of Map.of("Purandar", 1200) into the map
        System.out.println("2. size           : " + heights.size());  // prints the number of elements

        // 3. Java 21: putFirst and putLast
        heights.putFirst("Rajgad", 1300);                      // calls putFirst() on heights
        heights.putLast("Lohagad", 1033);                      // calls putLast() on heights
        System.out.println("3. After puts     : " + heights);  // prints a label followed by the value

        // 4. get, getOrDefault, containsKey, containsValue
        System.out.println("4. get            : " + heights.get("Raigad"));  // prints the element or value read
        System.out.println("   getOrDefault   : " + heights.getOrDefault("Panhala", 0));  // prints the element or value read
        System.out.println("   containsKey    : " + heights.containsKey("Torna"));  // prints whether the element is present
        System.out.println("   containsValue  : " + heights.containsValue(820));  // prints whether the element is present

        // 5. Change values: replace, merge, compute
        heights.replace("Raigad", 900);             // calls replace() on heights
        heights.merge("Raigad", 10, Integer::sum);  // combines the old and new value for the key
        heights.compute("Torna", (k, v) -> v + 3);  // computes the value for the key
        System.out.println("5. Raigad / Torna : " + heights.get("Raigad") + " / " + heights.get("Torna"));  // prints the element or value read

        // 6. Views and loops: always in insertion order
        System.out.println("6. keys           : " + heights.keySet());  // prints the keys, values or entries
        System.out.println("   values         : " + heights.values());  // prints the keys, values or entries
        heights.forEach((fort, h) -> System.out.print(fort + " "));  // runs the given action for every element
        System.out.println();  // prints an empty line

        // 7. Java 21: firstEntry, lastEntry, reversed
        System.out.println("7. first / last   : " + heights.firstEntry() + " / " + heights.lastEntry());  // prints a label followed by the value
        System.out.println("   reversed       : " + heights.reversed());  // prints a label followed by the value

        // 8. Remove: remove, pollFirstEntry, pollLastEntry
        heights.remove("Purandar");                            // removes the entry for key "Purandar"
        heights.pollFirstEntry();                              // removes and returns the first/last entry
        heights.pollLastEntry();                               // removes and returns the first/last entry
        System.out.println("8. After removes  : " + heights);  // prints a label followed by the value

        // 9. Access order: reading a key moves it to the end
        LinkedHashMap<String, Integer> recent = new LinkedHashMap<>(16, 0.75f, true);  // creates a LinkedHashMap named recent copied from 16, 0.75f, true
        recent.put("A", 1);                                   // maps key "A" to value 1
        recent.put("B", 2);                                   // maps key "B" to value 2
        recent.get("A");                                      // reads the value stored for key "A"
        System.out.println("9. access order   : " + recent);  // prints a label followed by the value

        // 10. equals ignores order; clear
        LinkedHashMap<String, Integer> x = new LinkedHashMap<>(Map.of("A", 1));  // creates a LinkedHashMap named x copied from Map.of("A", 1)
        System.out.println("10. equals        : " + x.equals(Map.of("A", 1)));  // prints the comparison result
        heights.clear();                                       // removes every element from the map
        System.out.println("    After clear   : " + heights);  // prints a label followed by the value
    }
}
// OUTPUT:
// 2. size           : 4
// 3. After puts     : {Rajgad=1300, Torna=1400, Raigad=820, Sinhagad=1300, Purandar=1200, Lohagad=1033}
// 4. get            : 820
//    getOrDefault   : 0
//    containsKey    : true
//    containsValue  : true
// 5. Raigad / Torna : 910 / 1403
// 6. keys           : [Rajgad, Torna, Raigad, Sinhagad, Purandar, Lohagad]
//    values         : [1300, 1403, 910, 1300, 1200, 1033]
// Rajgad Torna Raigad Sinhagad Purandar Lohagad
// 7. first / last   : Rajgad=1300 / Lohagad=1033
//    reversed       : {Lohagad=1033, Purandar=1200, Sinhagad=1300, Raigad=910, Torna=1403, Rajgad=1300}
// 8. After removes  : {Torna=1403, Raigad=910, Sinhagad=1300}
// 9. access order   : {B=2, A=1}
// 10. equals        : true
//     After clear   : {}

