    public static void main(String[] args) {  // program entry point
        // Step 1: stops in visiting order
        LinkedHashMap<String, Integer> plan = new LinkedHashMap<>();  // creates an empty LinkedHashMap named plan
        plan.put("Sinhagad", 2);              // maps key "Sinhagad" to value 2
        plan.put("Purandar", 3);              // maps key "Purandar" to value 3
        plan.put("Torna", 4);                 // maps key "Torna" to value 4
        printTimeline("Initial plan", plan);  // calls the printTimeline() method

        // Step 2: a quick breakfast stop is added at the front
        plan.putFirst("Lohagad", 1);  // calls putFirst() on plan

        // Step 3: Sinhagad has the best sunset view, so it moves to the end
        plan.putLast("Sinhagad", 2);          // calls putLast() on plan
        printTimeline("Updated plan", plan);  // calls the printTimeline() method

        // Step 5: longest stop and total hours
        Map.Entry<String, Integer> longest = Collections.max(plan.entrySet(), Map.Entry.comparingByValue());  // stores the value in longest
        int total = plan.values().stream().mapToInt(Integer::intValue).sum();  // stores the result: gets the collection of values
        System.out.println("Longest stop : " + longest.getKey() + " (" + longest.getValue() + " h)");  // prints a label followed by the value
        System.out.println("Total hours  : " + total);  // prints a label followed by the value
        System.out.println("First / last : " + plan.firstEntry().getKey() + " / " + plan.lastEntry().getKey());  // prints a label followed by the value

        // Step 6: the way back is the same map, reversed
        System.out.println("Return route : " + String.join(" -> ", plan.reversed().keySet()));  // prints the keys, values or entries
    }
}
// OUTPUT:
// Initial plan
//   08:00  Sinhagad   (2 h)
//   10:00  Purandar   (3 h)
//   13:00  Torna      (4 h)
//   17:00  tour ends
// Updated plan
//   08:00  Lohagad    (1 h)
//   09:00  Purandar   (3 h)
//   12:00  Torna      (4 h)
//   16:00  Sinhagad   (2 h)
//   18:00  tour ends
// Longest stop : Torna (4 h)
// Total hours  : 10
// First / last : Lohagad / Sinhagad
// Return route : Sinhagad -> Torna -> Purandar -> Lohagad

// Real-time practice: an LRU page cache with LinkedHashMap
import java.util.LinkedHashMap;  // imports the LinkedHashMap class
import java.util.Map;            // imports the Map class

public class FortPageCache {                                   // class that holds the main method
    static class LruCache<K, V> extends LinkedHashMap<K, V> {  // LruCache class extending LinkedHashMap<K, V>
        private final int capacity;                            // field capacity of type int

        LruCache(int capacity) {       // constructor
            super(16, 0.75f, true);    // true = access order
            this.capacity = capacity;  // stores capacity in the field capacity
        }

        @Override
        protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {  // method removeEldestEntry()
            return size() > capacity;  // evict the least recently used
        }
    }

    static int hits = 0;    // stores the value in hits
    static int misses = 0;  // stores the value in misses

    static String load(LruCache<String, String> cache, String fort) {  // method load()
        String page = cache.get(fort);  // stores the result: reads the element at index fort
        if (page == null) {             // checks for null
            misses++;                   // increments misses
            page = "Page of " + fort;   // pretend this is slow work
            cache.put(fort, page);      // maps key fort to value page
        } else {                        // runs when the condition is false
            hits++;                     // increments hits
        }
        return page;                    // returns the result to the caller
    }

    public static void main(String[] args) {                 // program entry point
        LruCache<String, String> cache = new LruCache<>(3);  // creates a LruCache object named cache
        for (String fort : new String[] {"Raigad", "Torna", "Lohagad", "Raigad", "Panhala", "Torna", "Raigad"}) {  // loops over every element of new String[] {"Raigad", "Torn...
            load(cache, fort);                               // calls the load() method
            System.out.println("request " + fort + " -> cache " + cache.keySet());  // prints the keys, values or entries
        }
        System.out.println("hits=" + hits + " misses=" + misses);  // prints a label followed by the value
    }
}
// OUTPUT:
// request Raigad -> cache [Raigad]
// request Torna -> cache [Raigad, Torna]
// request Lohagad -> cache [Raigad, Torna, Lohagad]
// request Raigad -> cache [Torna, Lohagad, Raigad]
// request Panhala -> cache [Lohagad, Raigad, Panhala]
// request Torna -> cache [Raigad, Panhala, Torna]
// request Raigad -> cache [Panhala, Torna, Raigad]
// hits=2 misses=5

// Practice: group in first-seen order with LinkedHashMap
import java.util.ArrayList;      // imports the ArrayList class
import java.util.LinkedHashMap;  // imports the LinkedHashMap class
import java.util.List;           // imports the List class
import java.util.Map;            // imports the Map class

public class BookingsByDistrict {             // class that holds the main method
    public static void main(String[] args) {  // program entry point
        String[][] bookings = {
            {"Pune", "Torna"}, {"Raigad", "Raigad"}, {"Pune", "Lohagad"}, {"Kolhapur", "Panhala"},
                    {"Raigad", "Pratapgad"}, {"Pune", "Sinhagad"}, {"Kolhapur", "Vishalgad"}};

        Map<String, List<String>> byDistrict = new LinkedHashMap<>();  // creates an empty LinkedHashMap named byDistrict
        for (String[] b : bookings) {  // loops over every element of bookings
            byDistrict.computeIfAbsent(b[0], k -> new ArrayList<>()).add(b[1]);  // computes the value for the key
        }

        String busiest = null;                               // stores the value in busiest
        for (Map.Entry<String, List<String>> e : byDistrict.entrySet()) {  // loops over every element of byDistrict.entrySet()
            System.out.println(e.getKey() + " (" + e.getValue().size() + ")");  // prints the number of elements
            for (int i = 0; i < e.getValue().size(); i++) {  // loops through all the indexes
                System.out.println("   " + (i + 1) + ". " + e.getValue().get(i));  // prints the element or value read
            }
            if (busiest == null || e.getValue().size() > byDistrict.get(busiest).size()) {  // checks for null
                busiest = e.getKey();                        // strictly greater: the first one wins a tie
            }
        }
        System.out.println("Busiest district: " + busiest);  // prints a label followed by the value
    }
}
// OUTPUT:
// Pune (3)
//    1. Torna
//    2. Lohagad
//    3. Sinhagad
// Raigad (2)
//    1. Raigad
//    2. Pratapgad
// Kolhapur (2)
//    1. Panhala
//    2. Vishalgad
// Busiest district: Pune

