import java.util.*;  // imports every class of java.util

public class LhmMergeItineraries {                       // class that holds the main method
    public static void main(String[] args) {             // program entry point
        Map<String, Integer> a = new LinkedHashMap<>();  // creates an empty LinkedHashMap named a
        a.put("Sinhagad", 2);                            // maps key "Sinhagad" to value 2
        a.put("Torna", 4);                               // maps key "Torna" to value 4
        a.put("Raigad", 5);                              // maps key "Raigad" to value 5

        Map<String, Integer> b = new LinkedHashMap<>();  // creates an empty LinkedHashMap named b
        b.put("Lohagad", 1);                             // maps key "Lohagad" to value 1
        b.put("Torna", 6);                               // maps key "Torna" to value 6
        b.put("Panhala", 3);                             // maps key "Panhala" to value 3

        Map<String, Integer> merged = new LinkedHashMap<>(a);   // A's order first
        for (Map.Entry<String, Integer> e : b.entrySet()) {     // loops over every element of b.entrySet()
            merged.merge(e.getKey(), e.getValue(), Math::max);  // bigger hours win; new keys go to the end
        }
        System.out.println(merged);                             // prints merged
    }
}
