// Practice: leaderboard with shared ranks
import java.util.*;                  // imports every class of java.util
import java.util.stream.Collectors;  // imports the Collectors class

public class LhmLeaderboard {                           // class that holds the main method
    public static void main(String[] args) {            // program entry point
        Map<String, Integer> scores = new HashMap<>();  // creates an empty HashMap named scores
        scores.put("Asha", 90);                         // maps key "Asha" to value 90
        scores.put("Ravi", 75);                         // maps key "Ravi" to value 75
        scores.put("Meera", 90);                        // maps key "Meera" to value 90
        scores.put("Kiran", 60);                        // maps key "Kiran" to value 60
        scores.put("Sana", 75);                         // maps key "Sana" to value 75

        Map<String, Integer> board = scores.entrySet().stream()
                .sorted(Map.Entry.<String, Integer>comparingByValue().reversed().thenComparing(Map.Entry.comparingByKey()))
                .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue, (x, y) -> x, LinkedHashMap::new));

        int position = 0, rank = 0, lastScore = -1;  // declares int position with value 0, rank = 0, lastSc...
        for (Map.Entry<String, Integer> e : board.entrySet()) {  // loops over every element of board.entrySet()
            position++;                              // increments position
            if (e.getValue() != lastScore) {         // a new score gets the rank of its position
                rank = position;                     // assigns a new value to rank
                lastScore = e.getValue();            // assigns a new value to lastScore
            }
            System.out.println(rank + ". " + e.getKey() + " " + e.getValue());  // prints the result
        }
    }
}
// OUTPUT:
// 1. Asha 90
// 1. Meera 90
// 3. Ravi 75
// 3. Sana 75
// 5. Kiran 60

// TreeMap constructors: natural order, reverse order, copy
import java.util.Comparator;  // imports the Comparator class
import java.util.Map;         // imports the Map class
import java.util.TreeMap;     // imports the TreeMap class

public class TreeMapCreateDemo {              // class that holds the main method
    public static void main(String[] args) {  // program entry point
        Map<String, Integer> source = Map.of("Torna", 5, "Raigad", 6, "Purandar", 3, "Sinhagad", 2);  // source is an immutable map of the listed values

        Map<String, Integer> natural = new TreeMap<>(source);  // A to Z by key
        Map<String, Integer> reverse = new TreeMap<>(Comparator.reverseOrder());  // Z to A
        reverse.putAll(source);                                // copies every entry of source into the map
        Map<String, Integer> byLength = new TreeMap<>(Comparator.comparing(String::length).thenComparing(Comparator.naturalOrder()));  // creates a TreeMap ordered by the given comparator
        byLength.putAll(source);                               // copies every entry of source into the map

        System.out.println("Natural  : " + natural);   // prints a label followed by the value
        System.out.println("Reverse  : " + reverse);   // prints a label followed by the value
        System.out.println("By length: " + byLength);  // prints a label followed by the value
    }
}
// OUTPUT:
// Natural  : {Purandar=3, Raigad=6, Sinhagad=2, Torna=5}
// Reverse  : {Torna=5, Sinhagad=2, Raigad=6, Purandar=3}
// By length: {Torna=5, Raigad=6, Purandar=3, Sinhagad=2}

