// MASTER PROGRAM: all important TreeMap methods in one program
import java.util.Comparator;  // imports the Comparator class
import java.util.Map;         // imports the Map class
import java.util.TreeMap;     // imports the TreeMap class

public class TreeMapMasterDemo {              // class that holds the main method
    public static void main(String[] args) {  // program entry point
        // 1. Create an empty TreeMap (keys always sorted)
        TreeMap<Integer, String> map = new TreeMap<>();  // creates an empty TreeMap named map

        // 2. put, putAll, putIfAbsent
        map.put(30, "Torna");                                // maps key 30 to value "Torna"
        map.put(10, "Raigad");                               // maps key 10 to value "Raigad"
        map.putAll(Map.of(20, "Sinhagad", 40, "Purandar"));  // copies every entry of Map.of(20, "Sinhagad", 40, "Puran... into the map
        map.putIfAbsent(50, "Lohagad");                      // stores "Lohagad" for key 50 only if the key has no value yet
        System.out.println("2. After puts      : " + map);   // prints a label followed by the value

        // 3. get, getOrDefault, containsKey, containsValue, size
        System.out.println("3. get(10)         : " + map.get(10));  // prints the element or value read
        System.out.println("   getOrDefault    : " + map.getOrDefault(99, "none"));  // prints the element or value read
        System.out.println("   containsKey     : " + map.containsKey(20));  // prints whether the element is present
        System.out.println("   containsValue   : " + map.containsValue("Torna"));  // prints whether the element is present
        System.out.println("   size            : " + map.size());  // prints the number of elements

        // 4. firstKey, lastKey, firstEntry, lastEntry
        System.out.println("4. firstKey/lastKey: " + map.firstKey() + " / " + map.lastKey());  // prints the element or value read
        System.out.println("   first / last    : " + map.firstEntry() + " / " + map.lastEntry());  // prints a label followed by the value

        // 5. Nearest keys: lowerKey, floorKey, ceilingKey, higherKey
        System.out.println("5. lowerKey(30)    : " + map.lowerKey(30));  // prints the nearest element
        System.out.println("   floorKey(30)    : " + map.floorKey(30));  // prints the nearest element
        System.out.println("   ceilingKey(35)  : " + map.ceilingKey(35));  // prints the nearest element
        System.out.println("   higherKey(50)   : " + map.higherKey(50));  // prints the nearest element

        // 6. Range views: headMap, tailMap, subMap
        System.out.println("6. headMap(30)     : " + map.headMap(30));  // prints the selected range
        System.out.println("   tailMap(30)     : " + map.tailMap(30));  // prints the selected range
        System.out.println("   subMap(20, 40)  : " + map.subMap(20, 40));  // prints the selected range

        // 7. Reverse order: descendingMap, descendingKeySet, reversed
        System.out.println("7. descendingMap   : " + map.descendingMap());  // prints a label followed by the value
        System.out.println("   descendingKeySet: " + map.descendingKeySet());  // prints a label followed by the value

        // 8. Views: keySet, values, forEach
        System.out.println("8. keys / values   : " + map.keySet() + " / " + map.values());  // prints the keys, values or entries
        map.forEach((k, v) -> System.out.print(k + "=" + v + " "));  // runs the given action for every element
        System.out.println();  // prints an empty line

        // 9. Change values: replace, merge
        map.replace(10, "Raigad Fort");      // calls replace() on map
        map.merge(10, "!", String::concat);  // combines the old and new value for the key
        System.out.println("9. map.get(10)     : " + map.get(10));  // prints the element or value read

        // 10. Remove: remove, pollFirstEntry, pollLastEntry
        map.remove(30);                                     // removes the entry for key 30
        System.out.println("10. pollFirstEntry : " + map.pollFirstEntry());  // prints a label followed by the value
        System.out.println("    pollLastEntry  : " + map.pollLastEntry());  // prints a label followed by the value
        System.out.println("    Left           : " + map);  // prints a label followed by the value

        // 11. A custom order, and clear
        TreeMap<String, Integer> zToA = new TreeMap<>(Comparator.reverseOrder());  // creates a TreeMap ordered by the given comparator
        zToA.put("Pune", 1);                                 // maps key "Pune" to value 1
        zToA.put("Agra", 2);                                 // maps key "Agra" to value 2
        System.out.println("11. Z to A         : " + zToA);  // prints a label followed by the value
        map.clear();                                         // removes every element from the map
        System.out.println("    After clear    : " + map);   // prints a label followed by the value
    }
}
// OUTPUT:
// 2. After puts      : {10=Raigad, 20=Sinhagad, 30=Torna, 40=Purandar, 50=Lohagad}
// 3. get(10)         : Raigad
//    getOrDefault    : none
//    containsKey     : true
//    containsValue   : true
//    size            : 5
// 4. firstKey/lastKey: 10 / 50
//    first / last    : 10=Raigad / 50=Lohagad
// 5. lowerKey(30)    : 20
//    floorKey(30)    : 30
//    ceilingKey(35)  : 40
//    higherKey(50)   : null
// 6. headMap(30)     : {10=Raigad, 20=Sinhagad}
//    tailMap(30)     : {30=Torna, 40=Purandar, 50=Lohagad}
//    subMap(20, 40)  : {20=Sinhagad, 30=Torna}
// 7. descendingMap   : {50=Lohagad, 40=Purandar, 30=Torna, 20=Sinhagad, 10=Raigad}
//    descendingKeySet: [50, 40, 30, 20, 10]
// 8. keys / values   : [10, 20, 30, 40, 50] / [Raigad, Sinhagad, Torna, Purandar, Lohagad]
// 10=Raigad 20=Sinhagad 30=Torna 40=Purandar 50=Lohagad
