// A TreeMap sorts by key; for value order use a stream
import java.util.*;                  // imports every class of java.util
import java.util.stream.Collectors;  // imports the Collectors class

public class TmSortByValue {                           // class that holds the main method
    public static void main(String[] args) {           // program entry point
        Map<String, Integer> hours = new TreeMap<>();  // creates an empty TreeMap named hours
        hours.put("Torna", 5);                         // maps key "Torna" to value 5
        hours.put("Raigad", 6);                        // maps key "Raigad" to value 6
        hours.put("Lohagad", 2);                       // maps key "Lohagad" to value 2

        Map<String, Integer> byHours = hours.entrySet().stream()
                .sorted(Map.Entry.comparingByValue())
                .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue, (a, b) -> a, LinkedHashMap::new));
        System.out.println("By key  : " + hours);    // prints a label followed by the value
        System.out.println("By value: " + byHours);  // prints a label followed by the value
    }
}
// OUTPUT:
// By key  : {Lohagad=2, Raigad=6, Torna=5}
// By value: {Lohagad=2, Torna=5, Raigad=6}

