// A comparator that ignores part of the key silently merges entries
import java.util.Comparator;  // imports the Comparator class
import java.util.TreeMap;     // imports the TreeMap class

public class TreeMapComparatorTrapDemo {      // class that holds the main method
    public static void main(String[] args) {  // program entry point
        TreeMap<String, Integer> lossy = new TreeMap<>(Comparator.comparing(String::length));  // length only
        lossy.put("Torna", 5);                // maps key "Torna" to value 5
        lossy.put("Lohag", 99);               // same length -> "same key": value replaced
        lossy.put("Raigad", 6);               // maps key "Raigad" to value 6
        System.out.println("Length only      : " + lossy + " (3 puts, " + lossy.size() + " entries)");  // prints the number of elements

        TreeMap<String, Integer> safe = new TreeMap<>(Comparator.comparing(String::length).thenComparing(Comparator.naturalOrder()));  // creates a TreeMap ordered by the given comparator
        safe.put("Torna", 5);   // maps key "Torna" to value 5
        safe.put("Lohag", 99);  // maps key "Lohag" to value 99
        safe.put("Raigad", 6);  // maps key "Raigad" to value 6
        System.out.println("With tie-breaker : " + safe + " (" + safe.size() + " entries)");  // prints the number of elements
    }
}
// OUTPUT:
// Length only      : {Torna=99, Raigad=6} (3 puts, 2 entries)
// With tie-breaker : {Lohag=99, Torna=5, Raigad=6} (3 entries)

// Entry fee slabs: the slab that contains a group size
import java.util.Map;      // imports the Map class
import java.util.TreeMap;  // imports the TreeMap class

public class TreeMapSlabsDemo {               // class that holds the main method
    public static void main(String[] args) {  // program entry point
        TreeMap<Integer, Integer> feePerPerson = new TreeMap<>();  // key = smallest group size of the slab
        feePerPerson.put(1, 100);             // 1 to 9 people pay 100 each
        feePerPerson.put(10, 80);             // 10 to 24 people pay 80 each
        feePerPerson.put(25, 60);             // 25 or more pay 60 each

        for (int group : new int[] {1, 9, 10, 24, 25, 100}) {  // loops over every element of new int[] {1, 9, 10, 24, 25,...
            Map.Entry<Integer, Integer> slab = feePerPerson.floorEntry(group);  // stores the value in slab
            System.out.println("Group of " + group + " -> slab starting at " + slab.getKey() + ", fee " + slab.getValue() + " each, total " + group * slab.getValue());  // prints a label followed by the value
        }
    }
}
// OUTPUT:
// Group of 1 -> slab starting at 1, fee 100 each, total 100
// Group of 9 -> slab starting at 1, fee 100 each, total 900
// Group of 10 -> slab starting at 10, fee 80 each, total 800
// Group of 24 -> slab starting at 10, fee 80 each, total 1920
// Group of 25 -> slab starting at 25, fee 60 each, total 1500
// Group of 100 -> slab starting at 25, fee 60 each, total 6000

// Timeline of events: query a window of hours with subMap()
import java.util.TreeMap;  // imports the TreeMap class

public class TreeMapTimelineDemo {                       // class that holds the main method
    public static void main(String[] args) {             // program entry point
        TreeMap<Integer, String> day = new TreeMap<>();  // creates an empty TreeMap named day
        day.put(6, "Reach Raigad base");                 // maps key 6 to value "Reach Raigad base"
        day.put(8, "Start the climb");                   // maps key 8 to value "Start the climb"
        day.put(11, "Summit and photos");                // maps key 11 to value "Summit and photos"
        day.put(13, "Lunch");                            // maps key 13 to value "Lunch"
        day.put(16, "Back at the base");                 // maps key 16 to value "Back at the base"

        System.out.println("Morning (before 12)    : " + day.headMap(12));  // prints the selected range
        System.out.println("Between 8 and 13       : " + day.subMap(8, true, 13, true));  // prints the selected range
        System.out.println("From 13 onwards        : " + day.tailMap(13));  // prints the selected range
        System.out.println("Next event after 9:00  : " + day.higherEntry(9));  // prints the nearest element
        System.out.println("Last event before 12   : " + day.lowerEntry(12));  // prints the nearest element
    }
}
// OUTPUT:
// Morning (before 12)    : {6=Reach Raigad base, 8=Start the climb, 11=Summit and photos}
// Between 8 and 13       : {8=Start the climb, 11=Summit and photos, 13=Lunch}
// From 13 onwards        : {13=Lunch, 16=Back at the base}
// Next event after 9:00  : 11=Summit and photos
// Last event before 12   : 11=Summit and photos

// Real-time example: phone directory with prefix search
import java.util.*;  // imports every class of java.util

public class TmPhoneDirectory {                           // class that holds the main method
    public static void main(String[] args) {              // program entry point
        TreeMap<String, String> phone = new TreeMap<>();  // creates an empty TreeMap named phone
        phone.put("Meera", "98220-11111");                // maps key "Meera" to value "98220-11111"
