// Real-time example: nearest key
import java.util.*;  // imports every class of java.util

public class TmNearestFort {                                  // class that holds the main method
    public static void main(String[] args) {                  // program entry point
        TreeMap<Integer, String> byHeight = new TreeMap<>();  // creates an empty TreeMap named byHeight
        byHeight.put(845, "Panhala");                         // maps key 845 to value "Panhala"
        byHeight.put(1033, "Lohagad");                        // maps key 1033 to value "Lohagad"
        byHeight.put(1312, "Sinhagad");                       // maps key 1312 to value "Sinhagad"
        byHeight.put(1403, "Torna");                          // maps key 1403 to value "Torna"

        for (int target : new int[]{1200, 700, 1500}) {  // loops over every element of new int[]{1200, 700, 1500}
            Map.Entry<Integer, String> below = byHeight.floorEntry(target);  // stores the value in below
            Map.Entry<Integer, String> above = byHeight.ceilingEntry(target);  // stores the value in above

            Map.Entry<Integer, String> nearest;  // declares nearest of type Map.Entry<Integer, String>
            if (below == null) {                 // checks for null
                nearest = above;                 // nothing lower
            } else if (above == null) {          // checks the next condition
                nearest = below;                 // nothing higher
            } else {                             // runs when the condition is false
                nearest = (target - below.getKey() <= above.getKey() - target) ? below : above;  // closer wins; tie -> lower
            }
            System.out.println("Nearest to " + target + " m: " + nearest.getValue() + " (" + nearest.getKey() + " m)");  // prints a label followed by the value
        }
    }
}
// OUTPUT:
// Nearest to 1200 m: Sinhagad (1312 m)
// Nearest to 700 m: Panhala (845 m)
// Nearest to 1500 m: Torna (1403 m)

// Sample project: Fort Height Explorer (TreeMap)
import java.util.*;  // imports every class of java.util

public class TmHeightExplorer {               // class that holds the main method
    public static void main(String[] args) {  // program entry point
        // Step 1: load the forts (height in metres -> name)
        TreeMap<Integer, String> forts = new TreeMap<>();  // creates an empty TreeMap named forts
        forts.put(1403, "Torna");                          // maps key 1403 to value "Torna"
        forts.put(1356, "Raigad");                         // maps key 1356 to value "Raigad"
        forts.put(1312, "Sinhagad");                       // maps key 1312 to value "Sinhagad"
        forts.put(1033, "Lohagad");                        // maps key 1033 to value "Lohagad"
        forts.put(1080, "Pratapgad");                      // maps key 1080 to value "Pratapgad"
        forts.put(845, "Panhala");                         // maps key 845 to value "Panhala"
        forts.put(820, "Shivneri");                        // maps key 820 to value "Shivneri"

        // Step 2: tallest to shortest
        System.out.println("Tallest first:");  // prints the text "Tallest first:"
        for (Map.Entry<Integer, String> e : forts.descendingMap().entrySet()) {  // loops over every element of forts.descendingMap().entrySe...
            System.out.println("  " + e.getValue() + " " + e.getKey() + " m");  // prints a label followed by the value
        }

        // Step 3: extremes
        System.out.println("Shortest: " + forts.firstEntry().getValue());  // prints a label followed by the value
