// Real-time practice: a bus timetable with TreeMap
import java.util.Map;      // imports the Map class
import java.util.TreeMap;  // imports the TreeMap class

public class BusTimetable {         // class that holds the main method
    static String t(int minutes) {  // method t()
        return String.format("%02d:%02d", minutes / 60, minutes % 60);  // returns the result to the caller
    }

    static int at(int hour, int minute) {  // method at()
        return hour * 60 + minute;         // returns the result to the caller
    }

    public static void main(String[] args) {                    // program entry point
        TreeMap<Integer, String> departures = new TreeMap<>();  // creates an empty TreeMap named departures
        departures.put(at(12, 15), "Pune to Kolhapur");         // maps key at(12, 15) to value "Pune to Kolhapur"
        departures.put(at(6, 30), "Pune to Nashik");            // maps key at(6, 30) to value "Pune to Nashik"
        departures.put(at(9, 0), "Pune to Mumbai");             // maps key at(9, 0) to value "Pune to Mumbai"
        departures.put(at(11, 45), "Pune to Nagpur");           // maps key at(11, 45) to value "Pune to Nagpur"
        departures.put(at(15, 30), "Pune to Mumbai");           // maps key at(15, 30) to value "Pune to Mumbai"

        int now = at(10, 30);  // declares int now with value at(10, 30)
        Map.Entry<Integer, String> next = departures.ceilingEntry(now);  // first bus at or after now
        Map.Entry<Integer, String> previous = departures.lowerEntry(now);  // the one you just missed
        System.out.println("Next bus after " + t(now) + "     : " + t(next.getKey()) + " " + next.getValue());  // prints a label followed by the value
        System.out.println("Bus you just missed      : " + t(previous.getKey()) + " " + previous.getValue());  // prints a label followed by the value

        System.out.println("Board for the next 2 hours:");  // prints the text "Board for the next 2 hours:"
        for (Map.Entry<Integer, String> e : departures.subMap(now, true, now + 120, true).entrySet()) {  // loops over every element of departures.subMap(now, true,...
            System.out.println("  " + t(e.getKey()) + "  " + e.getValue());  // prints a label followed by the value
        }

        Map.Entry<Integer, String> gone = departures.pollFirstEntry();  // earliest bus has left
        System.out.println("Left the stand: " + t(gone.getKey()) + " " + gone.getValue() + "; remaining " + departures.size());  // prints the number of elements
        System.out.println("Is there a bus after 16:00? " + departures.higherEntry(at(16, 0)));  // prints the nearest element
    }
}
// OUTPUT:
// Next bus after 10:30     : 11:45 Pune to Nagpur
// Bus you just missed      : 09:00 Pune to Mumbai
// Board for the next 2 hours:
//   11:45  Pune to Nagpur
//   12:15  Pune to Kolhapur
// Left the stand: 06:30 Pune to Nashik; remaining 4
// Is there a bus after 16:00? null

// Practice: progressive fee slabs with TreeMap
import java.util.Map;      // imports the Map class
import java.util.TreeMap;  // imports the TreeMap class

public class SlabFeeCalculator {                              // class that holds the main method
    static int total(TreeMap<Integer, Integer> slabs, int people) {  // method total()
        int sum = 0;                                          // declares int sum with value 0
        for (Map.Entry<Integer, Integer> slab : slabs.entrySet()) {  // loops over every element of slabs.entrySet()
            int start = slab.getKey();                        // declares int start with value slab.getKey()
            Integer next = slabs.higherKey(start);            // where the next slab begins
            int last = (next == null) ? people : Math.min(people, next - 1);  // declares int last with value (next == null) ? pe...
            if (people >= start) {                            // checks the condition
                sum += (last - start + 1) * slab.getValue();  // people inside this slab
            }
        }
        return sum;                                           // returns the result to the caller
    }

    public static void main(String[] args) {                // program entry point
        TreeMap<Integer, Integer> slabs = new TreeMap<>();  // creates an empty TreeMap named slabs
        slabs.put(1, 100);                                  // people 1 to 10
        slabs.put(11, 80);                                  // people 11 to 25
        slabs.put(26, 60);                                  // people 26 and more

        for (int people : new int[] {5, 10, 18, 25, 40}) {  // loops over every element of new int[] {5, 10, 18, 25, 40}
            Map.Entry<Integer, Integer> last = slabs.floorEntry(people);  // stores the value in last
            System.out.println(people + " people -> " + total(slabs, people) + " rupees (ends in the slab starting at " + last.getKey() + ")");  // prints the result
        }
    }
}
// OUTPUT:
// 5 people -> 500 rupees (ends in the slab starting at 1)
// 10 people -> 1000 rupees (ends in the slab starting at 1)
// 18 people -> 1640 rupees (ends in the slab starting at 11)
// 25 people -> 2200 rupees (ends in the slab starting at 11)
// 40 people -> 3100 rupees (ends in the slab starting at 26)

