// Practice: nearest key with a "taller wins" tie-break
import java.util.*;  // imports every class of java.util

public class TmNearestTie {                   // class that holds the main method
    static String nearest(TreeMap<Integer, String> map, int target) {  // method nearest()
        Map.Entry<Integer, String> low = map.floorEntry(target);  // stores the value in low
        Map.Entry<Integer, String> high = map.ceilingEntry(target);  // stores the value in high
        if (low == null) {                    // checks for null
            return high.getValue();           // returns the result to the caller
        }
        if (high == null) {                   // checks for null
            return low.getValue();            // returns the result to the caller
        }
        int downGap = target - low.getKey();  // declares int downGap with value target - low.getKey...
        int upGap = high.getKey() - target;   // declares int upGap with value high.getKey() - tar...
        return downGap < upGap ? low.getValue() : high.getValue();  // equal gap -> taller (high)
    }

    public static void main(String[] args) {                  // program entry point
        TreeMap<Integer, String> byHeight = new TreeMap<>();  // creates an empty TreeMap named byHeight
        byHeight.put(1000, "Lohagad");                        // maps key 1000 to value "Lohagad"
        byHeight.put(1200, "Sinhagad");                       // maps key 1200 to value "Sinhagad"
        byHeight.put(1400, "Torna");                          // maps key 1400 to value "Torna"

        for (int t : new int[]{900, 1100, 1200, 1290, 1300, 1500}) {  // loops over every element of new int[]{900, 1100, 1200, 12...
            System.out.println(t + " -> " + nearest(byHeight, t));  // prints the result
        }
    }
}
// OUTPUT:
// 900 -> Lohagad
// 1100 -> Sinhagad
// 1200 -> Sinhagad
// 1290 -> Sinhagad
// 1300 -> Torna
// 1500 -> Torna

// Practice: overlapping bookings with a TreeMap sweep line
import java.util.*;  // imports every class of java.util

public class TmBusyGuides {                   // class that holds the main method
    public static void main(String[] args) {  // program entry point
        int[][] bookings = {{9, 12}, {10, 11}, {11, 14}, {13, 15}, {10, 13}};  // stores the value in bookings

        TreeMap<Integer, Integer> change = new TreeMap<>();  // creates an empty TreeMap named change
        for (int[] b : bookings) {                           // loops over every element of bookings
            change.merge(b[0], 1, Integer::sum);             // a guide becomes busy
            change.merge(b[1], -1, Integer::sum);            // a guide becomes free
        }

        int busy = 0, maxBusy = 0, firstHour = -1;  // declares int busy with value 0, maxBusy = 0, fir...
        for (Map.Entry<Integer, Integer> e : change.entrySet()) {  // time order
            busy += e.getValue();                   // updates busy
            System.out.println("hour " + e.getKey() + ": busy = " + busy);  // prints a label followed by the value
            if (busy > maxBusy) {                   // checks the condition
                maxBusy = busy;                     // assigns a new value to maxBusy
                firstHour = e.getKey();             // assigns a new value to firstHour
            }
        }
        System.out.println("Most guides busy at once: " + maxBusy + " (from hour " + firstHour + ")");  // prints a label followed by the value
    }
}
// OUTPUT:
// hour 9: busy = 1
// hour 10: busy = 3
// hour 11: busy = 3
// hour 12: busy = 2
// hour 13: busy = 2
// hour 14: busy = 1
// hour 15: busy = 0
// Most guides busy at once: 3 (from hour 10)

