// MASTER PROGRAM: all important Hashtable methods in one program
import java.util.Enumeration;  // imports the Enumeration class
import java.util.Hashtable;    // imports the Hashtable class
import java.util.Map;          // imports the Map class

public class HashtableMasterDemo {            // class that holds the main method
    public static void main(String[] args) {  // program entry point
        // 1. Create an empty Hashtable
        Hashtable<String, Integer> heights = new Hashtable<>();  // creates an empty Hashtable named heights

        // 2. put, putAll, putIfAbsent
        heights.put("Raigad", 820);                // maps key "Raigad" to value 820
        heights.put("Torna", 1400);                // maps key "Torna" to value 1400
        heights.putAll(Map.of("Sinhagad", 1300));  // copies every entry of Map.of("Sinhagad", 1300) into the map
        heights.putIfAbsent("Purandar", 1200);     // stores 1200 for key "Purandar" only if the key has no value yet
        System.out.println("2. size            : " + heights.size());  // prints the number of elements

        // 3. Hashtable does not allow null keys or values
        try {                                              // code that may throw an exception
            heights.put("Lohagad", null);                  // maps key "Lohagad" to value null
        } catch (NullPointerException e) {                 // handles NullPointerException
            System.out.println("3. null is not allowed");  // prints the text "3. null is not allowed"
        }

        // 4. get, getOrDefault, containsKey, containsValue, contains
        System.out.println("4. get             : " + heights.get("Raigad"));  // prints the element or value read
        System.out.println("   getOrDefault    : " + heights.getOrDefault("Panhala", 0));  // prints the element or value read
        System.out.println("   containsKey     : " + heights.containsKey("Torna"));  // prints whether the element is present
        System.out.println("   containsValue   : " + heights.containsValue(820));  // prints whether the element is present
        System.out.println("   contains (old)  : " + heights.contains(820));  // prints whether the element is present

        // 5. replace and merge
        heights.replace("Raigad", 900);             // calls replace() on heights
        heights.merge("Raigad", 10, Integer::sum);  // combines the old and new value for the key
        System.out.println("5. Raigad          : " + heights.get("Raigad"));  // prints the element or value read

        // 6. Loop: entrySet, keySet, values, forEach
        System.out.println("6. keys count      : " + heights.keySet().size());  // prints the number of elements
        System.out.println("   values count    : " + heights.values().size());  // prints the number of elements
        for (Map.Entry<String, Integer> e : heights.entrySet()) {  // loops over every element of heights.entrySet()
            if (e.getValue() > 1300) {                         // checks the condition
                System.out.println("   tall: " + e.getKey());  // prints a label followed by the value
            }
        }
        heights.forEach((fort, h) -> { });                     // runs the given action for every element

        // 7. Old way to loop: keys() and elements() return an Enumeration
        Enumeration<String> keys = heights.keys();            // stores the result: gets an enumeration to walk through
        int count = 0;                                        // declares int count with value 0
        while (keys.hasMoreElements()) {                      // repeats while the condition is true
            keys.nextElement();                               // calls nextElement() on keys
            count++;                                          // increments count
        }
        System.out.println("7. keys counted    : " + count);  // prints a label followed by the value

        // 8. clone and equals
        Object copy = heights.clone();  // stores the result: creates a shallow copy
        System.out.println("8. equals clone    : " + heights.equals(copy));  // prints the comparison result

        // 9. remove, isEmpty, clear
        heights.remove("Purandar");  // removes the entry for key "Purandar"
        System.out.println("9. size after remove: " + heights.size());  // prints the number of elements
        heights.clear();             // removes every element from the map
        System.out.println("   isEmpty         : " + heights.isEmpty());  // prints whether it is empty
    }
}
// OUTPUT:
// 2. size            : 4
// 3. null is not allowed
// 4. get             : 820
//    getOrDefault    : 0
//    containsKey     : true
//    containsValue   : true
//    contains (old)  : true
// 5. Raigad          : 910
// 6. keys count      : 4
//    values count    : 4
//    tall: Torna
// 7. keys counted    : 4
// 8. equals clone    : true
// 9. size after remove: 3
//    isEmpty         : true

