// Sort a Hashtable by value, biggest first
import java.util.*;                  // imports every class of java.util
import java.util.stream.Collectors;  // imports the Collectors class

public class HtSortByValue {                  // class that holds the main method
    public static void main(String[] args) {  // program entry point
        Hashtable<String, Integer> visitors = new Hashtable<>();  // creates an empty Hashtable named visitors
        visitors.put("Raigad", 40);           // maps key "Raigad" to value 40
        visitors.put("Sinhagad", 95);         // maps key "Sinhagad" to value 95
        visitors.put("Torna", 25);            // maps key "Torna" to value 25

        Map<String, Integer> ranked = visitors.entrySet().stream()
                .sorted(Map.Entry.comparingByValue(Comparator.reverseOrder()))
                .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue, (a, b) -> a, LinkedHashMap::new));
        System.out.println(ranked);  // prints ranked
    }
}
// OUTPUT:
// {Sinhagad=95, Raigad=40, Torna=25}

