// Find all keys that start with N using an Enumeration
import java.util.*;  // imports every class of java.util

public class HtFindEnumeration {                               // class that holds the main method
    public static void main(String[] args) {                   // program entry point
        Hashtable<String, Integer> codes = new Hashtable<>();  // creates an empty Hashtable named codes
        codes.put("Nagpur", 712);                              // maps key "Nagpur" to value 712
        codes.put("Nashik", 253);                              // maps key "Nashik" to value 253
        codes.put("Pune", 20);                                 // maps key "Pune" to value 20

        List<String> found = new ArrayList<>();   // creates an empty ArrayList named found
        Enumeration<String> keys = codes.keys();  // stores the result: gets an enumeration to walk through
        while (keys.hasMoreElements()) {          // repeats while the condition is true
            String key = keys.nextElement();      // stores the value in key
            if (key.startsWith("N")) {            // the search rule
                found.add(key);                   // adds key to the end of the list
            }
        }
        Collections.sort(found);                  // Hashtable order is not fixed, so sort before printing
        System.out.println(found);                // prints found
    }
}
// OUTPUT:
// [Nagpur, Nashik]

