// Real-time example: session store
import java.util.*;  // imports every class of java.util

public class HtSessionStore {  // class that holds the main method
    static final Hashtable<String, String> sessions = new Hashtable<>();  // token -> user

    static String login(String user, int number) {  // method login()
        String token = "TKN-" + number;             // stores the text "TKN-" + number in token
        sessions.put(token, user);                  // maps key token to value user
        return token;                               // returns the result to the caller
    }

    static String whoIs(String token) {                // method whoIs()
        String user = sessions.get(token);             // stores the result: reads the element at index token
        return user == null ? "not logged in" : user;  // returns the result to the caller
    }

    public static void main(String[] args) {  // program entry point
        String a = login("Asha", 101);        // stores the value in a
        String b = login("Ravi", 102);        // stores the value in b

        System.out.println(a + " -> " + whoIs(a));             // prints the result
        System.out.println(b + " -> " + whoIs(b));             // prints the result
        sessions.remove(a);                                    // logout
        System.out.println(a + " -> " + whoIs(a));             // prints the result
        System.out.println("Unknown -> " + whoIs("TKN-999"));  // prints a label followed by the value
    }
}
// OUTPUT:
// TKN-101 -> Asha
// TKN-102 -> Ravi
// TKN-101 -> not logged in
// Unknown -> not logged in

