// Real-time example: several threads, one Hashtable
import java.util.*;  // imports every class of java.util

public class HtVisitCounter {                                   // class that holds the main method
    public static void main(String[] args) throws InterruptedException {  // program entry point
        Hashtable<String, Integer> visits = new Hashtable<>();  // creates an empty Hashtable named visits

        Runnable counter = () -> {                        // defines counter as a lambda
            for (int i = 0; i < 1000; i++) {              // counting loop
                visits.merge("Raigad", 1, Integer::sum);  // one synchronized call: safe
                visits.merge("Torna", 1, Integer::sum);   // combines the old and new value for the key
            }
        };

        Thread[] threads = new Thread[4];           // creates an array named threads
        for (int i = 0; i < threads.length; i++) {  // loops through all the indexes
            threads[i] = new Thread(counter);       // stores new Thread(counte... at index i of threads
