// Sample project: Thread-safe Trek Seat Booking (Hashtable + synchronized check-then-act)
import java.util.*;                                // imports every class of java.util
import java.util.concurrent.atomic.AtomicInteger;  // imports the AtomicInteger class

public class HtSeatBooking {  // class that holds the main method
    // Step 1: seats left per fort
    static final Hashtable<String, Integer> seats = new Hashtable<>();  // creates an empty Hashtable named seats
    static final AtomicInteger booked = new AtomicInteger();    // creates an AtomicInteger object named booked
    static final AtomicInteger rejected = new AtomicInteger();  // creates an AtomicInteger object named rejected

    // Step 2: check and reduce must happen together, so we hold the table's own lock
    static void book(String fort) {          // method book()
        synchronized (seats) {               // only one thread at a time may run this block
            int left = seats.get(fort);      // stores the result: reads the element at index fort
            if (left > 0) {                  // checks the condition
                seats.put(fort, left - 1);   // maps key fort to value left - 1
                booked.incrementAndGet();    // calls incrementAndGet() on booked
            } else {                         // runs when the condition is false
                rejected.incrementAndGet();  // calls incrementAndGet() on rejected
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {  // program entry point
        seats.put("Raigad", 20);    // maps key "Raigad" to value 20
        seats.put("Torna", 15);     // maps key "Torna" to value 15
        seats.put("Sinhagad", 10);  // maps key "Sinhagad" to value 10

        // Step 3: four desks, each tries 15 bookings per fort
        Runnable desk = () -> {                   // defines desk as a lambda
            for (int i = 0; i < 15; i++) {        // counting loop
                book("Raigad");                   // calls the book() method
                book("Torna");                    // calls the book() method
                book("Sinhagad");                 // calls the book() method
            }
        };
        Thread[] desks = new Thread[4];           // creates an array named desks
        for (int i = 0; i < desks.length; i++) {  // loops through all the indexes
            desks[i] = new Thread(desk);          // stores new Thread(desk) at index i of desks
        }

        // Step 5: run and wait
        for (Thread t : desks) {  // loops over every element of desks
            t.start();            // starts the thread
        }
        for (Thread t : desks) {  // loops over every element of desks
            t.join();             // waits for the thread to finish
        }

        // Step 4/5: totals
        System.out.println("Seats left : " + new TreeMap<>(seats));  // prints a label followed by the value
        System.out.println("Booked     : " + booked.get());    // prints the element or value read
        System.out.println("Rejected   : " + rejected.get());  // prints the element or value read
        System.out.println("Requests   : " + (booked.get() + rejected.get()));  // prints the element or value read
        System.out.println("No overbooking: " + (booked.get() == 45));  // prints the element or value read
    }
}
// OUTPUT:
// Seats left : {Raigad=0, Sinhagad=0, Torna=0}
// Booked     : 45
// Rejected   : 135
// Requests   : 180
// No overbooking: true

// Real-time practice: a thread-safe counter table with Hashtable
import java.util.Enumeration;  // imports the Enumeration class
import java.util.Hashtable;    // imports the Hashtable class
import java.util.TreeMap;      // imports the TreeMap class

public class SharedVisitorCounters {                      // class that holds the main method
    public static void main(String[] args) throws InterruptedException {  // program entry point
        Hashtable<String, Integer> counters = new Hashtable<>();  // creates an empty Hashtable named counters
        String[] forts = {"Raigad", "Torna", "Lohagad"};  // stores the value in forts

        Thread[] gates = new Thread[3];           // creates an array named gates
        for (int g = 0; g < gates.length; g++) {  // loops through all the indexes
            gates[g] = new Thread(() -> {
                for (int i = 0; i < 3000; i++) {  // counting loop
                    counters.merge(forts[i % forts.length], 1, Integer::sum);  // atomic update
                }
            });
            gates[g].start();
        }
        for (Thread t : gates) {                  // loops over every element of gates
            t.join();                             // waits for the thread to finish
        }
        System.out.println("Counts: " + new TreeMap<>(counters));  // prints a label followed by the value

        int total = 0;                                      // declares int total with value 0
        Enumeration<Integer> values = counters.elements();  // the legacy way
        while (values.hasMoreElements()) {                  // repeats while the condition is true
            total += values.nextElement();                  // updates total
        }
        System.out.println("Total visitors: " + total);     // prints a label followed by the value

        try {                               // code that may throw an exception
            counters.put("Panhala", null);  // maps key "Panhala" to value null
        } catch (NullPointerException e) {  // handles NullPointerException
            System.out.println("A Hashtable does not accept null values");  // prints the text "A Hashtable does not accept..."
        }
    }
}
// OUTPUT:
// Counts: {Lohagad=3000, Raigad=3000, Torna=3000}
// Total visitors: 9000
// A Hashtable does not accept null values

// Practice: merging and inverting Hashtables
import java.util.ArrayList;    // imports the ArrayList class
import java.util.Collections;  // imports the Collections class
import java.util.Hashtable;    // imports the Hashtable class
import java.util.List;         // imports the List class
import java.util.Map;          // imports the Map class
import java.util.TreeMap;      // imports the TreeMap class

public class LegacyInventoryMerge {                            // class that holds the main method
    public static void main(String[] args) {                   // program entry point
        Hashtable<String, Integer> shopA = new Hashtable<>();  // creates an empty Hashtable named shopA
        shopA.put("Rope", 10);                                 // maps key "Rope" to value 10
        shopA.put("Torch", 4);                                 // maps key "Torch" to value 4
        shopA.put("Boots", 6);                                 // maps key "Boots" to value 6

        Hashtable<String, Integer> shopB = new Hashtable<>();  // creates an empty Hashtable named shopB
        shopB.put("Torch", 6);                                 // maps key "Torch" to value 6
        shopB.put("Boots", 4);                                 // maps key "Boots" to value 4
        shopB.put("Raincoat", 10);                             // maps key "Raincoat" to value 10

        Hashtable<String, Integer> merged = new Hashtable<>(shopA);  // creates a Hashtable named merged copied from shopA
        for (Map.Entry<String, Integer> e : shopB.entrySet()) {  // loops over every element of shopB.entrySet()
            merged.merge(e.getKey(), e.getValue(), Integer::sum);  // add the counts of common items
        }
        System.out.println("Merged : " + new TreeMap<>(merged));  // prints a label followed by the value

        Hashtable<Integer, List<String>> byCount = new Hashtable<>();  // creates an empty Hashtable named byCount
        for (Map.Entry<String, Integer> e : merged.entrySet()) {  // loops over every element of merged.entrySet()
            byCount.computeIfAbsent(e.getValue(), k -> new ArrayList<>()).add(e.getKey());  // computes the value for the key
        }
        for (List<String> items : byCount.values()) {  // loops over every element of byCount.values()
            Collections.sort(items);                   // sorts the list (natural order or the given comparator)
        }
        System.out.println("By count: " + new TreeMap<>(byCount));  // prints a label followed by the value
    }
}
// OUTPUT:
// Merged : {Boots=10, Raincoat=10, Rope=10, Torch=10}
// By count: {10=[Boots, Raincoat, Rope, Torch]}

// Practice: null-safe lookup on a Hashtable
import java.util.*;  // imports every class of java.util

public class HtSafeLookup {                   // class that holds the main method
    static int fee(Hashtable<String, Integer> table, String fort) {  // method fee()
        if (fort == null) {                   // checks for null
            return -1;                        // Hashtable.get(null) would throw
        }
        return table.getOrDefault(fort, -1);  // returns the result to the caller
    }

    public static void main(String[] args) {                  // program entry point
        Hashtable<String, Integer> fees = new Hashtable<>();  // creates an empty Hashtable named fees
        fees.put("Raigad", 50);                               // maps key "Raigad" to value 50
        fees.put("Torna", 30);                                // maps key "Torna" to value 30

        System.out.println(fee(fees, "Raigad"));        // prints the result
        System.out.println(fee(fees, "Panhala"));       // prints the result
        System.out.println(fee(fees, null));            // prints the result
        try {                                           // code that may throw an exception
            fees.put("Lohagad", null);                  // null values are rejected too
        } catch (NullPointerException e) {              // handles NullPointerException
            System.out.println("null value rejected");  // prints the text "null value rejected"
        }
    }
}
// OUTPUT:
// 50
// -1
// -1
// null value rejected

// Practice: Hashtable versus HashMap behaviour
import java.util.*;  // imports every class of java.util

public class HtVersusHashMap {                            // class that holds the main method
    static void attempt(String label, Runnable action) {  // method attempt()
        try {                                             // code that may throw an exception
            action.run();                                 // calls run() on action
            System.out.println(label + ": ok");           // prints the result
        } catch (RuntimeException e) {                    // handles RuntimeException
            System.out.println(label + ": " + e.getClass().getSimpleName());  // prints the result
        }
    }

    public static void main(String[] args) {                   // program entry point
        Map<String, Integer> table = new Hashtable<>();        // creates an empty Hashtable named table
        Map<String, Integer> hash = new HashMap<>();           // creates an empty HashMap named hash
        for (Map<String, Integer> m : List.of(table, hash)) {  // loops over every element of List.of(table, hash)
            m.put("Pune", 20);                                 // maps key "Pune" to value 20
            m.put("Mumbai", 22);                               // maps key "Mumbai" to value 22
        }

        attempt("Hashtable null key  ", () -> table.put(null, 1));  // calls the attempt() method
        attempt("HashMap   null key  ", () -> hash.put(null, 1));  // calls the attempt() method
        attempt("Hashtable null value", () -> table.put("Delhi", null));  // calls the attempt() method
        attempt("HashMap   null value", () -> hash.put("Delhi", null));  // calls the attempt() method
        attempt("Hashtable remove in loop", () -> {
            for (String k : table.keySet()) {  // loops over every element of table.keySet()
                table.remove(k);               // changing the map while looping
            }
        });
        attempt("HashMap   remove in loop", () -> {
            for (String k : hash.keySet()) {   // loops over every element of hash.keySet()
                hash.remove(k);                // removes the entry for key k
            }
        });
    }
}
// OUTPUT:
// Hashtable null key  : NullPointerException
// HashMap   null key  : ok
// Hashtable null value: NullPointerException
// HashMap   null value: ok
// Hashtable remove in loop: ConcurrentModificationException
// HashMap   remove in loop: ConcurrentModificationException

// Practice: check-then-act on a Hashtable
import java.util.*;                                // imports every class of java.util
import java.util.concurrent.atomic.AtomicInteger;  // imports the AtomicInteger class

public class HtAtomicSale {                                 // class that holds the main method
    static final Hashtable<String, Integer> stock = new Hashtable<>();  // creates an empty Hashtable named stock
    static final AtomicInteger sold = new AtomicInteger();  // creates an AtomicInteger object named sold

    static void sell() {  // method sell()
        // get and put are each synchronized, but another thread could run between them.
        // Locking the table for both calls makes the pair atomic.
        synchronized (stock) {                   // only one thread at a time may run this block
            int left = stock.get("tickets");     // stores the result: reads the value stored for key "tickets"
            if (left > 0) {                      // checks the condition
                stock.put("tickets", left - 1);  // maps key "tickets" to value left - 1
                sold.incrementAndGet();          // calls incrementAndGet() on sold
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {  // program entry point
        stock.put("tickets", 100);                  // maps key "tickets" to value 100
        Thread[] threads = new Thread[10];          // creates an array named threads
        for (int i = 0; i < threads.length; i++) {  // loops through all the indexes
            threads[i] = new Thread(() -> {
                for (int n = 0; n < 20; n++) {      // counting loop
                    sell();                         // calls the sell() method
                }
            });
            threads[i].start();
        }
        for (Thread t : threads) {                  // loops over every element of threads
            t.join();                               // waits for the thread to finish
        }
        System.out.println("Sold: " + sold.get() + ", left: " + stock.get("tickets"));  // prints the element or value read
    }
}
// OUTPUT:
// Sold: 100, left: 0

// Practice: predicting Hashtable enumeration order
import java.util.*;  // imports every class of java.util

public class HtPredictOrder {                 // class that holds the main method
    public static void main(String[] args) {  // program entry point
        int capacity = 11;                    // declares int capacity with value 11
        int[] keys = {3, 14, 25, 5, 16, 7};   // stores the value in keys

        // the real table
        Hashtable<Integer, String> table = new Hashtable<>();  // creates an empty Hashtable named table
        for (int k : keys) {                                   // loops over every element of keys
            table.put(k, "v" + k);                             // maps key k to value "v" + k
        }

        // our model: buckets with new entries added at the front
        List<LinkedList<Integer>> buckets = new ArrayList<>();  // creates an empty ArrayList named buckets
        for (int i = 0; i < capacity; i++) {                    // counting loop
            buckets.add(new LinkedList<>());                    // adds new LinkedList<>() to the end of the list
        }
        for (int k : keys) {                                    // loops over every element of keys
            int index = (Integer.hashCode(k) & 0x7FFFFFFF) % capacity;  // declares int index with value (Integer.hashCode(k...
            buckets.get(index).addFirst(k);                     // reads the element at index index).addFirst(k
            System.out.println("key " + k + " -> bucket " + index);  // prints a label followed by the value
        }

        List<Integer> predicted = new ArrayList<>();  // creates an empty ArrayList named predicted
        for (int i = capacity - 1; i >= 0; i--) {     // last bucket first
            predicted.addAll(buckets.get(i));         // chain from its head
        }

        List<Integer> real = Collections.list(table.keys());  // stores the value in real
        System.out.println("Predicted: " + predicted);        // prints a label followed by the value
        System.out.println("Real     : " + real);             // prints a label followed by the value
        System.out.println("Match    : " + predicted.equals(real));  // prints the comparison result

        int threshold = (int) (capacity * 0.75f);  // declares int threshold with value (int) (capacity * 0...
        System.out.println("Resize when size reaches " + threshold + "; new capacity = " + (capacity * 2 + 1));  // prints a label followed by the value
    }
}
// OUTPUT:
// key 3 -> bucket 3
// key 14 -> bucket 3
// key 25 -> bucket 3
// key 5 -> bucket 5
// key 16 -> bucket 5
// key 7 -> bucket 7
// Predicted: [7, 16, 5, 25, 14, 3]
// Real     : [7, 16, 5, 25, 14, 3]
// Match    : true
// Resize when size reaches 8; new capacity = 23

