// compareTo with a tie-breaker: district first, then name
import java.util.ArrayList;    // imports the ArrayList class
import java.util.Collections;  // imports the Collections class
import java.util.List;         // imports the List class

public class ComparableTieBreakDemo {       // class that holds the main method
    record Fort(String district, String name) implements Comparable<Fort> {  // Fort record implementing Comparable<Fort>
        public int compareTo(Fort other) {  // natural ordering: negative, zero or positive
            int byDistrict = district.compareTo(other.district);  // declares int byDistrict with value district.compareTo(...
            return byDistrict != 0 ? byDistrict : name.compareTo(other.name);  // tie: compare names
        }
    }

    public static void main(String[] args) {  // program entry point
        List<Fort> forts = new ArrayList<>(List.of(
                new Fort("Pune", "Torna"), new Fort("Raigad", "Raigad"), new Fort("Pune", "Lohagad")));
        Collections.sort(forts);              // sorts the list (natural order or the given comparator)
        System.out.println(forts);            // prints forts
    }
}
// OUTPUT:
// [Fort[district=Pune, name=Lohagad], Fort[district=Pune, name=Torna], Fort[district=Raigad, name=Raigad]]

// compareTo: students ranked by marks (high first), then name
public class CmpToMethodDemo {                                  // class that holds the main method
    record Student(String name, int marks) implements Comparable<Student> {  // Student record implementing Comparable<Student>
        public int compareTo(Student other) {                   // natural ordering: negative, zero or positive
            int byMarks = Integer.compare(other.marks, marks);  // swapped: higher marks first
            return byMarks != 0 ? byMarks : name.compareTo(other.name);  // tie: name A to Z
        }
    }

    public static void main(String[] args) {    // program entry point
        Student a = new Student("Aarav", 90);   // creates a Student object named a
        Student b = new Student("Diya", 85);    // creates a Student object named b
        Student c = new Student("Bhavna", 90);  // creates a Student object named c
        System.out.println("a vs b : " + Integer.signum(a.compareTo(b)));  // -1: a ranks before b
        System.out.println("a vs c : " + Integer.signum(a.compareTo(c)));  // -1: same marks, Aarav < Bhavna
        System.out.println("b vs a : " + Integer.signum(b.compareTo(a)));  // 1
    }
}
// OUTPUT:
// a vs b : -1
// a vs c : -1
// b vs a : 1

