// Employee payroll order: salary high to low, then name
import java.util.ArrayList;    // imports the ArrayList class
import java.util.Collections;  // imports the Collections class
import java.util.List;         // imports the List class
import java.util.TreeSet;      // imports the TreeSet class

public class CmpEmployeePayrollDemo {           // class that holds the main method
    record Employee(String name, String city, int salary) implements Comparable<Employee> {  // Employee record implementing Comparable<Employee>
        public int compareTo(Employee other) {  // natural ordering: negative, zero or positive
            int bySalary = Integer.compare(other.salary, salary);  // high first
            return bySalary != 0 ? bySalary : name.compareTo(other.name);  // tie-breaker
        }
    }

    public static void main(String[] args) {  // program entry point
        List<Employee> staff = new ArrayList<>(List.of(
                new Employee("Meera", "Pune", 70000), new Employee("Arjun", "Nagpur", 90000),
