        staff.forEach(e -> System.out.println(e.name() + " " + e.salary()));  // runs the given action for every element
        System.out.println("Unique in TreeSet: " + new TreeSet<>(staff).size());  // 4: nobody lost
    }
}
// OUTPUT:
// Arjun 90000
// Kabir 70000
// Meera 70000
// Sana 55000
// Unique in TreeSet: 4

// Product catalogue: natural order is price (cheap first), then product name
import java.util.TreeSet;  // imports the TreeSet class

public class CmpProductCatalogueDemo {                          // class that holds the main method
    record Product(String name, int price) implements Comparable<Product> {  // Product record implementing Comparable<Product>
        public int compareTo(Product other) {                   // natural ordering: negative, zero or positive
            int byPrice = Integer.compare(price, other.price);  // declares int byPrice with value Integer.compare(pri...
            return byPrice != 0 ? byPrice : name.compareTo(other.name);  // returns the comparison result
        }
    }

    public static void main(String[] args) {                    // program entry point
        TreeSet<Product> catalogue = new TreeSet<>();           // creates an empty TreeSet named catalogue
