// Student rank list: marks high first, equal marks share the same rank
import java.util.ArrayList;    // imports the ArrayList class
import java.util.Collections;  // imports the Collections class
import java.util.List;         // imports the List class

public class CmpStudentRankDemo {                               // class that holds the main method
    record Student(String name, int marks) implements Comparable<Student> {  // Student record implementing Comparable<Student>
        public int compareTo(Student other) {                   // natural ordering: negative, zero or positive
            int byMarks = Integer.compare(other.marks, marks);  // declares int byMarks with value Integer.compare(oth...
            return byMarks != 0 ? byMarks : name.compareTo(other.name);  // returns the comparison result
        }
    }

    public static void main(String[] args) {   // program entry point
        List<Student> list = new ArrayList<>(List.of(new Student("Diya", 88), new Student("Aarav", 95),
                new Student("Isha", 88), new Student("Rohan", 72)));
        Collections.sort(list);                // sorts the list (natural order or the given comparator)
        int rank = 0;                          // declares int rank with value 0
        int position = 0;                      // declares int position with value 0
        int previousMarks = -1;                // declares int previousMarks with value -1
        for (Student s : list) {               // loops over every element of list
            position++;                        // increments position
            if (s.marks() != previousMarks) {  // checks the condition
                rank = position;               // new marks value: rank jumps to position
                previousMarks = s.marks();     // assigns a new value to previousMarks
            }
            System.out.println("Rank " + rank + ": " + s.name() + " (" + s.marks() + ")");  // prints a label followed by the value
        }
    }
}
// OUTPUT:
// Rank 1: Aarav (95)
// Rank 2: Diya (88)
// Rank 2: Isha (88)
// Rank 4: Rohan (72)

// Sample project: Fort Register driven entirely by Comparable
import java.util.ArrayList;      // imports the ArrayList class
import java.util.Collections;    // imports the Collections class
import java.util.List;           // imports the List class
import java.util.PriorityQueue;  // imports the PriorityQueue class
import java.util.TreeSet;        // imports the TreeSet class

public class CmpFortRegisterProject {  // class that holds the main method
    // Step 1: the natural order lives inside the class
    record Fort(String district, int heightMetres, String name) implements Comparable<Fort> {  // Fort record implementing Comparable<Fort>
        @Override
        public int compareTo(Fort other) {  // natural ordering: negative, zero or positive
            int byDistrict = district.compareTo(other.district);  // district A to Z
            if (byDistrict != 0) {          // checks the condition
                return byDistrict;          // returns the result to the caller
            }
            int byHeight = Integer.compare(other.heightMetres, heightMetres);  // tallest first
            return byHeight != 0 ? byHeight : name.compareTo(other.name);  // tie-breaker
        }

        @Override
        public String toString() {  // text shown when the object is printed
            return district + "/" + name + "/" + heightMetres + "m";  // returns the result to the caller
        }
    }

    public static void main(String[] args) {  // program entry point
        // Step 2: load and sort
        List<Fort> register = new ArrayList<>(List.of(
                new Fort("Pune", 1403, "Torna"), new Fort("Raigad", 820, "Raigad"), new Fort("Pune", 1033, "Lohagad"),
                new Fort("Kolhapur", 845, "Panhala"), new Fort("Pune", 1374, "Purandar"), new Fort("Satara", 1000, "Ajinkyatara")));
        Collections.sort(register);                           // sorts the list (natural order or the given comparator)
        System.out.println("Sorted register:");               // prints the text "Sorted register:"
        register.forEach(f -> System.out.println("  " + f));  // runs the given action for every element

        // Step 3: neighbours in a TreeSet
        TreeSet<Fort> tree = new TreeSet<>(register);  // creates a TreeSet named tree copied from register
        Fort probe = new Fort("Pune", 1200, "");       // a spot between Torna-ish heights
        System.out.println("Before the probe : " + tree.lower(probe));  // prints the nearest element
        System.out.println("After the probe  : " + tree.ceiling(probe));  // prints the nearest element

        // Step 4: exact search on the sorted list
        int index = Collections.binarySearch(register, new Fort("Raigad", 820, "Raigad"));  // declares int index with value Collections.binaryS...
        System.out.println("Raigad is at position " + index);  // prints a label followed by the value

        // Step 5: next three with a heap, and the last with max
        PriorityQueue<Fort> queue = new PriorityQueue<>(register);  // creates a PriorityQueue named queue copied from register
        System.out.print("First three      : ");          // prints the text "First three      : "
        for (int i = 0; i < 3; i++) {                     // counting loop
            System.out.print(queue.poll().name() + " ");  // prints the removed element
        }
        System.out.println();                             // prints an empty line
        System.out.println("Last in the order: " + Collections.max(register));  // prints a label followed by the value
    }
}
// OUTPUT:
