// Practice: a three-level natural order used by sort, TreeSet and PriorityQueue
import java.util.ArrayList;      // imports the ArrayList class
import java.util.Collections;    // imports the Collections class
import java.util.List;           // imports the List class
import java.util.PriorityQueue;  // imports the PriorityQueue class
import java.util.TreeSet;        // imports the TreeSet class

public class FortRanking {                                      // class that holds the main method
    record Fort(String district, int heightMetres, String name) implements Comparable<Fort> {  // Fort record implementing Comparable<Fort>
        public int compareTo(Fort o) {                          // natural ordering: negative, zero or positive
            int c = district.compareTo(o.district);             // 1. district A to Z
            if (c != 0) {                                       // checks the condition
                return c;                                       // returns the result to the caller
            }
            c = Integer.compare(o.heightMetres, heightMetres);  // 2. higher first (arguments swapped)
            return c != 0 ? c : name.compareTo(o.name);         // 3. name
        }
    }

    public static void main(String[] args) {  // program entry point
        List<Fort> forts = new ArrayList<>(List.of(
                new Fort("Pune", 1033, "Lohagad"), new Fort("Raigad", 820, "Raigad"), new Fort("Pune", 1403, "Torna"),
                new Fort("Kolhapur", 845, "Panhala"), new Fort("Pune", 1374, "Purandar"), new Fort("Pune", 1403, "Torna")));

        Collections.sort(forts);        // sorts the list (natural order or the given comparator)
        System.out.println("Sorted:");  // prints the text "Sorted:"
        forts.forEach(f -> System.out.println("  " + f.district() + " | " + f.heightMetres() + " | " + f.name()));  // runs the given action for every element

        TreeSet<Fort> unique = new TreeSet<>(forts);  // creates a TreeSet named unique copied from forts
        System.out.println("List size " + forts.size() + ", unique forts " + unique.size());  // prints the number of elements

        PriorityQueue<Fort> queue = new PriorityQueue<>(forts);  // creates a PriorityQueue named queue copied from forts
        System.out.print("First three polled: ");         // prints the text "First three polled: "
        for (int i = 0; i < 3; i++) {                     // counting loop
            System.out.print(queue.poll().name() + " ");  // prints the removed element
        }
        System.out.println();                             // prints an empty line
    }
}
// OUTPUT:
// Sorted:
//   Kolhapur | 845 | Panhala
//   Pune | 1403 | Torna
//   Pune | 1403 | Torna
//   Pune | 1374 | Purandar
//   Pune | 1033 | Lohagad
//   Raigad | 820 | Raigad
// List size 6, unique forts 5
// First three polled: Panhala Torna Torna

// Practice: Comparable record, sort, binarySearch and max
import java.util.ArrayList;    // imports the ArrayList class
