// Practice: numeric part-by-part compareTo
import java.util.ArrayList;    // imports the ArrayList class
import java.util.Collections;  // imports the Collections class
import java.util.List;         // imports the List class

public class CmpPracticeVersion {                          // class that holds the main method
    static class Version implements Comparable<Version> {  // Version class implementing Comparable<Version>
        final String text;                                 // declares text of type String
        final int[] parts;                                 // declares parts of type int[]

        Version(String text) {                           // constructor
            this.text = text;                            // stores text in the field text
            String[] pieces = text.split("\\.");         // stores the value in pieces
            parts = new int[pieces.length];              // assigns a new value to parts
            for (int i = 0; i < pieces.length; i++) {    // loops through all the indexes
                parts[i] = Integer.parseInt(pieces[i]);  // stores Integer.parseInt(... at index i of parts
            }
        }

        @Override
        public int compareTo(Version other) {                // natural ordering: negative, zero or positive
            int longest = Math.max(parts.length, other.parts.length);  // declares int longest with value Math.max(parts.leng...
            for (int i = 0; i < longest; i++) {              // counting loop
                int mine = i < parts.length ? parts[i] : 0;  // missing part = 0
                int theirs = i < other.parts.length ? other.parts[i] : 0;  // declares int theirs with value i < other.parts.len...
                if (mine != theirs) {                        // checks the condition
                    return Integer.compare(mine, theirs);    // returns the comparison result
                }
            }
            return 0;                                        // returns the result to the caller
        }

        @Override
        public String toString() {  // text shown when the object is printed
            return text;            // returns the result to the caller
        }
    }

    public static void main(String[] args) {                // program entry point
        List<Version> versions = new ArrayList<>();         // creates an empty ArrayList named versions
        for (String v : new String[] {"1.9", "1.10", "1.2.1", "1.2", "2.0"}) {  // loops over every element of new String[] {"1.9", "1.10",...
            versions.add(new Version(v));                   // adds new Version(v) to the end of the list
        }
        Collections.sort(versions);                         // sorts the list (natural order or the given comparator)
        System.out.println("Numeric order : " + versions);  // prints a label followed by the value
        System.out.println("String compare 1.9 vs 1.10 : " + Integer.signum("1.9".compareTo("1.10")) + " (wrongly says 1.9 is bigger)");  // prints the comparison result
        System.out.println("1.2 vs 1.2.0  : " + new Version("1.2").compareTo(new Version("1.2.0")));  // prints the comparison result
        System.out.println("Newest        : " + Collections.max(versions));  // prints a label followed by the value
    }
}
// OUTPUT:
// Numeric order : [1.2, 1.2.1, 1.9, 1.10, 2.0]
// String compare 1.9 vs 1.10 : 1 (wrongly says 1.9 is bigger)
// 1.2 vs 1.2.0  : 0
// Newest        : 2.0

// Practice: compareTo, equals and hashCode use the same field
import java.util.HashSet;  // imports the HashSet class
import java.util.Set;      // imports the Set class
import java.util.TreeSet;  // imports the TreeSet class

public class CmpPracticeConsistent {                       // class that holds the main method
    static class Product implements Comparable<Product> {  // Product class implementing Comparable<Product>
        final String code;                                 // declares code of type String
        final String name;                                 // declares name of type String

        Product(String code, String name) {  // constructor
            this.code = code;                // stores code in the field code
            this.name = name;                // stores name in the field name
        }

        @Override
        public int compareTo(Product other) {   // natural ordering: negative, zero or positive
            return code.compareTo(other.code);  // only code
        }

        @Override
        public boolean equals(Object o) {  // decides when two objects are equal
            return o instanceof Product p && p.code.equals(code);  // only code
        }

        @Override
        public int hashCode() {      // hash code consistent with equals()
            return code.hashCode();  // only code
        }
    }

    public static void main(String[] args) {  // program entry point
        Product[] items = {new Product("P-1", "Torch"), new Product("P-2", "Rope"), new Product("P-1", "Torch XL")};  // stores the value in items
        Set<Product> tree = new TreeSet<>();  // creates an empty TreeSet named tree
        Set<Product> hash = new HashSet<>();  // creates an empty HashSet named hash
        for (Product p : items) {             // loops over every element of items
            tree.add(p);                      // adds p to the set (a duplicate is ignored)
            hash.add(p);                      // adds p to the set (a duplicate is ignored)
        }
        System.out.println("TreeSet size: " + tree.size() + ", HashSet size: " + hash.size());  // prints the number of elements
        try {                                 // code that may throw an exception
            items[0].compareTo(null);
        } catch (NullPointerException e) {    // handles NullPointerException
            System.out.println("compareTo(null) -> NullPointerException");  // prints the text "compareTo(null) -> NullPoin..."
        }
    }
}
// OUTPUT:
// TreeSet size: 2, HashSet size: 2
// compareTo(null) -> NullPointerException

// Practice: PriorityQueue and TreeSet driven by one three-level compareTo
import java.util.List;           // imports the List class
import java.util.PriorityQueue;  // imports the PriorityQueue class
import java.util.TreeSet;        // imports the TreeSet class

public class CmpPracticeScheduler {                             // class that holds the main method
    record Task(int priority, int dueDay, String name) implements Comparable<Task> {  // Task record implementing Comparable<Task>
        public int compareTo(Task other) {                      // natural ordering: negative, zero or positive
            int byPriority = Integer.compare(priority, other.priority);  // declares int byPriority with value Integer.compare(pri...
            if (byPriority != 0) {                              // checks the condition
                return byPriority;                              // returns the result to the caller
            }
            int byDue = Integer.compare(dueDay, other.dueDay);  // declares int byDue with value Integer.compare(due...
            return byDue != 0 ? byDue : name.compareTo(other.name);  // returns the comparison result
        }
    }

    public static void main(String[] args) {  // program entry point
        List<Task> tasks = List.of(new Task(2, 7, "Book Raigad trek"), new Task(1, 3, "Pay Torna fees"),
                new Task(3, 1, "Wash gear"), new Task(2, 4, "Pack bags"), new Task(1, 3, "Call Nashik guide"), new Task(2, 9, "Plan Pune stay"));

        PriorityQueue<Task> queue = new PriorityQueue<>(tasks);  // creates a PriorityQueue named queue copied from tasks
        int step = 1;               // declares int step with value 1
        while (!queue.isEmpty()) {  // runs until the collection is empty
            Task t = queue.poll();  // stores the result: removes and returns the head (null if empty)
            System.out.println(step++ + ". p" + t.priority() + " day " + t.dueDay() + " " + t.name());  // prints the result
        }

        TreeSet<Task> tree = new TreeSet<>(tasks);  // creates a TreeSet named tree copied from tasks
        System.out.println("ceiling(p2, day 5) : " + tree.ceiling(new Task(2, 5, "")).name());  // prints the nearest element
        System.out.println("priority-1 tasks   : " + tree.headSet(new Task(2, 0, ""), false).size());  // prints the number of elements
    }
}
// OUTPUT:
// 1. p1 day 3 Call Nashik guide
// 2. p1 day 3 Pay Torna fees
// 3. p2 day 4 Pack bags
// 4. p2 day 7 Book Raigad trek
// 5. p2 day 9 Plan Pune stay
// 6. p3 day 1 Wash gear
// ceiling(p2, day 5) : Book Raigad trek
// priority-1 tasks   : 2

