// Sample project: Employee Report Builder built on named Comparators
import java.util.ArrayList;      // imports the ArrayList class
import java.util.Collections;    // imports the Collections class
import java.util.Comparator;     // imports the Comparator class
import java.util.LinkedHashMap;  // imports the LinkedHashMap class
import java.util.List;           // imports the List class
import java.util.Map;            // imports the Map class
import java.util.TreeSet;        // imports the TreeSet class

public class CpEmployeeReportProject {  // class that holds the main method
    // Step 1: the data
    record Employee(int id, String name, String city, int salary, Double bonus) { }

    // Step 2: reusable comparators as named constants
    static final Comparator<Employee> BY_NAME = Comparator.comparing(Employee::name);  // stores the value in BY_NAME
    static final Comparator<Employee> BY_SALARY_DESC = Comparator.comparingInt(Employee::salary).reversed().thenComparing(BY_NAME);  // stores the value in BY_SALARY_DESC
    static final Comparator<Employee> BY_CITY_THEN_NAME = Comparator.comparing(Employee::city).thenComparing(BY_NAME);  // stores the value in BY_CITY_THEN_NAME
    static final Comparator<Employee> BY_BONUS_NULLS_LAST =
            Comparator.comparing(Employee::bonus, Comparator.nullsLast(Comparator.<Double>reverseOrder())).thenComparing(BY_NAME);  // calls comparing() on Comparator
    static final Comparator<Employee> BY_ID = Comparator.comparingInt(Employee::id);  // stores the value in BY_ID

    static String names(List<Employee> list) {  // method names()
        return list.stream().map(Employee::name).toList().toString();  // returns the result to the caller
    }

    public static void main(String[] args) {  // program entry point
        List<Employee> staff = List.of(
                new Employee(104, "Meera", "Pune", 70000, 5000.0), new Employee(101, "Arjun", "Nagpur", 90000, null),
                new Employee(103, "Kabir", "Mumbai", 70000, 8000.0), new Employee(105, "Sana", "Pune", 55000, null),
                new Employee(102, "Vikram", "Delhi", 82000, 2000.0));

        Map<String, Comparator<Employee>> reports = new LinkedHashMap<>();  // creates an empty LinkedHashMap named reports
        reports.put("By name", BY_NAME);                        // maps key "By name" to value BY_NAME
        reports.put("By salary (high first)", BY_SALARY_DESC);  // maps key "By salary (high first)" to value BY_SALARY_DESC
        reports.put("By city, then name", BY_CITY_THEN_NAME);   // maps key "By city, then name" to value BY_CITY_THEN_NAME
        reports.put("By bonus (none last)", BY_BONUS_NULLS_LAST);  // maps key "By bonus (none last)" to value BY_BONUS_NULLS_LAST

        // Step 3: run every report on its own copy
        for (Map.Entry<String, Comparator<Employee>> r : reports.entrySet()) {  // loops over every element of reports.entrySet()
            List<Employee> copy = new ArrayList<>(staff);  // creates an ArrayList named copy copied from staff
            copy.sort(r.getValue());                       // sorts using the given comparator
            System.out.println(r.getKey() + ": " + names(copy));  // prints the result
        }

        // Step 4: questions answered with the comparators
        System.out.println("Top 2 paid : " + names(staff.stream().sorted(BY_SALARY_DESC).limit(2).toList()));  // prints a label followed by the value
        System.out.println("Lowest paid: " + Collections.min(staff, Comparator.comparingInt(Employee::salary)).name());  // prints a label followed by the value

        // Step 5: lookups
        List<Employee> byId = new ArrayList<>(staff);  // creates an ArrayList named byId copied from staff
        byId.sort(BY_ID);                              // sorts using the given comparator
        int at = Collections.binarySearch(byId, new Employee(103, "", "", 0, null), BY_ID);  // declares int at with value Collections.binaryS...
        System.out.println("Employee 103 is " + byId.get(at).name());  // prints the element or value read
        TreeSet<Integer> bands = new TreeSet<>(List.of(50000, 75000, 100000));  // creates a TreeSet filled with the listed values
        System.out.println("Next band above 82000 is " + bands.higher(82000));  // prints the nearest element
    }
}
// OUTPUT:
// By name: [Arjun, Kabir, Meera, Sana, Vikram]
// By salary (high first): [Arjun, Vikram, Kabir, Meera, Sana]
// By city, then name: [Vikram, Kabir, Arjun, Meera, Sana]
// By bonus (none last): [Kabir, Meera, Vikram, Arjun, Sana]
// Top 2 paid : [Arjun, Vikram]
// Lowest paid: Sana
// Employee 103 is Kabir
// Next band above 82000 is 100000

