// MiniHashSet: the real design of java.util.HashSet in about 20 lines
import java.util.HashMap;  // imports the HashMap class

public class MiniHashSetDemo {                               // class that holds the main method
    static class MiniHashSet<E> {                            // declares the MiniHashSet class
        private static final Object PRESENT = new Object();  // shared dummy value
        private final HashMap<E, Object> map = new HashMap<>();  // creates an empty HashMap named map

        boolean add(E e) {                       // method add()
            return map.put(e, PRESENT) == null;  // true if the key was new
        }

        boolean contains(Object o) {    // method contains()
            return map.containsKey(o);  // returns the result to the caller
        }

        boolean remove(Object o) {            // method remove()
            return map.remove(o) == PRESENT;  // returns the result to the caller
        }

        int size() {            // method size()
            return map.size();  // returns the result to the caller
        }

        @Override
        public String toString() {           // text shown when the object is printed
            return map.keySet().toString();  // the elements are the keys
        }
    }

    public static void main(String[] args) {              // program entry point
        MiniHashSet<String> forts = new MiniHashSet<>();  // creates an empty MiniHashSet named forts
        System.out.println("add Raigad  : " + forts.add("Raigad"));  // prints the result of the add
        System.out.println("add Torna   : " + forts.add("Torna"));  // prints the result of the add
        System.out.println("add Raigad  : " + forts.add("Raigad"));  // duplicate
        System.out.println("contains Torna : " + forts.contains("Torna"));  // prints whether the element is present
        System.out.println("remove Torna   : " + forts.remove("Torna"));  // prints the removed element
        System.out.println("remove Torna   : " + forts.remove("Torna"));  // prints the removed element
        System.out.println("Set: " + forts + ", size " + forts.size());  // prints the number of elements
    }
}
// OUTPUT:
// add Raigad  : true
// add Torna   : true
// add Raigad  : false
// contains Torna : true
// remove Torna   : true
// remove Torna   : false
// Set: [Raigad], size 1

// A duplicate needs the same hashCode AND equals(); the old object is kept
import java.util.HashSet;  // imports the HashSet class
import java.util.Objects;  // imports the Objects class
import java.util.Set;      // imports the Set class

public class DuplicateCheckDemo {  // class that holds the main method
    static class Fort {            // declares the Fort class
        final String name;         // declares name of type String
        final String note;         // declares note of type String

        Fort(String name, String note) {  // constructor
            this.name = name;             // stores name in the field name
            this.note = note;             // stores note in the field note
        }

        @Override
        public boolean equals(Object o) {                       // decides when two objects are equal
            return o instanceof Fort f && f.name.equals(name);  // identity is the name only
        }

        @Override
        public int hashCode() {         // hash code consistent with equals()
            return Objects.hash(name);  // returns the result to the caller
        }

        @Override
        public String toString() {           // text shown when the object is printed
            return name + "(" + note + ")";  // returns the result to the caller
        }
    }

    public static void main(String[] args) {                 // program entry point
        Set<Fort> forts = new HashSet<>();                   // creates an empty HashSet named forts
        System.out.println("add first Raigad  : " + forts.add(new Fort("Raigad", "original")));  // prints the result of the add
        System.out.println("add second Raigad : " + forts.add(new Fort("Raigad", "replacement")));  // prints the result of the add
        System.out.println("Set keeps         : " + forts);  // prints a label followed by the value
    }
}
// OUTPUT:
// add first Raigad  : true
// add second Raigad : false
// Set keeps         : [Raigad(original)]

