// Sizing a HashSet like the copy-constructor does
import java.util.HashSet;  // imports the HashSet class
import java.util.List;     // imports the List class
import java.util.Set;      // imports the Set class

public class HashSetSizingDemo {              // class that holds the main method
    public static void main(String[] args) {  // program entry point
        List<String> forts = List.of("Raigad", "Torna", "Lohagad", "Panhala", "Purandar", "Sinhagad");  // forts is an immutable list of the listed values

        int capacity = Math.max((int) (forts.size() / .75f) + 1, 16);  // formula used by new HashSet<>(collection)
        System.out.println("6 elements -> initial capacity " + capacity);  // prints a label followed by the value

        Set<String> copy = new HashSet<>(forts);            // no resize needed
        System.out.println("copy size  : " + copy.size());  // prints the number of elements

        Set<String> presized = new HashSet<>(100);  // for ~75 elements without a resize
        System.out.println("presized   : " + presized.isEmpty());  // prints whether it is empty
    }
}
// OUTPUT:
// 6 elements -> initial capacity 16
