// One null is allowed; changing the set inside a for-each is not
import java.util.HashSet;   // imports the HashSet class
import java.util.Iterator;  // imports the Iterator class
import java.util.Set;       // imports the Set class

public class SetNullFailFastDemo {            // class that holds the main method
    public static void main(String[] args) {  // program entry point
        Set<String> forts = new HashSet<>();  // creates an empty HashSet named forts
        forts.add("Raigad");                  // adds "Raigad" to the set (a duplicate is ignored)
        forts.add(null);                      // adds null to the set (a duplicate is ignored)
        forts.add(null);                      // still one null
        System.out.println("size with null : " + forts.size());  // prints the number of elements
        forts.remove(null);                   // removes null from the set

        forts.addAll(java.util.List.of("Torna", "Lohagad", "Panhala"));  // adds every element of java.util.List.of("Torna", "Lohag... to the set
        try {                         // code that may throw an exception
            for (String f : forts) {  // loops over every element of forts
                forts.remove(f);      // structural change inside the loop
            }
        } catch (java.util.ConcurrentModificationException e) {  // handles java.util.ConcurrentModificationException
            System.out.println("remove in for-each -> ConcurrentModificationException");  // prints the text "remove in for-each -> Concu..."
        }

        Iterator<String> it = forts.iterator();  // stores the result: gets an iterator to walk the elements
        while (it.hasNext()) {                   // runs while the iterator has more elements
            if (it.next().startsWith("P")) {     // checks the condition
                it.remove();                     // the safe way
            }
        }
        forts.removeIf(f -> f.length() > 6);     // removes every element that matches the condition
        System.out.println("after safe removal: " + new java.util.TreeSet<>(forts));  // prints a label followed by the value
    }
}
// OUTPUT:
// size with null : 2
// remove in for-each -> ConcurrentModificationException
// after safe removal: [Raigad, Torna]

// The cost of a HashSet: a node per element; compare with a BitSet for small ints
import java.util.BitSet;   // imports the BitSet class
import java.util.HashSet;  // imports the HashSet class
import java.util.Set;      // imports the Set class

public class SetMemoryDemo {                  // class that holds the main method
    public static void main(String[] args) {  // program entry point
        int n = 100_000;                      // declares int n with value 100_000
        Set<Integer> set = new HashSet<>();   // creates an empty HashSet named set
        BitSet bits = new BitSet();           // creates an empty BitSet named bits
        for (int i = 0; i < n; i += 2) {      // counting loop
            set.add(i);                       // adds i to the set (a duplicate is ignored)
            bits.set(i);                      // calls set() on bits
        }
        System.out.println("HashSet contains 1000 : " + set.contains(1000) + ", 1001 : " + set.contains(1001));  // prints whether the element is present
        System.out.println("BitSet  contains 1000 : " + bits.get(1000) + ", 1001 : " + bits.get(1001));  // prints the element or value read
        System.out.println("BitSet size in bytes ~ " + bits.size() / 8 + " for " + bits.cardinality() + " numbers");  // prints the number of elements
        System.out.println("HashSet needs one Node object (about 32 bytes) per number, so ~" + set.size() * 32 / 1024 + " KB before the table");  // prints the number of elements
    }
}
// OUTPUT:
// HashSet contains 1000 : true, 1001 : false
// BitSet  contains 1000 : true, 1001 : false
// BitSet size in bytes ~ 16384 for 50000 numbers
// HashSet needs one Node object (about 32 bytes) per number, so ~1562 KB before the table

// A mutable element whose hashCode changes becomes unreachable
import java.util.HashSet;  // imports the HashSet class
import java.util.Objects;  // imports the Objects class
import java.util.Set;      // imports the Set class

public class MutableElementDemo {  // class that holds the main method
    static class Fort {            // declares the Fort class
        String name;               // declares name of type String

        Fort(String name) {    // constructor
            this.name = name;  // stores name in the field name
        }

        @Override
        public boolean equals(Object o) {                       // decides when two objects are equal
            return o instanceof Fort f && f.name.equals(name);  // returns the result to the caller
        }

        @Override
        public int hashCode() {         // hash code consistent with equals()
            return Objects.hash(name);  // returns the result to the caller
        }
    }

    public static void main(String[] args) {  // program entry point
        Set<Fort> set = new HashSet<>();      // creates an empty HashSet named set
        Fort fort = new Fort("Raigad");       // creates a Fort object named fort
        set.add(fort);                        // adds fort to the set (a duplicate is ignored)
        System.out.println("contains before change : " + set.contains(fort));  // prints whether the element is present

        fort.name = "Rajgad";  // hashCode changes while it is in the set
        System.out.println("contains after change  : " + set.contains(fort));  // prints whether the element is present
        System.out.println("size                   : " + set.size() + "  (it is still inside, but lost)");  // prints the number of elements
    }
}
// OUTPUT:
// contains before change : true
// contains after change  : false
// size                   : 1  (it is still inside, but lost)

// A constant hashCode: every key lands in one bucket, so equals() runs again and again
import java.util.HashSet;  // imports the HashSet class
import java.util.Set;      // imports the Set class

public class BadHashCodeExample {    // class that holds the main method
    static int badEqualsCalls = 0;   // stores the value in badEqualsCalls
    static int goodEqualsCalls = 0;  // stores the value in goodEqualsCalls

    static class BadKey {                                // declares the BadKey class
        final int id;                                    // declares id of type int
        BadKey(int id) {                                 // constructor
            this.id = id;                                // stores id in the field id
        }
        @Override
        public int hashCode() { return 1; }              // the same bucket for everyone
        @Override
        public boolean equals(Object o) {                // decides when two objects are equal
            badEqualsCalls++;                            // count the comparisons
            return o instanceof BadKey b && b.id == id;  // returns the result to the caller
        }
    }

    static class GoodKey {                                      // declares the GoodKey class
        final int id;                                           // declares id of type int
        GoodKey(int id) {                                       // constructor
            this.id = id;                                       // stores id in the field id
        }
        @Override
        public int hashCode() { return Integer.hashCode(id); }  // different buckets
        @Override
        public boolean equals(Object o) {                       // decides when two objects are equal
            goodEqualsCalls++;                                  // increments goodEqualsCalls
            return o instanceof GoodKey g && g.id == id;        // returns the result to the caller
        }
    }

    public static void main(String[] args) {  // program entry point
        Set<BadKey> bad = new HashSet<>();    // creates an empty HashSet named bad
        Set<GoodKey> good = new HashSet<>();  // creates an empty HashSet named good
        for (int i = 1; i <= 6; i++) {        // counting loop
            bad.add(new BadKey(i));           // adds new BadKey(i) to the set (a duplicate is ignored)
            good.add(new GoodKey(i));         // adds new GoodKey(i) to the set (a duplicate is ignored)
        }
        System.out.println("Sizes             : " + bad.size() + " and " + good.size());  // prints the number of elements
        System.out.println("equals() calls bad : " + badEqualsCalls);  // prints a label followed by the value
        System.out.println("equals() calls good: " + goodEqualsCalls);  // prints a label followed by the value
    }
}
// OUTPUT:
// Sizes             : 6 and 6
// equals() calls bad : 15
// equals() calls good: 0

// Changing an element that is inside a HashSet
import java.util.HashSet;  // imports the HashSet class
import java.util.Objects;  // imports the Objects class
import java.util.Set;      // imports the Set class

public class LostGroupExample {            // class that holds the main method
    static class Group {                   // declares the Group class
        String city;                       // not final: can change
        Group(String city) {               // constructor
            this.city = city;              // stores city in the field city
        }
        @Override
        public boolean equals(Object o) {  // decides when two objects are equal
            return o instanceof Group g && g.city.equals(city);  // returns the result to the caller
        }
        @Override
        public int hashCode() {            // hash code consistent with equals()
            return Objects.hash(city);     // returns the result to the caller
        }
    }

    public static void main(String[] args) {  // program entry point
        Set<Group> groups = new HashSet<>();  // creates an empty HashSet named groups
        Group pune = new Group("Pune");       // creates a Group object named pune
        groups.add(pune);                     // adds pune to the set (a duplicate is ignored)

        pune.city = "Nashik";  // hash code changes, bucket does not
        System.out.println("Wrong way : contains = " + groups.contains(pune) + ", size = " + groups.size());  // prints the number of elements

        pune.city = "Pune";    // change back so it can be found again
        groups.remove(pune);   // remove while the hash is correct
        pune.city = "Nashik";  // now it is safe to change
        groups.add(pune);      // add again under the new hash
        System.out.println("Right way : contains = " + groups.contains(pune) + ", size = " + groups.size());  // prints the number of elements
    }
}
// OUTPUT:
// Wrong way : contains = false, size = 1
// Right way : contains = true, size = 1

// SAMPLE PROJECT: MiniHashSet with buckets, collisions and resize
public class HandMadeHashSetDemo {           // class that holds the main method
    static class MiniHashSet {               // declares the MiniHashSet class
        static class Node {                  // declares the Node class
            final String value;              // declares value of type String
            Node next;                       // declares next of type Node
            Node(String value, Node next) {  // constructor
                this.value = value;          // stores value in the field value
                this.next = next;            // stores next in the field next
            }
        }

        private Node[] buckets = new Node[4];  // Step 1: start small to see a resize
        private int size;                      // field size of type int

        // Step 2: a very simple hash (the real one is String.hashCode plus bit spreading)
        private int indexFor(String value, int length) {  // method indexFor()
            int hash = 0;                                 // declares int hash with value 0
            for (char c : value.toCharArray()) {          // loops over every element of value.toCharArray()
                hash += c;                                // updates hash
            }
            return hash % length;                         // returns the result to the caller
        }

        boolean contains(String value) {      // method contains()
            for (Node n = buckets[indexFor(value, buckets.length)]; n != null; n = n.next) {
                if (n.value.equals(value)) {  // checks the condition
                    return true;              // returns the result to the caller
                }
            }
            return false;                     // returns the result to the caller
        }

        // Step 3: add, ignoring duplicates
        boolean add(String value) {                    // method add()
            if (contains(value)) {                     // checks the condition
                return false;                          // returns the result to the caller
            }
            if (size + 1 > buckets.length * 3 / 4) {   // Step 4: load factor 0.75
                resize();                              // calls the resize() method
            }
            int i = indexFor(value, buckets.length);   // declares int i with value indexFor(value, buc...
            buckets[i] = new Node(value, buckets[i]);  // insert at the head of the chain
            size++;                                    // increments size
            return true;                               // returns the result to the caller
        }

        private void resize() {                                // method resize()
            Node[] bigger = new Node[buckets.length * 2];      // stores the value in bigger
            for (Node head : buckets) {                        // loops over every element of buckets
                for (Node n = head; n != null; n = n.next) {
                    int i = indexFor(n.value, bigger.length);  // new index for the new length
                    bigger[i] = new Node(n.value, bigger[i]);  // stores new Node(n.value,... at index i of bigger
                }
            }
            buckets = bigger;                                  // assigns a new value to buckets
            System.out.println("  -> resized to " + bigger.length + " buckets");  // prints a label followed by the value
        }

        // Step 5: print the buckets
        void show() {                                       // method show()
            for (int i = 0; i < buckets.length; i++) {      // loops through all the indexes
                StringBuilder chain = new StringBuilder();  // creates a StringBuilder object named chain
                for (Node n = buckets[i]; n != null; n = n.next) {
                    chain.append(chain.length() == 0 ? "" : " -> ").append(n.value);  // calls append() on chain
                }
                System.out.println("  bucket " + i + ": " + (chain.length() == 0 ? "(empty)" : chain));  // prints a label followed by the value
            }
        }
    }

    public static void main(String[] args) {  // program entry point
        MiniHashSet set = new MiniHashSet();  // creates an empty MiniHashSet named set
        String[] cities = {"Pune", "Nashik", "Nagpur", "Pune", "Indore", "Surat", "Thane"};  // stores the value in cities
        for (String city : cities) {          // loops over every element of cities
            System.out.println("add " + city + " -> " + set.add(city));  // prints the result of the add
        }
        System.out.println("Final layout (" + set.size + " elements):");  // prints a label followed by the value
        set.show();                           // calls show() on set
        System.out.println("contains Nagpur: " + set.contains("Nagpur"));  // prints whether the element is present
        System.out.println("contains Delhi : " + set.contains("Delhi"));  // prints whether the element is present
    }
}
// OUTPUT:
// add Pune -> true
// add Nashik -> true
// add Nagpur -> true
// add Pune -> false
//   -> resized to 8 buckets
// add Indore -> true
// add Surat -> true
// add Thane -> true
// Final layout (6 elements):
//   bucket 0: Thane -> Pune
//   bucket 1: Indore
//   bucket 2: (empty)
//   bucket 3: (empty)
//   bucket 4: (empty)
//   bucket 5: Nagpur
//   bucket 6: Nashik
//   bucket 7: Surat
// contains Nagpur: true
// contains Delhi : false

// Practice: the effect of a bad hashCode on a HashSet
import java.util.HashSet;  // imports the HashSet class
import java.util.Set;      // imports the Set class

public class BadHashCodeEffect {                           // class that holds the main method
    record BadKey(int id) implements Comparable<BadKey> {  // BadKey record implementing Comparable<BadKey>
        public int hashCode() {                            // hash code consistent with equals()
            return 7;                                      // every key collides
        }

        public int compareTo(BadKey o) {       // natural ordering: negative, zero or positive
            return Integer.compare(id, o.id);  // returns the comparison result
        }
    }

    record GoodKey(int id) { }

    static int distinctBuckets(int[] hashes) {     // method distinctBuckets()
        Set<Integer> buckets = new HashSet<>();    // creates an empty HashSet named buckets
        for (int h : hashes) {                     // loops over every element of hashes
            buckets.add((h ^ (h >>> 16)) & 4095);  // the bucket index in a 4096-slot table
        }
        return buckets.size();                     // returns the result to the caller
    }

    public static void main(String[] args) {  // program entry point
        int n = 2000;                         // declares int n with value 2000
        int[] badHashes = new int[n];         // creates an array named badHashes
        int[] goodHashes = new int[n];        // creates an array named goodHashes
        Set<BadKey> bad = new HashSet<>();    // creates an empty HashSet named bad
        Set<GoodKey> good = new HashSet<>();  // creates an empty HashSet named good
        for (int i = 0; i < n; i++) {         // counting loop
            BadKey b = new BadKey(i);         // creates a BadKey object named b
            GoodKey g = new GoodKey(i);       // creates a GoodKey object named g
            badHashes[i] = b.hashCode();      // stores b.hashCode() at index i of badHashes
            goodHashes[i] = g.hashCode();     // stores g.hashCode() at index i of goodHashes
            bad.add(b);                       // adds b to the set (a duplicate is ignored)
            good.add(g);                      // adds g to the set (a duplicate is ignored)
        }
        System.out.println("BadKey  uses " + distinctBuckets(badHashes) + " bucket(s) for " + n + " keys");  // prints a label followed by the value
        System.out.println("GoodKey uses " + distinctBuckets(goodHashes) + " buckets for " + n + " keys");  // prints a label followed by the value

        int missing = 0;               // declares int missing with value 0
        for (int i = 0; i < n; i++) {  // counting loop
            if (!bad.contains(new BadKey(i)) || !good.contains(new GoodKey(i))) {  // checks whether the element is present
                missing++;             // increments missing
            }
        }
        System.out.println("Keys not found in either set: " + missing);  // prints a label followed by the value
    }
}
// OUTPUT:
// BadKey  uses 1 bucket(s) for 2000 keys
// GoodKey uses 2000 buckets for 2000 keys
// Keys not found in either set: 0

