// Practice: the bucket index calculation of HashMap / HashSet
import java.util.ArrayList;  // imports the ArrayList class
import java.util.List;       // imports the List class
import java.util.Map;        // imports the Map class
import java.util.TreeMap;    // imports the TreeMap class

public class BucketIndexCalculator {                    // class that holds the main method
    static int bucketOf(String key, int tableLength) {  // method bucketOf()
        int h = key.hashCode();                         // stores the result: computes the hash code
        h = h ^ (h >>> 16);                             // spread the high bits down
        return (tableLength - 1) & h;                   // table length is a power of two
    }

    public static void main(String[] args) {  // program entry point
        String[] cities = {"Pune", "Nashik", "Nagpur", "Indore", "Surat", "Thane", "Aurangabad", "Kolhapur"};  // stores the value in cities
        int tableLength = 16;                 // declares int tableLength with value 16

        Map<Integer, List<String>> buckets = new TreeMap<>();  // creates an empty TreeMap named buckets
        for (String city : cities) {                           // loops over every element of cities
            buckets.computeIfAbsent(bucketOf(city, tableLength), i -> new ArrayList<>()).add(city);  // computes the value for the key
        }

        int collisions = 0;                            // declares int collisions with value 0
        for (Map.Entry<Integer, List<String>> e : buckets.entrySet()) {  // loops over every element of buckets.entrySet()
            boolean shared = e.getValue().size() > 1;  // declares boolean shared with value e.getValue().size()...
            if (shared) {                              // checks the condition
                collisions++;                          // increments collisions
            }
            System.out.println("bucket " + e.getKey() + ": " + e.getValue() + (shared ? "  <- collision" : ""));  // prints a label followed by the value
        }
        System.out.println("Buckets used: " + buckets.size() + " of " + tableLength + ", collisions: " + collisions);  // prints the number of elements
    }
}
// OUTPUT:
// bucket 2: [Kolhapur]
// bucket 4: [Thane]
// bucket 8: [Nagpur]
// bucket 10: [Pune]
// bucket 11: [Surat]
// bucket 12: [Nashik, Indore]  <- collision
// bucket 13: [Aurangabad]
// Buckets used: 7 of 16, collisions: 1

// Step 1 and 2 by hand: from a key to a bucket number (capacity 16)
public class HashStepsDemo {         // class that holds the main method
    static int spread(Object key) {  // method spread()
        int h = key.hashCode();      // stores the result: computes the hash code
        return h ^ (h >>> 16);       // mix high bits into low bits (same as HashMap.hash)
    }

    public static void main(String[] args) {    // program entry point
        int capacity = 16;                      // declares int capacity with value 16
        for (String fort : new String[] {"Raigad", "Torna", "Lohagad", "Panhala", "Purandar"}) {  // loops over every element of new String[] {"Raigad", "Torn...
            int hash = spread(fort);            // declares int hash with value spread(fort)
            int index = (capacity - 1) & hash;  // (n - 1) & hash: the bucket number
            System.out.println(fort + "  hashCode=" + fort.hashCode() + "  bucket=" + index);  // prints the comparison result
        }
    }
}
// OUTPUT:
// Raigad  hashCode=-1854565232  bucket=5
// Torna  hashCode=80995626  bucket=9
// Lohagad  hashCode=2007676782  bucket=4
// Panhala  hashCode=867660331  bucket=12
// Purandar  hashCode=1806302587  bucket=2

// A bucket is a chain of nodes: the idea behind collisions
public class NodeDemo {    // class that holds the main method
    static class Node {    // declares the Node class
        final String key;  // declares key of type String
        int value;         // declares value of type int
        Node next;         // next node in the same bucket

        Node(String key, int value, Node next) {  // constructor
            this.key = key;                       // stores key in the field key
            this.value = value;                   // stores value in the field value
            this.next = next;                     // stores next in the field next
        }
    }

    public static void main(String[] args) {  // program entry point
        Node chain = new Node("Raigad", 6, new Node("Torna", 5, new Node("Lohagad", 2, null)));  // three keys in one bucket
        for (Node n = chain; n != null; n = n.next) {
            System.out.println(n.key + "=" + n.value + (n.next != null ? "  -> next" : "  -> end"));  // prints the result
        }
    }
}
// OUTPUT:
// Raigad=6  -> next
// Torna=5  -> next
// Lohagad=2  -> end

// MiniHashMap: put() and get() with a fixed 4 buckets, to show collisions
public class MiniHashMapDemo {  // class that holds the main method
    static class Node {         // declares the Node class
        final String key;       // declares key of type String
        int value;              // declares value of type int
        Node next;              // declares next of type Node

        Node(String key, int value) {  // constructor
            this.key = key;            // stores key in the field key
            this.value = value;        // stores value in the field value
        }
    }

    static class MiniHashMap {       // declares the MiniHashMap class
        Node[] table = new Node[4];  // the bucket array

        int indexFor(String key) {          // method indexFor()
            int h = key.hashCode();         // stores the result: computes the hash code
            h = h ^ (h >>> 16);             // spread
            return (table.length - 1) & h;  // bucket number
        }

        void put(String key, int value) {       // method put()
            int i = indexFor(key);              // declares int i with value indexFor(key)
            for (Node n = table[i]; n != null; n = n.next) {
                if (n.key.equals(key)) {        // same key: update
                    n.value = value;            // sets the field value of n
                    return;                     // ends the method
                }
            }
            Node fresh = new Node(key, value);  // new key: add at the front of the chain
            fresh.next = table[i];              // sets the field next of fresh
            table[i] = fresh;                   // stores fresh at index i of table
        }

        Integer get(String key) {         // method get()
            for (Node n = table[indexFor(key)]; n != null; n = n.next) {
                if (n.key.equals(key)) {  // checks the condition
                    return n.value;       // returns the result to the caller
                }
            }
            return null;                  // absent
        }

        void print() {                                // method print()
            for (int i = 0; i < table.length; i++) {  // loops through all the indexes
                StringBuilder row = new StringBuilder("bucket " + i + ": ");  // creates a StringBuilder object named row
                for (Node n = table[i]; n != null; n = n.next) {
                    row.append(n.key).append("=").append(n.value).append(" ");  // calls append() on row
                }
                System.out.println(row);              // prints row
            }
        }
    }

    public static void main(String[] args) {  // program entry point
        MiniHashMap map = new MiniHashMap();  // creates an empty MiniHashMap named map
