// Chain lengths with a good hash and with a hash that always returns 1
public class IhBadHashCodeDemo {                        // class that holds the main method
    static int bucketOf(int hashCode, int tableSize) {  // method bucketOf()
        int hash = hashCode ^ (hashCode >>> 16);        // declares int hash with value hashCode ^ (hashCod...
        return (tableSize - 1) & hash;                  // returns the result to the caller
    }

    static int longestChain(boolean badHash, int tableSize) {  // method longestChain()
        int[] counts = new int[tableSize];                     // creates an array named counts
        for (int i = 0; i < 100; i++) {                        // counting loop
            String key = "Fort-" + i;                          // stores the text "Fort-" + i in key
            int hashCode = badHash ? 1 : key.hashCode();       // bad: constant
            counts[bucketOf(hashCode, tableSize)]++;
        }
        int longest = 0;                                       // declares int longest with value 0
        for (int c : counts) {                                 // loops over every element of counts
            longest = Math.max(longest, c);                    // assigns a new value to longest
        }
        return longest;                                        // returns the result to the caller
    }

    public static void main(String[] args) {  // program entry point
        System.out.println("100 keys, 256 buckets, good hashCode: longest chain = " + longestChain(false, 256));  // prints a label followed by the value
        System.out.println("100 keys, 256 buckets, constant hash: longest chain = " + longestChain(true, 256));  // prints a label followed by the value
    }
}
// OUTPUT:
// 100 keys, 256 buckets, good hashCode: longest chain = 2
// 100 keys, 256 buckets, constant hash: longest chain = 100

