// How many resizes for 10 000 entries: default start vs presized
public class IhResizeCountDemo {                             // class that holds the main method
    static int resizesFor(int entries, int startCapacity) {  // method resizesFor()
        int capacity = startCapacity;                        // declares int capacity with value startCapacity
        int resizes = 0;                                     // declares int resizes with value 0
        for (int size = 1; size <= entries; size++) {        // counting loop
            if (size > capacity * 0.75) {                    // threshold crossed
                capacity *= 2;                               // updates capacity
                resizes++;                                   // increments resizes
            }
        }
        return resizes;                                      // returns the result to the caller
    }

    public static void main(String[] args) {                    // program entry point
        int entries = 10_000;                                   // declares int entries with value 10_000
        int needed = (int) (entries / 0.75f) + 1;               // capacity that avoids resizing
        int presized = Integer.highestOneBit(needed - 1) << 1;  // next power of two
        System.out.println("default start (16)  : " + resizesFor(entries, 16) + " resizes");  // prints a label followed by the value
        System.out.println("presized to " + presized + " : " + resizesFor(entries, presized) + " resizes");  // prints a label followed by the value
    }
}
// OUTPUT:
// default start (16)  : 10 resizes
// presized to 16384 : 0 resizes

