            }
        }

        // Step 2: the bucket array and bookkeeping
        private Node<K, V>[] table = newTable(4);  // stores the value in table
        private int size = 0;                      // stores the value in size

        @SuppressWarnings("unchecked")
        private static <K, V> Node<K, V>[] newTable(int n) {  // method newTable()
            return (Node<K, V>[]) new Node[n];                // returns the result to the caller
        }

        private static int hash(Object key) {          // method hash()
            int h = key == null ? 0 : key.hashCode();  // declares int h with value key == null ? 0 : k...
            return h ^ (h >>> 16);                     // returns the result to the caller
        }

        // Step 3: put = hash, index, search, update or append, maybe resize
        V put(K key, V value) {                               // method put()
            int hash = hash(key);                             // declares int hash with value hash(key)
            int index = (table.length - 1) & hash;            // declares int index with value (table.length - 1)...
            Node<K, V> last = null;                           // stores the value in last
            for (Node<K, V> n = table[index]; n != null; last = n, n = n.next) {
                if (n.hash == hash && java.util.Objects.equals(n.key, key)) {  // checks the condition
                    V old = n.value;                          // stores the value in old
                    n.value = value;                          // equal key: update
                    return old;                               // returns the result to the caller
                }
            }
            Node<K, V> fresh = new Node<>(hash, key, value);  // creates a Node object named fresh
            if (last == null) {                               // checks for null
                table[index] = fresh;                         // empty bucket
            } else {                                          // runs when the condition is false
                last.next = fresh;                            // append at the tail
            }
            if (++size > table.length * 0.75) {               // checks the condition
                resize();                                     // calls the resize() method
            }
            return null;                                      // returns the result to the caller
        }

        // Step 4: get and remove share the search
        V get(K key) {               // method get()
            int hash = hash(key);    // declares int hash with value hash(key)
            for (Node<K, V> n = table[(table.length - 1) & hash]; n != null; n = n.next) {
                if (n.hash == hash && java.util.Objects.equals(n.key, key)) {  // checks the condition
                    return n.value;  // returns the result to the caller
                }
            }
            return null;             // returns the result to the caller
        }

        boolean remove(K key) {                     // method remove()
            int hash = hash(key);                   // declares int hash with value hash(key)
            int index = (table.length - 1) & hash;  // declares int index with value (table.length - 1)...
            Node<K, V> previous = null;             // stores the value in previous
            for (Node<K, V> n = table[index]; n != null; previous = n, n = n.next) {
                if (n.hash == hash && java.util.Objects.equals(n.key, key)) {  // checks the condition
                    if (previous == null) {         // checks for null
                        table[index] = n.next;      // stores n.next at index index of table
                    } else {                        // runs when the condition is false
                        previous.next = n.next;     // sets the field next of previous
                    }
                    size--;                         // decrements size
                    return true;                    // returns the result to the caller
                }
            }
            return false;                           // returns the result to the caller
        }

        // Step 5: double the table and put every node in its new bucket
        private void resize() {                               // method resize()
            Node<K, V>[] old = table;                         // stores the value in old
            table = newTable(old.length * 2);                 // assigns a new value to table
            for (Node<K, V> head : old) {                     // loops over every element of old
                for (Node<K, V> n = head; n != null; ) {
                    Node<K, V> next = n.next;                 // stores the value in next
                    int index = (table.length - 1) & n.hash;  // declares int index with value (table.length - 1)...
                    n.next = table[index];                    // push onto the new bucket
                    table[index] = n;                         // stores n at index index of table
                    n = next;                                 // assigns a new value to n
                }
            }
        }

        void print() {                                // method print()
            System.out.println("size=" + size + " buckets=" + table.length);  // prints a label followed by the value
            for (int i = 0; i < table.length; i++) {  // loops through all the indexes
                if (table[i] != null) {               // checks for null
                    StringBuilder row = new StringBuilder("  [" + i + "]");  // creates a StringBuilder object named row
                    for (Node<K, V> n = table[i]; n != null; n = n.next) {
                        row.append(" ").append(n.key).append("=").append(n.value);  // calls append() on row
                    }
                    System.out.println(row);          // prints row
                }
            }
        }
    }

    public static void main(String[] args) {                 // program entry point
        SimpleHashMap<String, Integer> map = new SimpleHashMap<>();  // creates an empty SimpleHashMap named map
        String[] forts = {"Torna", "Raigad", "Lohagad"};     // stores the value in forts
        int[] hours = {5, 6, 2};                             // stores the value in hours
        for (int i = 0; i < forts.length; i++) {             // loops through all the indexes
            map.put(forts[i], hours[i]);                     // maps key forts[i] to value hours[i]
        }
        map.print();                                         // calls print() on map
        System.out.println("put(Torna, 9) returns old value " + map.put("Torna", 9));  // prints the result of the add
        for (String more : new String[] {"Panhala", "Purandar", "Sinhagad"}) {  // loops over every element of new String[] {"Panhala", "Pur...
            map.put(more, more.length());                    // crosses 0.75 x 4 and 0.75 x 8
        }
        map.print();                                         // calls print() on map
        System.out.println("get(Raigad)  = " + map.get("Raigad"));  // prints the element or value read
        System.out.println("remove(Raigad) = " + map.remove("Raigad") + ", get now = " + map.get("Raigad"));  // prints the element or value read
        System.out.println("get(null) = " + map.get(null));  // prints the element or value read
    }
}
// OUTPUT:
// size=3 buckets=4
//   [0] Lohagad=2
//   [1] Torna=5 Raigad=6
// put(Torna, 9) returns old value 5
// size=6 buckets=8
//   [1] Torna=9
//   [2] Purandar=8
//   [4] Panhala=7 Lohagad=2
//   [5] Raigad=6 Sinhagad=8
// get(Raigad)  = 6
// remove(Raigad) = true, get now = null
// get(null) = null

// Practice: a HashMap written from scratch (put, get, remove, resize)
public class MyHashMap {   // class that holds the main method
    static class Node {    // declares the Node class
        final String key;  // declares key of type String
        int value;         // declares value of type int
        Node next;         // declares next of type Node

        Node(String key, int value, Node next) {  // constructor
            this.key = key;                       // stores key in the field key
            this.value = value;                   // stores value in the field value
            this.next = next;                     // stores next in the field next
        }
    }

    private Node[] table = new Node[4];  // creates an array named table
    private int size = 0;                // stores the value in size

    private static int index(String key, int length) {  // method index()
        int h = key.hashCode();                         // stores the result: computes the hash code
        return (h ^ (h >>> 16)) & (length - 1);         // returns the result to the caller
    }

    void put(String key, int value) {               // method put()
        int i = index(key, table.length);           // declares int i with value index(key, table.le...
        for (Node n = table[i]; n != null; n = n.next) {
            if (n.key.equals(key)) {                // checks the condition
                n.value = value;                    // existing key: update
                return;                             // ends the method
            }
        }
        table[i] = new Node(key, value, table[i]);  // stores new Node(key, val... at index i of table
        if (++size > table.length * 0.75) {         // checks the condition
            resize();                               // calls the resize() method
        }
    }

    Integer get(String key) {         // method get()
        for (Node n = table[index(key, table.length)]; n != null; n = n.next) {
            if (n.key.equals(key)) {  // checks the condition
                return n.value;       // returns the result to the caller
            }
        }
        return null;                  // returns the result to the caller
    }

    boolean remove(String key) {             // method remove()
        int i = index(key, table.length);    // declares int i with value index(key, table.le...
        Node previous = null;                // stores the value in previous
        for (Node n = table[i]; n != null; previous = n, n = n.next) {
            if (n.key.equals(key)) {         // checks the condition
                if (previous == null) {      // checks for null
                    table[i] = n.next;       // it was the head of the chain
                } else {                     // runs when the condition is false
                    previous.next = n.next;  // unlink from the middle
                }
                size--;                      // decrements size
                return true;                 // returns the result to the caller
            }
        }
        return false;                        // returns the result to the caller
    }

    private void resize() {                           // method resize()
        Node[] bigger = new Node[table.length * 2];   // stores the value in bigger
        for (Node head : table) {                     // loops over every element of table
            for (Node n = head; n != null; n = n.next) {
                int i = index(n.key, bigger.length);  // declares int i with value index(n.key, bigger...
                bigger[i] = new Node(n.key, n.value, bigger[i]);  // stores new Node(n.key, n... at index i of bigger
            }
        }
        table = bigger;                               // assigns a new value to table
    }

    int longestChain() {                          // method longestChain()
        int longest = 0;                          // declares int longest with value 0
        for (Node head : table) {                 // loops over every element of table
            int length = 0;                       // declares int length with value 0
            for (Node n = head; n != null; n = n.next) {
                length++;                         // increments length
            }
            longest = Math.max(longest, length);  // assigns a new value to longest
        }
        return longest;                           // returns the result to the caller
    }

    public static void main(String[] args) {      // program entry point
        MyHashMap map = new MyHashMap();          // creates an empty MyHashMap named map
        String[] forts = {"Raigad", "Torna", "Lohagad", "Panhala", "Purandar", "Sinhagad", "Rajgad", "Pratapgad", "Visapur", "Shivneri"};  // stores the value in forts
        for (int i = 0; i < forts.length; i++) {  // loops through all the indexes
            map.put(forts[i], i + 1);             // maps key forts[i] to value i + 1
        }
        map.put("Torna", 99);                     // maps key "Torna" to value 99
        System.out.println("size=" + map.size + " capacity=" + map.table.length + " longest chain=" + map.longestChain());  // prints a label followed by the value
        System.out.println("get(Torna)    = " + map.get("Torna"));  // prints the element or value read
        System.out.println("remove(Torna) = " + map.remove("Torna") + ", again = " + map.remove("Torna"));  // prints the removed element
        System.out.println("get(Torna)    = " + map.get("Torna") + ", size=" + map.size);  // prints the element or value read
    }
}
// OUTPUT:
// size=10 capacity=16 longest chain=2
// get(Torna)    = 99
// remove(Torna) = true, again = false
// get(Torna)    = null, size=9

// Practice: bucket index = (n - 1) & spread(hash) for three capacities
public class IhPracticeBuckets {     // class that holds the main method
    static int spread(Object key) {  // method spread()
        int h = key.hashCode();      // stores the result: computes the hash code
        return h ^ (h >>> 16);       // returns the result to the caller
    }

    public static void main(String[] args) {  // program entry point
        String[] forts = {"Torna", "Raigad", "Lohagad", "Panhala"};  // stores the value in forts
        for (String fort : forts) {           // loops over every element of forts
            int b8 = 7 & spread(fort);        // declares int b8 with value 7 & spread(fort)
            int b16 = 15 & spread(fort);      // declares int b16 with value 15 & spread(fort)
            int b32 = 31 & spread(fort);      // declares int b32 with value 31 & spread(fort)
            System.out.println(fort + "  8->" + b8 + "  16->" + b16 + "  32->" + b32 + (b8 == b16 ? "  *" : ""));  // prints the result
        }
    }
}
// OUTPUT:
// Torna  8->1  16->9  32->25
// Raigad  8->5  16->5  32->5  *
// Lohagad  8->4  16->4  32->4  *
// Panhala  8->4  16->12  32->28

// Practice: counting collisions in a 16-bucket table
import java.util.ArrayList;  // imports the ArrayList class
import java.util.List;       // imports the List class
import java.util.Map;        // imports the Map class
import java.util.TreeMap;    // imports the TreeMap class

public class IhPracticeCollisions {                            // class that holds the main method
    public static void main(String[] args) {                   // program entry point
        String[] forts = {"Torna", "Raigad", "Lohagad", "Panhala", "Purandar", "Sinhagad", "Rajgad", "Pratapgad", "Shivneri", "Visapur"};  // stores the value in forts
        Map<Integer, List<String>> buckets = new TreeMap<>();  // creates an empty TreeMap named buckets
        for (String fort : forts) {                            // loops over every element of forts
            int h = fort.hashCode();                           // stores the result: computes the hash code
            int index = 15 & (h ^ (h >>> 16));                 // declares int index with value 15 & (h ^ (h >>> 16...
            buckets.computeIfAbsent(index, k -> new ArrayList<>()).add(fort);  // computes the value for the key
        }
        int shared = 0;                                        // declares int shared with value 0
        int longest = 0;                                       // declares int longest with value 0
        for (Map.Entry<Integer, List<String>> e : buckets.entrySet()) {  // loops over every element of buckets.entrySet()
            System.out.println("bucket " + e.getKey() + ": " + e.getValue());  // prints a label followed by the value
            if (e.getValue().size() > 1) {                     // checks the condition
                shared++;                                      // increments shared
            }
            longest = Math.max(longest, e.getValue().size());  // assigns a new value to longest
        }
        System.out.println("buckets used: " + buckets.size() + ", shared: " + shared + ", longest chain: " + longest);  // prints the number of elements
    }
}
// OUTPUT:
// bucket 2: [Purandar]
// bucket 4: [Lohagad, Pratapgad]
// bucket 5: [Raigad, Sinhagad]
// bucket 8: [Shivneri]
// bucket 9: [Torna, Rajgad]
// bucket 11: [Visapur]
// bucket 12: [Panhala]
// buckets used: 7, shared: 3, longest chain: 2

// Practice: a mutable key is lost, a record key is safe
import java.util.HashMap;  // imports the HashMap class
import java.util.Map;      // imports the Map class
import java.util.Objects;  // imports the Objects class

public class IhPracticeImmutableKey {  // class that holds the main method
    static class MutableKey {          // declares the MutableKey class
        String fort;                   // declares fort of type String

        MutableKey(String fort) {  // constructor
            this.fort = fort;      // stores fort in the field fort
        }

        @Override
        public boolean equals(Object o) {  // decides when two objects are equal
            return o instanceof MutableKey k && k.fort.equals(fort);  // returns the result to the caller
        }

        @Override
        public int hashCode() {         // hash code consistent with equals()
            return Objects.hash(fort);  // returns the result to the caller
        }
    }

    record TrekKey(String fort, String city) { }  // equals + hashCode generated, fields final

    public static void main(String[] args) {            // program entry point
        Map<MutableKey, String> bad = new HashMap<>();  // creates an empty HashMap named bad
        MutableKey k = new MutableKey("Torna");         // creates a MutableKey object named k
        bad.put(k, "5 hours");                          // maps key k to value "5 hours"
        k.fort = "Raigad";                              // sets the field fort of k
        System.out.println("mutable key lookup : " + bad.get(k));  // prints the element or value read

        Map<TrekKey, String> good = new HashMap<>();        // creates an empty HashMap named good
        good.put(new TrekKey("Torna", "Pune"), "5 hours");  // maps key new TrekKey("Torna", "Pune") to value "5 hours"
        System.out.println("record key lookup  : " + good.get(new TrekKey("Torna", "Pune")));  // prints the element or value read
        System.out.println("different city     : " + good.get(new TrekKey("Torna", "Nagpur")));  // prints the element or value read
    }
}
// OUTPUT:
// mutable key lookup : null
// record key lookup  : 5 hours
// different city     : null

// Practice: null value vs missing key; the null key sits in bucket 0
import java.util.HashMap;  // imports the HashMap class
import java.util.Map;      // imports the Map class

public class IhPracticeNulls {                           // class that holds the main method
    public static void main(String[] args) {             // program entry point
        Map<String, String> bookings = new HashMap<>();  // creates an empty HashMap named bookings
        bookings.put("Torna", null);                     // maps key "Torna" to value null
        bookings.put(null, "walk-in");                   // maps key null to value "walk-in"
        System.out.println("get(Torna)         : " + bookings.get("Torna"));  // prints the element or value read
        System.out.println("get(Missing)       : " + bookings.get("Missing"));  // prints the element or value read
        System.out.println("containsKey(Torna) : " + bookings.containsKey("Torna"));  // prints whether the element is present
        System.out.println("containsKey(Missing): " + bookings.containsKey("Missing"));  // prints whether the element is present
        System.out.println("null key bucket    : " + (15 & 0));  // prints a label followed by the value
        System.out.println("get(null)          : " + bookings.get(null));  // prints the element or value read
        System.out.println("getOrDefault(Torna): " + bookings.getOrDefault("Torna", "default") + "  (key exists, so the stored null wins)");  // prints the element or value read
        System.out.println("getOrDefault(Missing): " + bookings.getOrDefault("Missing", "default"));  // prints the element or value read
    }
}
// OUTPUT:
// get(Torna)         : null
// get(Missing)       : null
// containsKey(Torna) : true
// containsKey(Missing): false
// null key bucket    : 0
// get(null)          : walk-in
// getOrDefault(Torna): null  (key exists, so the stored null wins)
// getOrDefault(Missing): default

// Practice: the Java 8 resize split keeps order and equals a fresh rehash
import java.util.ArrayList;  // imports the ArrayList class
import java.util.List;       // imports the List class

public class IhPracticeResizeSplit {  // class that holds the main method
    static int spread(String key) {   // method spread()
        int h = key.hashCode();       // stores the result: computes the hash code
        return h ^ (h >>> 16);        // returns the result to the caller
    }

    static List<List<String>> emptyTable(int n) {      // method emptyTable()
        List<List<String>> table = new ArrayList<>();  // creates an empty ArrayList named table
        for (int i = 0; i < n; i++) {                  // counting loop
            table.add(new ArrayList<>());              // adds new ArrayList<>() to the end of the list
        }
        return table;                                  // returns the result to the caller
    }

    public static void main(String[] args) {  // program entry point
        String[] forts = {"Torna", "Raigad", "Lohagad", "Panhala", "Purandar", "Sinhagad", "Rajgad", "Pratapgad",
                    "Shivneri", "Visapur", "Sudhagad", "Tikona"};

        List<List<String>> small = emptyTable(8);  // stores the value in small
        for (String f : forts) {                   // loops over every element of forts
            small.get(7 & spread(f)).add(f);       // tail insertion keeps insertion order
        }

        List<List<String>> split = emptyTable(16);  // stores the value in split
        for (int i = 0; i < 8; i++) {               // counting loop
            for (String f : small.get(i)) {         // loops over every element of small.get(i)
                if ((spread(f) & 8) == 0) {         // checks the condition
                    split.get(i).add(f);            // low chain: stays
                } else {                            // runs when the condition is false
                    split.get(i + 8).add(f);        // high chain: moves by oldCapacity
                }
            }
        }

        List<List<String>> fresh = emptyTable(16);  // stores the value in fresh
        for (String f : forts) {                    // loops over every element of forts
            fresh.get(15 & spread(f)).add(f);       // reads the element at index 15 & spread(f)).add(f
        }

        System.out.println("split table equals fresh rehash: " + split.equals(fresh));  // prints the comparison result
        for (int i = 0; i < 16; i++) {      // counting loop
            if (!split.get(i).isEmpty()) {  // checks whether it is empty
                System.out.println("bucket " + i + ": " + split.get(i));  // prints the element or value read
            }
        }
    }
}
// OUTPUT:
// split table equals fresh rehash: true
// bucket 2: [Purandar]
// bucket 4: [Lohagad, Pratapgad]
// bucket 5: [Raigad, Sinhagad]
// bucket 8: [Shivneri]
// bucket 9: [Torna, Rajgad, Sudhagad]
// bucket 11: [Visapur]
// bucket 12: [Panhala]
// bucket 13: [Tikona]
